if (typeof window !== 'undefined') {
  window.cleanAcademicUnitTitle = cleanAcademicUnitTitle;
  window.cleanAcademicLessonTitle = cleanAcademicLessonTitle;
}

(function() {
  const oldToNewUnits = {};
  if (typeof units !== 'undefined') {
    // Deduplicate units by title
    const uniqueUnits = [];
    const seenTitles = new Set();
    units.forEach(u => {
      const normalizedTitle = (u.title || '').trim();
      if (!seenTitles.has(normalizedTitle)) {
        seenTitles.add(normalizedTitle);
        uniqueUnits.push(u);
      }
    });
    units.length = 0;
    units.push(...uniqueUnits);

    units.forEach((u, idx) => {
      u.originalId = u.id;
      oldToNewUnits[u.id] = idx + 1;
    });
  }

  if (typeof units !== 'undefined') {
    units.forEach((u, idx) => {
      u.id = idx + 1;
      if (u.title) {
        u.title = cleanAcademicUnitTitle(u.title);
      }
    });
  }

  if (typeof lessons !== 'undefined') {
    lessons.forEach(l => {
      l.originalUnitId = l.unitId;
      if (l.unitId && oldToNewUnits[l.unitId]) {
        l.unitId = oldToNewUnits[l.unitId];
      }
      if (l.title) {
        l.title = cleanAcademicLessonTitle(l.title);
      }
      if (l.konuAnlatimi && l.konuAnlatimi.baslik) {
        l.konuAnlatimi.baslik = l.konuAnlatimi.baslik.split(':').map((part, index) => {
          if (index === 0) return part;
          return cleanAcademicLessonTitle(part);
        }).join(':');
      }
    });
  }

  if (typeof rawTopics !== 'undefined') {
    rawTopics.forEach(t => {
      if (t.id && oldToNewUnits[t.id]) {
        t.id = oldToNewUnits[t.id];
      }
      if (t.title) {
        t.title = cleanAcademicUnitTitle(t.title);
      }
    });
  }
})();

