let APPROVED_USERS_WHITELIST = [];
try {
  const savedWhitelist = localStorage.getItem('amok_approved_users_whitelist');
  if (savedWhitelist) {
    APPROVED_USERS_WHITELIST = JSON.parse(savedWhitelist);
  }
  // Eski sürümlerden kalan tahmin edilebilir varsayılan kayıtları temizle.
  APPROVED_USERS_WHITELIST = (APPROVED_USERS_WHITELIST || []).filter(item => {
    const e = String(item && item.email || '').toLowerCase();
    const p = String(item && item.phone || '').replace(/\D/g, '');
    return !(e === 'test@gmail.com' || e === 'admin@gmail.com' || p === '5551234567' || p === '5559876543');
  });
} catch (e) {
  console.error('Failed to load whitelist from localStorage:', e);
  APPROVED_USERS_WHITELIST = [];
}

const isUserWhitelisted = (phone, email) => {
  if (!APPROVED_USERS_WHITELIST || APPROVED_USERS_WHITELIST.length === 0) return false;
  const clean = (val) => String(val || '').trim().toLowerCase().replace(/[\s\-()]/g, '');
  const cPhone = clean(phone);
  const cEmail = clean(email);
  
  let digitsPhone = cPhone.replace(/\D/g, '');
  if (digitsPhone.startsWith('90')) digitsPhone = digitsPhone.slice(2);
  else if (digitsPhone.startsWith('0')) digitsPhone = digitsPhone.slice(1);

  for (const item of APPROVED_USERS_WHITELIST) {
    const cItem = clean(item);
    if (cItem === cEmail) return true;
    if (cItem === cPhone) return true;
    
    let digitsItem = cItem.replace(/\D/g, '');
    if (digitsItem.startsWith('90')) digitsItem = digitsItem.slice(2);
    else if (digitsItem.startsWith('0')) digitsItem = digitsItem.slice(1);
    
    if (digitsItem && digitsItem === digitsPhone) return true;
  }
  return false;
};

function formatGrammarFormula(formulaHtml) {
  // Tokenize the formula by matching either bracketed expressions, the arrow operator, or the plus sign
  const regex = /(\[[^\]]+\]|➔|\+)/g;
  const tokens = formulaHtml.split(regex);
  
  const formattedTokens = tokens.map(token => {
    if (!token) return "";
    const trimmed = token.trim();
    if (!trimmed) return "";
    
    if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
      // It's a block segment! Strip the outer brackets for styling inside
      let innerText = trimmed.substring(1, trimmed.length - 1);
      // Highlight question mark (?) inside blocks as dotted lines
      innerText = innerText.replace(/\?/g, '<span class="formula-inner-var">.......</span>');
      // Highlight V1, V2, V3 etc.
      innerText = innerText.replace(/\b(V\d|V_)\b/g, '<span style="color: var(--accent-primary, #6366f1); font-weight: 800;">$1</span>');
      return `<div class="formula-block">${innerText}</div>`;
    } else if (trimmed === '+') {
      return `<div class="formula-connector">+</div>`;
    } else if (trimmed === '➔') {
      return `<div class="formula-arrow-connector">➔</div>`;
    } else {
      // Any text block outside the bracket expressions
      return `<div class="formula-text-node">${trimmed}</div>`;
    }
  });
  
  return `<div class="formula-container">${formattedTokens.join('')}</div>`;
}

function formatPromptWithTags(promptText) {
  if (!promptText) return "";
  
  // Find all code block ranges to ignore tags inside them
  const codeRanges = [];
  const codeRegex = /<code>([\s\S]*?)<\/code>/gi;
  let codeMatch;
  while ((codeMatch = codeRegex.exec(promptText)) !== null) {
    codeRanges.push([codeMatch.index, codeMatch.index + codeMatch[0].length]);
  }
  
  const regex = /\[([^\]]+)\]/g;
  
  // Filter out matches that are actually grammar formulas (containing +, ➔, ?, V_, V1/2/3, or Subject) or inside <code> blocks
  const matches = [...promptText.matchAll(regex)].filter(match => {
    const startIdx = match.index;
    const isInsideCode = codeRanges.some(range => startIdx >= range[0] && startIdx <= range[1]);
    if (isInsideCode) {
      return false;
    }
    
    const text = match[1];
    if (text.includes('+') || text.includes('➔') || text.includes('?') || /\bV\d\b/.test(text) || text.includes('V_') || text.toLowerCase().includes('subject')) {
      return false;
    }
    return true;
  });
  
  // Replace <code> formula text inside cleanPrompt with beautifully formatted HTML
  let cleanPrompt = promptText.replace(/<code>([\s\S]*?)<\/code>/gi, (match, p1) => {
    return `<code>${formatGrammarFormula(p1)}</code>`;
  });
  
  if (matches.length === 0) return cleanPrompt;
  
  const badgesHtml = matches.map(match => {
    return `<span class="prompt-tag-badge" style="display: inline-block; background: linear-gradient(135deg, var(--accent-primary, #6366f1) 0%, var(--accent-primary-hover, #4f46e5) 100%); color: #ffffff; font-size: 0.72rem; font-weight: 700; padding: 4px 10px; border-radius: 12px; margin: 2px; border: 1px solid rgba(255, 255, 255, 0.15); box-shadow: 0 2px 6px rgba(99, 102, 241, 0.2); vertical-align: middle;">🏷️ ${match[1]}</span>`;
  }).join('');
  
  matches.forEach(match => {
    cleanPrompt = cleanPrompt.replace(match[0], '');
  });
  cleanPrompt = cleanPrompt.trim();
  
  return `<div class="prompt-tags-wrapper" style="margin-bottom: 12px; display: flex; justify-content: center; flex-wrap: wrap; gap: 4px; width: 100%;">${badgesHtml}</div><div class="prompt-clean-text" style="font-weight: 700;">${cleanPrompt}</div>`;
}

function translatePromptToTurkish(prompt, question) {
  if (!prompt) return prompt;
  
  // Normalize line breaks
  const parts = prompt.split(/<br\s*\/?>/i);
  let mainText = parts[0].trim();
  
  // Decide whether to strip the sentence/extra info from the prompt
  let shouldStripSentence = false;
  if (question && question.type) {
    const stripTypes = [
      'fill-blank',
      'fill-blank-dropdown',
      'fill-blank-text',
      'multiple-fill-blank',
      'word-bank',
      'matching',
      'preposition-magnet',
      'double-preposition-magnet'
    ];
    if (stripTypes.includes(question.type)) {
      shouldStripSentence = true;
    }
  }

  // Remove trailing colon for mapping, but preserve it if present
  let hasColon = false;
  if (mainText.endsWith(':')) {
    hasColon = true;
    mainText = mainText.slice(0, -1).trim();
  }
  
  const translations = {
    "choose the correct grammatical form to complete the sentence": "Cümleyi tamamlamak için doğru dil bilgisi biçimini seçiniz",
    "is the following sentence grammatically correct according to zaman uyumu rules?": "Aşağıdaki cümle Zaman Uyumu kurallarına göre doğru mudur?",
    "select the correct choice that satisfies the syntax guidelines": "Sözdizimi kuralını sağlayan doğru seçeneği belirleyiniz",
    "reconstruct the sentence in english using the correct word blocks": "Doğru kelime bloklarını kullanarak cümleyi İngilizce olarak yeniden oluşturun",
    "reconstruct the sentence in turkish using the correct word blocks": "Doğru kelime bloklarını kullanarak cümleyi Türkçe olarak yeniden oluşturun",
    "match the clauses to form correct sentences": "Doğru cümleler oluşturmak için yan cümleleri eşleştirin",
    "translate the following sentence into turkish": "Aşağıdaki cümleyi Türkçe'ye çevirin",
    "is the following sentence grammatically correct according to modallar (modals) rules?": "Aşağıdaki cümle Modallar (Modals) kurallarına göre doğru mudur?",
    "select the correct clause to connect with the sentence logically": "Cümleyi mantıksal olarak bağlamak için doğru yan cümleyi seçiniz",
    "select the most suitable academic option for the context": "En uygun seçeneği belirleyiniz"
  };

  const lowerText = mainText.toLowerCase();
  let translatedText = null;

  if (translations[lowerText]) {
    translatedText = translations[lowerText];
  } else {
    // Check dynamic rules
    const isMatch = mainText.match(/^Is the following sentence grammatically correct according to (.+?) rules\??$/i);
    if (isMatch) {
      let ruleName = isMatch[1].trim();
      const ruleTranslations = {
        "zaman uyumu": "Zaman Uyumu",
        "koşul cümlecikleri (if clauses)": "Koşul Cümlecikleri (If Clauses)",
        "modallar (modals)": "Modallar (Modals)",
        "sıfat cümlecikleri (relative clauses)": "Sıfat Cümlecikleri (Relative Clauses)",
        "bağlaçlar": "Bağlaçlar",
        "geçmiş zaman modalları (perfect modals)": "Geçmiş Zaman Modalları (Perfect Modals)"
      };
      const trRule = ruleTranslations[ruleName.toLowerCase()] || ruleName;
      translatedText = `Aşağıdaki cümle ${trRule} kurallarına göre doğru mudur?`;
    }
  }

  if (translatedText) {
    if (shouldStripSentence) {
      return translatedText + (hasColon ? ":" : "");
    }
    parts[0] = translatedText + (hasColon ? ":" : "");
    return parts.join("<br>");
  }

  return prompt;
}

