// ============================================================
// ÜYELİK v2 — Supabase Auth oturumu (auth.uid()) tabanlı
// ------------------------------------------------------------
// Eski sistem kimliği istemciden 'username' ile alıyordu, sunucu yetkisi yoktu.
// Yeni sistem: gerçek Supabase oturumu → app_users tablosu → RLS (auth.uid() = id).
// ============================================================
function mvSlugify(s) {
  return String(s || 'user').toLowerCase()
    .replace(/ı/g, 'i').replace(/ğ/g, 'g').replace(/ü/g, 'u')
    .replace(/ş/g, 's').replace(/ö/g, 'o').replace(/ç/g, 'c')
    .replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '') || 'user';
}

function mvRowToState(row) {
  if (!row) return;
  state.authId = row.id;
  if (row.username) state.username = row.username;
  if (row.display_name) state.displayName = row.display_name;
  if (row.avatar_color) state.avatarColor = row.avatar_color;
  if (row.profile_photo) state.profilePhoto = row.profile_photo;
  state.xp = row.xp || 0;
  state.streak = row.streak || 0;
  state.hearts = (row.hearts == null ? MAX_HEARTS : row.hearts);
  state.completedLessons = row.completed_lessons || [];
  state.unlockedAchievements = row.unlocked_achievements || state.unlockedAchievements || [];
  if (typeof row.coins === 'number') state.coins = row.coins;
  state.licenceKey = row.licence_key || state.licenceKey || null;
  state.isGuest = false;
  // Oturum verisi geldikten sonra bağımlı arayüzleri tazele.
  try { if (typeof updateLicenceUI === 'function') updateLicenceUI(); } catch (e) {}
  try { if (typeof updateTopBar === 'function') updateTopBar(); } catch (e) {}
}

function mvStateToRow() {
  const full = `${state.firstName || ''} ${state.lastName || ''}`.trim();
  return {
    id: state.authId,
    username: state.username || null,
    display_name: state.displayName || full || state.username || null,
    avatar_color: state.avatarColor || '#8B7EC8',
    profile_photo: state.profilePhoto || null,
    xp: state.xp || 0,
    streak: state.streak || 0,
    hearts: state.hearts || 0,
    completed_lessons: state.completedLessons || [],
    unlocked_achievements: state.unlockedAchievements || [],
    coins: state.coins || 0,
    licence_key: state.licenceKey || null,
    last_seen_at: new Date().toISOString()
  };
}

function mvSyncUp() {
  if (!supabaseClient || !state.authId) return Promise.resolve();
  return supabaseClient.from('app_users')
    .upsert(mvStateToRow(), { onConflict: 'id' })
    .then(({ error }) => { if (error) console.error('mvSyncUp error:', error); });
}

let mvAuthPromise = null;
async function mvOnAuthenticated(session, fullName) {
  if (!session || !supabaseClient) return false;
  // İki kaynak (proceed + onAuthStateChange) aynı anda çağırabilir — tek çalıştır.
  if (mvAuthPromise) return mvAuthPromise;
  mvAuthPromise = (async () => {
    const uid = session.user.id;
    state.authId = uid;
    state.email = session.user.email || state.email;
    state.isGuest = false;

    let row = null;
    try {
      const res = await supabaseClient.from('app_users').select('*').eq('id', uid).maybeSingle();
      row = res.data;
    } catch (e) { console.error('mvOnAuthenticated load error:', e); }

    if (!row) {
      const base = mvSlugify(fullName || (session.user.email || 'user').split('@')[0]);
      const colors = ['#E88A9A', '#B4A7D6', '#8BC6A0', '#E8CB6E', '#8B7EC8', '#7EC8C8'];
      const color = colors[Math.floor(Math.random() * colors.length)];
      let uname = base;
      for (let i = 0; i < 3 && !row; i++) {
        const payload = {
          id: uid, username: uname, display_name: fullName || uname, avatar_color: color,
          xp: state.xp || 0, streak: state.streak || 0, hearts: state.hearts || MAX_HEARTS,
          completed_lessons: state.completedLessons || [],
          unlocked_achievements: state.unlockedAchievements || [], coins: state.coins || 0
        };
        // insert yerine upsert: eşzamanlı çağrı satırı önce oluşturduysa hata vermez.
        const up = await supabaseClient.from('app_users')
          .upsert(payload, { onConflict: 'id' }).select().maybeSingle();
        if (up.error) {
          if (up.error.code === '23505') { uname = `${base}${Math.floor(Math.random() * 9999)}`; continue; }
          console.error('mvOnAuthenticated upsert error:', up.error);
          row = payload; // en kötü ihtimalle yerel değerlerle devam et; saveState sonra senkron eder
          break;
        }
        row = up.data || payload;
      }
    }
    mvRowToState(row);
    await mvRefreshLicence();
    // Admin mi? (admin_uids tablosu → is_admin RPC)
    try {
      const { data: adm } = await supabaseClient.rpc('is_admin');
      state.isAdmin = adm === true;
    } catch (e) { state.isAdmin = false; }
    try { if (typeof updateLicenceUI === 'function') updateLicenceUI(); } catch (e) {}
    try { if (typeof updateAdminTabVisibility === 'function') updateAdminTabVisibility(); } catch (e) {}
    try { localStorage.setItem(STATE_KEY, JSON.stringify(state)); } catch (e) {}
    return true;
  })();
  try { return await mvAuthPromise; }
  finally { setTimeout(() => { mvAuthPromise = null; }, 2000); }
}

// Lisans kodunu sunucuda kullan (redeem_licence RPC). İmza/sır yok, DB doğrular.
async function mvRedeemLicence(code) {
  const clean = String(code || '').trim().toUpperCase();
  if (!supabaseClient) return { ok: false, error: 'Sunucu bağlantısı yok.' };
  if (!state.authId) return { ok: false, error: 'Önce e-posta ile giriş yapın.' };
  try {
    const { data, error } = await supabaseClient.rpc('redeem_licence', { p_code: clean });
    if (error) return { ok: false, error: error.message || 'Sunucu hatası.' };
    if (data && data.ok) {
      state.licenceKey = clean;
      state.licenceValidUntil = data.expires_at || null;
      return { ok: true, expires_at: data.expires_at };
    }
    return { ok: false, error: (data && data.error) || 'Lisans kullanılamadı.' };
  } catch (e) {
    console.error('mvRedeemLicence', e);
    return { ok: false, error: 'Beklenmeyen hata.' };
  }
}

// Girişte / periyodik: app_users.licence_key hâlâ geçerli mi? (my_licence_status RPC)
async function mvRefreshLicence() {
  if (!supabaseClient || !state.authId) return;
  try {
    const { data, error } = await supabaseClient.rpc('my_licence_status');
    if (error) { console.error('mvRefreshLicence', error); return; }
    if (data && data.premium) {
      state.licenceValidUntil = data.expires_at || null;
    } else {
      state.licenceKey = null;
      state.licenceValidUntil = null;
    }
  } catch (e) { console.error('mvRefreshLicence', e); }
}

async function mvRestoreSession() {
  if (!supabaseClient) return false;
  try {
    const { data } = await supabaseClient.auth.getSession();
    if (data && data.session) {
      await mvOnAuthenticated(data.session, state.displayName);
      return true;
    }
  } catch (e) { console.error('mvRestoreSession error:', e); }
  return false;
}

