// YARDIMCI FONKSİYONLAR
// ============================================================

// Güvenlik: XSS koruması için HTML escape fonksiyonu
function escapeHtml(str) {
  if (typeof str !== 'string') return str;
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

function escapeAttr(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Güvenlik: "avatar:<emoji>" biçimindeki profil fotoğrafı değerinden yalnızca
// emoji kısmını, HTML-escape edilmiş olarak döndürür. Sunucudaki profil satırı
// başka bir kullanıcı tarafından değiştirilebildiği için (RLS gevşekse) bu değer
// innerHTML'e ham gömülürse depolanan XSS'e yol açar.
function safeAvatarEmoji(photo) {
  const raw = String(photo || '').split(':').slice(1).join(':');
  return escapeHtml(raw);
}

// Güvenlik: profil fotoğrafı bir <img src="..."> içine gömülecekse, DB'den gelen
// değeri öznitelik bağlamında güvenli hale getirir.
function safeAvatarSrc(photo) {
  return escapeAttr(String(photo || ''));
}

// Güvenlik: Şifre hash'leme (SHA-256)
async function hashPassword(password) {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hashBuffer))
    .map(b => b.toString(16).padStart(2, '0')).join('');
}

function isLocalEnvironment() {
  return window.location.hostname === 'localhost' ||
         window.location.hostname === '127.0.0.1' ||
         window.location.protocol === 'file:';
}

function saveState(immediate = false) {
  if (state.username && state.username !== 'Misafir') {
    const original = state.username;
    let normalized = original.toLowerCase()
      .replace(/ı/g, 'i')
      .replace(/ğ/g, 'g')
      .replace(/ü/g, 'u')
      .replace(/ş/g, 's')
      .replace(/ö/g, 'o')
      .replace(/ç/g, 'c')
      .replace(/[^a-z0-9]/g, '_')
      .replace(/_+/g, '_');
    if (normalized.endsWith('_')) normalized = normalized.slice(0, -1);
    if (normalized.startsWith('_')) normalized = normalized.slice(1);
    if (!normalized) normalized = 'user';
    
    if (normalized !== original) {
      state.username = normalized;
    }
  }
  localStorage.setItem(STATE_KEY, JSON.stringify(state));

  // ÜYELİK v2: gerçek oturum varsa app_users tablosuna yaz (RLS: auth.uid() = id).
  if (state.authId && supabaseClient && !state.isGuest) {
    if (saveStateDebounceTimeout) { clearTimeout(saveStateDebounceTimeout); saveStateDebounceTimeout = null; }
    if (immediate) { mvSyncUp(); }
    else { saveStateDebounceTimeout = setTimeout(mvSyncUp, 3000); }
    return;
  }

  if (state.username && !state.isGuest) {
    if (supabaseClient) {
      const performSync = () => {
        const upsertData = {
          username: state.username,
          xp: state.xp || 0,
          streak: state.streak || 0,
          hearts: state.hearts || 0,
          completed_lessons: state.completedLessons || [],
          avatar_color: state.avatarColor || '#E88A9A'
        };
        if (state.licenceKey) {
          upsertData.licence_key = state.licenceKey;
        }
        supabaseClient
          .from('user_states')
          .upsert(upsertData, { onConflict: 'username' })
          .then(({ error }) => {
            if (error) console.error('Supabase state sync error:', error);
          });
        
        // Update user profile details in profiles table
        const profileUpdate = {
          last_seen_at: new Date().toISOString()
        };
        if (state.profilePhoto) {
          profileUpdate.profile_photo = state.profilePhoto;
        }
        const currentFullName = `${state.firstName || ''} ${state.lastName || ''}`.trim();
        profileUpdate.display_name = state.displayName || currentFullName || state.username;

        supabaseClient
          .from('profiles')
          .update(profileUpdate)
          .eq('username', state.username)
          .then(({ error }) => {
            if (error) console.error('Supabase profile details sync error:', error);
          });
      };

      if (saveStateDebounceTimeout) {
        clearTimeout(saveStateDebounceTimeout);
        saveStateDebounceTimeout = null;
      }

      if (immediate) {
        performSync();
      } else {
        saveStateDebounceTimeout = setTimeout(performSync, 3000);
      }
    } else {
      // Local Database sync to amok_user_states
      try {
        const localStates = JSON.parse(localStorage.getItem('amok_user_states') || '{}');
        const existing = localStates[state.username] || {};
        localStates[state.username] = {
          username: state.username,
          xp: state.xp || 0,
          streak: state.streak || 0,
          hearts: state.hearts || 0,
          completed_lessons: state.completedLessons || [],
          avatar_color: state.avatarColor || '#E88A9A',
          licence_key: state.licenceKey || existing.licence_key || '',
          lastSeen: new Date().toISOString()
        };
        localStorage.setItem('amok_user_states', JSON.stringify(localStates));
      } catch (e) {
        console.error('Local states sync error:', e);
      }
    }
  }
}

// Add tab unload handler to flush save state immediately
window.addEventListener('beforeunload', () => {
  if (saveStateDebounceTimeout) {
    saveState(true);
  }
});

function sendTelegramNotification(message) {
  const token = localStorage.getItem('amok_telegram_token') || '';
  const chatId = localStorage.getItem('amok_telegram_chat_id') || '';
  if (!token || !chatId) return;

  const url = `https://api.telegram.org/bot${token}/sendMessage`;
  fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      chat_id: chatId,
      text: message,
      parse_mode: 'Markdown'
    })
  }).catch(err => console.error('Telegram notification failed:', err));
}

function setUnitTheme(unitId) {
  if (unitId === null || unitId === undefined) {
    document.documentElement.removeAttribute('data-unit-theme');
  } else {
    // Map unitId to theme numbers 1-10
    const themeNum = unitId === 0 ? 10 : (((unitId - 1) % 10) + 1);
    document.documentElement.setAttribute('data-unit-theme', themeNum);
  }
}

function updateActiveUnitTheme() {
  // Find the first lesson that is not completed
  const nextLesson = lessons.find(l => !state.completedLessons.includes(l.id));
  if (nextLesson) {
    setUnitTheme(nextLesson.unitId);
  } else {
    setUnitTheme(null);
  }
}

function scrollToActiveUnit(behavior = 'smooth') {
  const nextLesson = lessons.find(l => !state.completedLessons.includes(l.id));
  const activeUnitId = nextLesson ? nextLesson.unitId : (units[0] ? units[0].id : null);
  if (activeUnitId !== null) {
    ensureUnitRendered(activeUnitId);
    const unitSection = document.querySelector(`.unit-section[data-unit-id="${activeUnitId}"]`);
    if (unitSection) {
      unitSection.scrollIntoView({ behavior: behavior, block: 'start' });
      homeScreenScrollY = window.scrollY;
      localStorage.setItem('amok_last_scroll_y', window.scrollY);
    }
  }
}

function ensureUnitRendered(unitId) {
  const pContainer = document.querySelector(`.unit-section[data-unit-id="${unitId}"] .unit-path-container`);
  if (pContainer && pContainer.dataset.rendered === "false") {
    renderUnitPathAndNodes(pContainer, unitId);
  }
}

function loadState() {
  const saved = localStorage.getItem(STATE_KEY);
  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      state = { ...state, ...parsed };
      
      const FAKE_USERNAMES = ['ahmet yılmaz', 'elif demir', 'can kaya', 'sarah connor', 'melis şen', 'john doe', 'buse kaya', 'mert yılmaz', 'deniz aksu', 'ahmet_yilmaz', 'elif_demir', 'can_kaya', 'sarah_connor', 'melis_sen'];
      if (state.following) {
        state.following = state.following.filter(f => f && f.username && !FAKE_USERNAMES.includes(f.username.toLowerCase().trim()));
      }
      if (state.followers) {
        state.followers = state.followers.filter(f => f && f.username && !FAKE_USERNAMES.includes(f.username.toLowerCase().trim()));
      }
    } catch (e) {
      console.error('State yükleme hatası, varsayılan state kullanılacak:', e);
      localStorage.removeItem(STATE_KEY);
    }
  }

  // Normalize username to prevent spaces vs underscores sync mismatch
  if (state.username && state.username !== 'Misafir') {
    const original = state.username;
    let normalized = original.toLowerCase()
      .replace(/ı/g, 'i')
      .replace(/ğ/g, 'g')
      .replace(/ü/g, 'u')
      .replace(/ş/g, 's')
      .replace(/ö/g, 'o')
      .replace(/ç/g, 'c')
      .replace(/[^a-z0-9]/g, '_')
      .replace(/_+/g, '_');
    if (normalized.endsWith('_')) normalized = normalized.slice(0, -1);
    if (normalized.startsWith('_')) normalized = normalized.slice(1);
    if (!normalized) normalized = 'user';
    
    if (normalized !== original) {
      state.username = normalized;
      localStorage.setItem(STATE_KEY, JSON.stringify(state));
    }
  }
  // Sync license key from local states if in local fallback mode
  if (!supabaseClient && state.username) {
    try {
      const localStates = JSON.parse(localStorage.getItem('amok_user_states') || '{}');
      if (localStates[state.username] && localStates[state.username].licence_key) {
        state.licenceKey = localStates[state.username].licence_key;
      }
    } catch (e) {
      console.error('Local states parse error in loadState:', e);
    }
  }
  if (!state.activeDomain) {
    state.activeDomain = 'history';
  }
  if (state.negationOn === undefined || state.negationOn === null) state.negationOn = false;
  if (state.modalSelectLevel12 === undefined || state.modalSelectLevel12 === null) state.modalSelectLevel12 = 'could';
  state.activePassiveMode = 'active';
  if (state.selectedSubjectIndex === undefined || state.selectedSubjectIndex === null || isNaN(parseInt(state.selectedSubjectIndex, 10))) {
    state.selectedSubjectIndex = 0;
  } else {
    state.selectedSubjectIndex = parseInt(state.selectedSubjectIndex, 10);
  }
  if (state.selectedVerbIndex === undefined || state.selectedVerbIndex === null || isNaN(parseInt(state.selectedVerbIndex, 10))) {
    state.selectedVerbIndex = 0;
  } else {
    state.selectedVerbIndex = parseInt(state.selectedVerbIndex, 10);
  }
  if (!state.selectedShieldId) {
    state.selectedShieldId = 'likely';
  }
  // Initialize daily tasks if missing or empty
  if (!state.dailyTasks || !state.dailyTasks.tasks || state.dailyTasks.tasks.length === 0) {
    state.dailyTasks = {
      lastResetDate: new Date().toDateString(),
      tasks: getInitialDailyTasks()
    };
  }
  // Initialize following/followers if missing
  if (!state.following) {
    state.following = [
      { username: 'Ahmet Yılmaz', xp: 450, streak: 5, avatarColor: '#E88A9A' },
      { username: 'Elif Demir', xp: 320, streak: 3, avatarColor: '#B4A7D6' }
    ];
  }
  if (!state.followers) {
    state.followers = [
      { username: 'Ahmet Yılmaz', xp: 450, streak: 5, avatarColor: '#E88A9A' },
      { username: 'Elif Demir', xp: 320, streak: 3, avatarColor: '#B4A7D6' },
      { username: 'Sarah Connor', xp: 180, streak: 12, avatarColor: '#8BC6A0' },
      { username: 'Melis Şen', xp: 90, streak: 2, avatarColor: '#E8CB6E' }
    ];
  }
  if (state.activeTheme === 'light') {
    state.activeTheme = 'canva';
    saveState();
  }

  migrateStoreEconomy();
}

function getUsers() {
  const u = localStorage.getItem(USERS_KEY);
  if (!u) return {};
  try {
    return JSON.parse(u);
  } catch (e) {
    console.error('Kullanıcı veritabanı bozuk, sıfırlanıyor:', e);
    localStorage.removeItem(USERS_KEY);
    return {};
  }
}

async function saveUser(username, password) {
  const users = getUsers();
  const hashedPassword = await hashPassword(password);
  users[username] = { password: hashedPassword, createdAt: new Date().toISOString() };
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
}

let _scrollLockY = 0;

function updateBodyScrollLock() {
  const homeScreen = document.getElementById('home-screen');
  const homeScreenActive = homeScreen && homeScreen.classList.contains('active');
  const hasModal = document.querySelector('.qp-modal-overlay') !== null;
  const quizScreen = document.getElementById('quiz-screen');
  const quizActive = quizScreen && quizScreen.classList.contains('active');
  const placementScreen = document.getElementById('placement-screen');
  const placementActive = placementScreen && placementScreen.classList.contains('active');

  const shouldLock = (homeScreenActive && hasModal) || quizActive || placementActive;
  const isLocked = document.body.classList.contains('no-scroll');

  if (shouldLock && !isLocked) {
    // Save current scroll position before locking
    _scrollLockY = window.scrollY;
    document.body.classList.add('no-scroll');
    document.documentElement.classList.add('no-scroll');
    // Pin body in place with negative top to prevent iOS bounce
    document.body.style.top = `-${_scrollLockY}px`;
    document.body.style.position = 'fixed';
    document.body.style.width = '100%';
    document.body.style.left = '0';
  } else if (!shouldLock && isLocked) {
    document.body.classList.remove('no-scroll');
    document.documentElement.classList.remove('no-scroll');
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.width = '';
    document.body.style.left = '';
    // Restore scroll position
    window.scrollTo(0, _scrollLockY);
  }
}

function showScreen(screenId) {
  if (autoAdvanceTimeout) {
    clearTimeout(autoAdvanceTimeout);
    autoAdvanceTimeout = null;
  }

  // If leaving home-screen, save scroll position
  const activeScreen = document.querySelector('.app-screen.active');
  if (activeScreen && activeScreen.id === 'home-screen' && activeScreen.id !== screenId) {
    homeScreenScrollY = window.scrollY;
    localStorage.setItem('amok_last_scroll_y', window.scrollY);
  }

  localStorage.setItem('amok_last_screen', screenId);
  if (screenId !== 'quiz-screen') {
    clearActiveQuizState();
  }

  // Scroll to top instantly before screen state changes
  if (screenId !== 'home-screen') {
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
  }

  document.querySelectorAll('.app-screen').forEach(s => s.classList.remove('active'));
  document.getElementById(screenId).classList.add('active');

  // If returning to home-screen, restore scroll position
  if (screenId === 'home-screen') {
    updateActiveUnitTheme();
    const lastScrollY = parseInt(localStorage.getItem('amok_last_scroll_y'), 10) || homeScreenScrollY;
    requestAnimationFrame(() => {
      window.scrollTo(0, lastScrollY);
    });
    setTimeout(() => {
      window.scrollTo(0, lastScrollY);
    }, 100);
    setTimeout(() => {
      window.scrollTo(0, lastScrollY);
    }, 300);
    setTimeout(checkAndShowReviewPrompt, 600);
  }

  // Update body scroll lock state based on active screen & overlays
  updateBodyScrollLock();

  // Dispatch resize event to force visual viewport calculations to update
  window.dispatchEvent(new Event('resize'));
}

function showToast(message, type = 'info') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 3000);
}

function isQuestionNew(q, parentObj = null) {
  if (!q) return false;
  const thirtySixHoursMs = 36 * 60 * 60 * 1000;
  const now = Date.now();

  const isRecent = (dateStr) => {
    if (!dateStr) return false;
    const parsed = Date.parse(dateStr);
    if (isNaN(parsed)) return false;
    const diff = now - parsed;
    return diff <= thirtySixHoursMs && diff >= -600000;
  };

  if (q.createdAt && isRecent(q.createdAt)) return true;
  if (parentObj && parentObj.createdAt && isRecent(parentObj.createdAt)) return true;
  return false;
}

function openQuestionPreview(title, questions, parentObj = null) {
  if (!questions || questions.length === 0) {
    showToast("Bu alıştırmada henüz soru bulunmuyor.", "info");
    return;
  }

  let resolvedLessonId = null;
  let resolvedExerciseId = null;
  if (parentObj) {
    if (parentObj.subtitle !== undefined) {
      resolvedLessonId = parentObj.id;
    } else {
      const foundLesson = lessons.find(l => l.exercises && l.exercises.some(ex => ex.id === parentObj.id));
      if (foundLesson) {
        resolvedLessonId = foundLesson.id;
        resolvedExerciseId = parentObj.id;
      }
    }
  }

  const overlay = document.createElement('div');
  overlay.className = 'qp-modal-overlay';

  let headerHtml = `
    <div class="qp-modal-header">
      <h3>👁️ ${title} — Soru Önizleme</h3>
      <button class="modal-close-btn" id="qp-close-btn" title="Kapat">✕</button>
    </div>
  `;

  let cardsHtml = questions.map((q, idx) => {
    const isNew = isQuestionNew(q, parentObj);
    let typeLabel = "Soru";
    let typeClass = "";
    let detailsHtml = "";

    switch (q.type) {
      case 'multiple-choice':
      case 'error-spotting':
      case 'context-clue':
      case 'chain-expansion-differential':
      case 'structural-deconstruction':
      case 'vector-velocity-shift':
      case 'titan-boundary-defense':
      case 'vagon-to-suffix-match':
      case 'reverse-engineering-translation':
      case 'suffix-decapitation':
      case 'spotlight':
      case 'true-false':
        typeLabel = q.type === 'spotlight' ? "Projektör / Öge Analizi (Spotlight)" : (q.type === 'true-false' ? "Doğru / Yanlış" : (q.isEngToTr ? "Çoktan Seçmeli (Eng -> Tr)" : "Çoktan Seçmeli (Tr -> Eng)"));
        typeClass = q.type === 'spotlight' ? "qp-type-wb" : (q.type === 'true-false' ? "qp-type-drop" : "qp-type-mc");
        const opts = (q.options || []).map((opt, oIdx) => {
          const isCorrect = oIdx === q.correctIndex;
          return `<div class="qp-option-card-full ${isCorrect ? 'correct' : ''}">
            <span class="qp-opt-letter">${String.fromCharCode(65 + oIdx)}</span>
            <span class="qp-opt-text">${opt}</span>
            ${isCorrect ? '<span class="qp-opt-check">✓ Doğru Cevap</span>' : ''}
          </div>`;
        }).join('');
        
        let sentenceHtml = '';
        if (q.sentence || q.enSentence) {
          sentenceHtml = `
            <div class="qp-detail-row">
              <span class="qp-detail-label">Cümle:</span>
              <span class="qp-detail-val" style="font-size: 1.15rem; font-weight: 600;">${q.sentence || q.enSentence}</span>
            </div>
          `;
        }

        detailsHtml = `
          ${sentenceHtml}
          <div class="qp-detail-row">
            <span class="qp-detail-label">Seçenekler:</span>
            <div class="qp-options-grid-full">${opts}</div>
          </div>
        `;
        break;

      case 'fill-blank-dropdown':
        typeLabel = "Açılır Menü Boşluk Doldurma";
        typeClass = "qp-type-drop";
        const dropOpts = (q.options || []).map((opt, oIdx) => {
          const isCorrect = oIdx === q.correctIndex;
          return `<div class="qp-option-card-full ${isCorrect ? 'correct' : ''}">
            <span class="qp-opt-letter">${String.fromCharCode(65 + oIdx)}</span>
            <span class="qp-opt-text">${opt}</span>
            ${isCorrect ? '<span class="qp-opt-check">✓ Doğru Cevap</span>' : ''}
          </div>`;
        }).join('');
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Cümle Şablonu:</span>
            <span class="qp-detail-val" style="font-size: 1.15rem; font-weight: 600;">"${q.sentence || translatePromptToTurkish(q.prompt, q) || ''}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Seçenekler:</span>
            <div class="qp-options-grid-full">${dropOpts}</div>
          </div>
        `;
        break;

      case 'fill-blank':
        typeLabel = "Butonlu Boşluk Doldurma";
        typeClass = "qp-type-fb";
        const fbOpts = (q.options || []).map((opt, oIdx) => {
          const isCorrect = oIdx === q.correctIndex;
          return `<div class="qp-option-card-full ${isCorrect ? 'correct' : ''}">
            <span class="qp-opt-letter">${String.fromCharCode(65 + oIdx)}</span>
            <span class="qp-opt-text">${opt}</span>
            ${isCorrect ? '<span class="qp-opt-check">✓ Doğru Cevap</span>' : ''}
          </div>`;
        }).join('');
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Cümle Şablonu:</span>
            <span class="qp-detail-val" style="font-size: 1.15rem; font-weight: 600;">"${q.sentence || translatePromptToTurkish(q.prompt, q) || ''}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Seçenekler:</span>
            <div class="qp-options-grid-full">${fbOpts}</div>
          </div>
        `;
        break;

      case 'vector-assembly':
        typeLabel = "Öğe Sıralama (vector-assembly)";
        typeClass = "qp-type-wb";
        const vectorScrambled = q.scrambled_elements.map(w => `<span class="qp-option-item">${w}</span>`).join('');
        const vectorCorrect = q.correct_sequence.join(' ');
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Cümle:</span>
            <span class="qp-detail-val">"${q.sentence}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Öğeler:</span>
            <div class="qp-options-list">${vectorScrambled}</div>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Doğru Sıralama:</span>
            <span class="qp-detail-val qp-correct">"${vectorCorrect}"</span>
          </div>
        `;
        break;

      case 'fill-blank-text':
        typeLabel = "Yazılı Boşluk Doldurma";
        typeClass = "qp-type-text";
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Cümle Şablonu:</span>
            <span class="qp-detail-val">"${q.sentence}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Doğru Kelime:</span>
            <span class="qp-detail-val qp-correct">${q.correct || q.correctAnswer}</span>
          </div>
        `;
        break;

      case 'word-bank':
        typeLabel = q.isEngToTr ? "Kelime Sıralama (Eng -> Tr)" : "Kelime Sıralama (Tr -> Eng)";
        typeClass = "qp-type-wb";
        const bankWords = q.words.map(w => `<span class="qp-option-item">${w}</span>`).join('');
        const correctPath = Array.isArray(q.correctOrder) ? q.correctOrder.join(' ') : q.correctOrder;
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Kaynak Cümle:</span>
            <span class="qp-detail-val">"${q.translation}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Kelimeler:</span>
            <div class="qp-options-list">${bankWords}</div>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Doğru Sıralama:</span>
            <span class="qp-detail-val qp-correct">"${correctPath}"</span>
          </div>
        `;
        break;

      case 'translation-text':
        typeLabel = q.isEngToTr ? "Yazılı Çeviri (Eng -> Tr)" : "Yazılı Çeviri (Tr -> Eng)";
        typeClass = "qp-type-trans";
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Doğru Çeviri:</span>
            <span class="qp-detail-val qp-correct">"${q.correctSentence}"</span>
          </div>
        `;
        break;

      case 'matching':
        typeLabel = "Eşleştirme Kartları";
        typeClass = "qp-type-match";
        const pairsHtml = q.pairs.map(p => `<span class="qp-option-item correct">${p.left} ⟷ ${p.right}</span>`).join('');
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Eşleşmeler:</span>
            <div class="qp-options-list">${pairsHtml}</div>
          </div>
        `;
        break;

      case 'multiple-fill-blank':
        typeLabel = "Çoklu Boşluk Doldurma";
        typeClass = "qp-type-multi";
        const correctsList = q.corrects.map(c => `<span class="qp-option-item correct">${c}</span>`).join(' ');
        detailsHtml = `
          <div class="qp-detail-row">
            <span class="qp-detail-label">Cümle Şablonu:</span>
            <span class="qp-detail-val">"${q.sentence}"</span>
          </div>
          <div class="qp-detail-row">
            <span class="qp-detail-label">Sırasıyla Cevaplar:</span>
            <div class="qp-options-list">${correctsList}</div>
          </div>
        `;
        break;
    }

    let finalLessonId = resolvedLessonId;
    let finalExerciseId = resolvedExerciseId;
    if (!finalLessonId) {
      const foundLesson = lessons.find(l => {
        if (l.questions && l.questions.some(qi => qi.id === q.id)) return true;
        if (l.exercises && l.exercises.some(ex => ex.questions && ex.questions.some(qi => qi.id === q.id))) return true;
        return false;
      });
      if (foundLesson) {
        finalLessonId = foundLesson.id;
        if (foundLesson.exercises) {
          const foundEx = foundLesson.exercises.find(ex => ex.questions && ex.questions.some(qi => qi.id === q.id));
          if (foundEx) finalExerciseId = foundEx.id;
        }
      }
    }
    
    let startBtnHtml = '';
    if (checkIsLocal() && finalLessonId) {
      startBtnHtml = `
        <button onclick="window.startLessonAtQuestion('${escapeHtml(finalLessonId)}', ${finalExerciseId ? `'${escapeHtml(finalExerciseId)}'` : 'null'}, '${escapeHtml(q.id)}')" class="btn btn-primary" style="font-size: 0.72rem; padding: 4px 10px; border-radius: 4px; border: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; margin-left: 10px; box-shadow: var(--shadow-sm);">
          ⚡ Bu Soruyu Çöz
        </button>
      `;
    }

    return `
      <div class="qp-question-card">
        <div class="qp-question-header">
          <span class="qp-qnumber">Soru #${idx + 1}</span>
          ${isNew ? '<span class="qp-new-badge" style="background: #ff3b30; color: #fff; font-size: 0.65rem; padding: 2px 6px; border-radius: 4px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; margin-left: 6px; display: inline-block; vertical-align: middle; line-height: 1.2;">YENİ</span>' : ''}
          <span class="qp-type-badge ${typeClass}">${typeLabel}</span>
          ${startBtnHtml}
        </div>
        <p class="qp-prompt">${translatePromptToTurkish(q.prompt, q)}</p>
        <div class="qp-details">
          ${detailsHtml}
        </div>
      </div>
    `;
  }).join('');

  overlay.innerHTML = `
    <div class="qp-modal">
      ${headerHtml}
      <div class="qp-modal-body">
        ${cardsHtml}
      </div>
    </div>
  `;

  document.body.appendChild(overlay);
  updateBodyScrollLock();

  const closeBtn = overlay.querySelector('#qp-close-btn');
  const closeModal = () => {
    overlay.classList.add('fade-out');
    setTimeout(() => {
      overlay.remove();
      updateBodyScrollLock();
    }, 200);
  };
  closeBtn.addEventListener('click', closeModal);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal();
  });
}

window.previewQuestionById = function(lessonId, questionId) {
  if (typeof lessons === 'undefined') {
    showToast("Dersler yüklenemedi.", "error");
    return;
  }
  let lesson = null;
  if (lessonId && lessonId !== 'N/A') {
    lesson = lessons.find(l => l.id.toString() === lessonId.toString());
  }
  
  // Dynamic bridge questions end with '_bridge', extract base ID if needed
  const baseQuestionId = (questionId && questionId.endsWith('_bridge')) 
    ? questionId.replace(/_bridge$/, '') 
    : questionId;

  let targetQuestion = null;
  const findInLesson = (l, searchId) => {
    const qs = getLessonQuestions(l);
    return qs.find(q => q && (q.id === searchId || q.id === `${searchId}_bridge`));
  };

  if (lesson) {
    targetQuestion = findInLesson(lesson, questionId) || findInLesson(lesson, baseQuestionId);
  }
  
  if (!targetQuestion) {
    for (const l of lessons) {
      const q = findInLesson(l, questionId) || findInLesson(l, baseQuestionId);
      if (q) {
        targetQuestion = q;
        lesson = l;
        break;
      }
    }
  }
  
  if (!targetQuestion) {
    showToast("İlgili soru bulunamadı. Veritabanından silinmiş veya değiştirilmiş olabilir.", "error");
    return;
  }
  
  openQuestionPreview(`${lesson ? (lesson.subtitle ? lesson.id + '. Ders (' + lesson.subtitle + ')' : lesson.title || lesson.id + '. Ders') : 'Soru Önizleme'}`, [targetQuestion], lesson);
};

window.copyReportAiPrompt = function(questionId, lessonTitle, errorType, userComment) {
  let targetQuestion = null;
  let targetLessonTitle = lessonTitle || '';
  
  if (typeof lessons !== 'undefined') {
    for (const l of lessons) {
      const qList = getLessonQuestions(l);
      const found = qList.find(q => q && q.id === questionId);
      if (found) {
        targetQuestion = found;
        if (!targetLessonTitle) {
          targetLessonTitle = l.subtitle ? `${l.id}. Ders (${l.subtitle})` : (l.title || `${l.id}. Ders`);
        }
        break;
      }
    }
  }

  const qClean = targetQuestion ? { ...targetQuestion } : {};
  delete qClean._dynamicType;

  const translatedError = typeof translateErrorType === 'function' ? translateErrorType(errorType) : errorType;

  const promptText = `[AMOK SORU HATA DÜZELTME TALİMATI]
Lütfen aşağıdaki sorudaki bildirilen hatayı veritabanında/kodda inceleyip düzelt:

- Soru ID: ${questionId}
- Ders / Konu: ${targetLessonTitle || 'Belirtilmedi'}
- Bildirilen Hata Türü: ${translatedError}
- Kullanıcı / Bildiren Yorumu: "${userComment || ''}"

${targetQuestion ? `Mevcut Soru Verisi (JSON):
\`\`\`json
${JSON.stringify(qClean, null, 2)}
\`\`\`` : ''}

Yapılması Gerekenler:
1. data.js veya ilgili müfredat dosyasında "${questionId}" ID'sine sahip soruyu bulun.
2. Kullanıcının belirttiği "${userComment}" açıklamasını dikkate alarak hatayı (çeviri, imla, yanlış cevap anahtarı index'i, seçenekler veya kelimeler) düzeltin.
3. Değişiklikleri ilgili dosyaya kaydedin.`;

  navigator.clipboard.writeText(promptText).then(() => {
    if (typeof showToast === 'function') {
      showToast('Antigravity için AI düzeltme promptu kopyalandı! 📋 IDE sohbetine yapıştırabilirsiniz.', 'success');
    } else {
      alert('AI Fix Prompt kopyalandı!');
    }
  }).catch(err => {
    console.error('Kopyalama hatası:', err);
    if (typeof showToast === 'function') {
      showToast('Kopyalama başarısız oldu.', 'error');
    }
  });
};

window.startLessonAtQuestion = function(lessonId, exerciseId, questionId) {
  // Close any popovers
  const popover = document.querySelector('.lesson-popover');
  if (popover) popover.remove();
  
  // Close the preview modal
  const qpModal = document.querySelector('.qp-modal-overlay');
  if (qpModal) qpModal.remove();

  // Call startLesson
  startLesson(lessonId, exerciseId);

  // Set the correct index
  const targetIdx = currentQuizQuestions.findIndex(q => q.id === questionId);
  if (targetIdx !== -1) {
    currentQuestionIndex = targetIdx;
  }
  
  // Dismiss topic/konuAnlatimi modal if open
  const konuModal = document.getElementById('konu-anlatimi-modal');
  if (konuModal) konuModal.remove();
  
  // Render the selected question
  renderQuestion();
};



// ============================================================
// GÜNLÜK GÖREVLER (DAILY TASKS) SİSTEMİ
// ============================================================
function getInitialDailyTasks() {
  return [
    { id: 'lessons', text: 'Bugün 2 ders tamamla', target: 2, current: 0, xpReward: 20, coinReward: 25, completed: false, claimed: false },
    { id: 'xp', text: 'Bugün 50 Puan kazan', target: 50, current: 0, xpReward: 15, coinReward: 20, completed: false, claimed: false },
    { id: 'perfect', text: '1 dersi hatasız tamamla', target: 1, current: 0, xpReward: 25, coinReward: 30, completed: false, claimed: false },
    { id: 'review', text: '1 Hızlı Tekrar testi çöz', target: 1, current: 0, xpReward: 15, coinReward: 20, completed: false, claimed: false },
    { id: 'shop', text: 'Mağazadan bir ürün satın al', target: 1, current: 0, xpReward: 10, coinReward: 10, completed: false, claimed: false }
  ];
}

function checkAndResetDailyTasks() {
  const today = new Date().toDateString();
  if (!state.dailyTasks || !state.dailyTasks.tasks || !Array.isArray(state.dailyTasks.tasks) || state.dailyTasks.lastResetDate !== today) {
    state.dailyTasks = {
      lastResetDate: today,
      tasks: getInitialDailyTasks()
    };
    saveState();
  }
}

function updateDailyTaskProgress(taskId, value) {
  if (!state.dailyTasks) return;
  checkAndResetDailyTasks();
  
  const task = state.dailyTasks.tasks.find(t => t.id === taskId);
  if (task && !task.completed) {
    task.current = Math.min(task.target, task.current + value);
    if (task.current >= task.target) {
      task.completed = true;
      claimDailyTaskReward(task);
    }
    saveState();
    renderDailyTasks();
  }
}

function claimDailyTaskReward(task) {
  if (task.claimed) return;
  task.claimed = true;
  state.xp += task.xpReward;
  const coinR = task.coinReward || 0;
  if (coinR) addCoins(coinR);
  saveState();
  updateTopBar();
  showToast(`Görev tamamlandı: ${task.text}! +${task.xpReward} Puan${coinR ? ` · +${coinR} 🪙` : ''} 🎉`, 'success');
  if (typeof confetti === 'function') {
    confetti({
      particleCount: 50,
      angle: 60,
      spread: 55,
      origin: { x: 0 }
    });
    confetti({
      particleCount: 50,
      angle: 120,
      spread: 55,
      origin: { x: 1 }
    });
  }
}

function renderDailyTasks() {
  const list = document.getElementById('daily-tasks-list');
  if (!list) return;

  checkAndResetDailyTasks();

  list.innerHTML = state.dailyTasks.tasks.map(task => {
    const progressPercent = Math.min(100, Math.round((task.current / task.target) * 100));
    const isCompleted = task.completed;

    return `
      <div class="daily-task-card ${isCompleted ? 'completed' : ''}" id="task-card-${task.id}">
        <div class="task-card-main">
          <div class="task-checkbox-wrap">
            <div class="task-checkbox">${isCompleted ? '✓' : ''}</div>
          </div>
          <div class="task-details">
            <span class="task-text">${task.text}</span>
            <div class="task-meta">
              <span class="task-progress-text">${task.current}/${task.target}</span>
              ${task.xpReward ? `<span class="task-reward">+${task.xpReward} XP</span>` : ''}
            </div>
            <div class="task-progress-bar-wrap">
              <div class="task-progress-bar" style="width: ${progressPercent}%"></div>
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

let dailyTasksTimerInterval = null;

function startDailyTasksTimer() {
  if (dailyTasksTimerInterval) {
    clearInterval(dailyTasksTimerInterval);
  }
  updateResetTimer();
  dailyTasksTimerInterval = setInterval(updateResetTimer, 1000);
}

function updateResetTimer() {
  const timerEl = document.getElementById('tasks-reset-timer');
  if (!timerEl) return;
  
  const now = new Date();
  const nextDay = new Date();
  nextDay.setHours(24, 0, 0, 0); // Next midnight
  
  const diffMs = nextDay - now;
  if (diffMs <= 0) {
    checkAndResetDailyTasks();
    renderDailyTasks();
    return;
  }
  
  const hours = Math.floor(diffMs / 3600000);
  const minutes = Math.floor((diffMs % 3600000) / 60000);
  const seconds = Math.floor((diffMs % 60000) / 1000);
  
  const pad = (num) => String(num).padStart(2, '0');
  timerEl.textContent = `Sıfırlanma: ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
}



// ============================================================
// STREAK SİSTEMİ
// ============================================================
function updateStreak() {
  const today = new Date().toDateString();
  if (state.lastActiveDate === today) return; // Bugün zaten güncellendi

  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);

  if (state.lastActiveDate === yesterday.toDateString()) {
    state.streak += 1;
  } else if (state.lastActiveDate !== today) {
    // Seri kırılacak — envanterde Seri Dondurucu varsa birini harcayıp seriyi koru
    const freezes = (state.inventory && state.inventory.streak_freeze) || 0;
    if (state.streak > 0 && freezes > 0) {
      state.inventory.streak_freeze = freezes - 1;
      if (state.inventory.streak_freeze <= 0) state.streakFreezeBought = false;
      state.streak += 1;
      if (typeof showToast === 'function') {
        showToast(`❄️ Seri Dondurucu kullanıldı! Serin korundu (${state.streak} gün). Kalan: ${state.inventory.streak_freeze}`, 'info');
      }
    } else {
      state.streak = 1; // Seri kırıldı, yeniden başla
    }
  }

  state.lastActiveDate = today;

  // Günlük giriş jeton ödülü — seri uzadıkça artar (maks. +40)
  if (state.lastCoinBonusDate !== today) {
    state.lastCoinBonusDate = today;
    const bonus = 15 + Math.min(25, (state.streak || 1) * 3);
    addCoins(bonus);
    if (typeof showToast === 'function') showToast(`Günlük giriş ödülü: +${bonus} 🪙`, 'success');
    if (typeof updateTopBar === 'function') updateTopBar();
  }

  saveState();
}

// ============================================================
// BAŞARIM SİSTEMİ (DEVRE DIŞI — UI'dan kaldırıldı, geri almak için
// bu bölümdeki yorumları ve renderAchievements/checkAchievements
// çağrılarını aktifleştirin)
// ============================================================
function checkAchievements() {
  const newlyUnlocked = [];

  achievements.forEach(ach => {
    if (state.unlockedAchievements.includes(ach.id)) return;
    if (ach.condition(state)) {
      state.unlockedAchievements.push(ach.id);
      newlyUnlocked.push(ach);
    }
  });

  if (newlyUnlocked.length > 0) {
    saveState();
  }

  return newlyUnlocked;
}

