function isLessonNew(lesson) {
  if (!lesson) return false;
  const thirtySixHoursMs = 36 * 60 * 60 * 1000;
  const now = Date.now();

  const isRecent = (dateStr) => {
    if (!dateStr) return false;
    const parsed = Date.parse(dateStr);
    if (isNaN(parsed)) return false;
    const diff = now - parsed;
    return diff <= thirtySixHoursMs && diff >= -600000;
  };

  if (lesson.createdAt && isRecent(lesson.createdAt)) {
    return true;
  }

  if (lesson.exercises && Array.isArray(lesson.exercises)) {
    for (const ex of lesson.exercises) {
      if (ex.createdAt && isRecent(ex.createdAt)) {
        return true;
      }
      if (ex.questions && Array.isArray(ex.questions)) {
        for (const q of ex.questions) {
          if (q.createdAt && isRecent(q.createdAt)) {
            return true;
          }
        }
      }
    }
  }

  if (lesson.questions && Array.isArray(lesson.questions)) {
    for (const q of lesson.questions) {
      if (q.createdAt && isRecent(q.createdAt)) {
        return true;
      }
    }
  }

  return false;
}

function renderUnitPathAndNodes(pContainer, unitId) {
  if (pContainer.dataset.rendered === "true") return;
  pContainer.dataset.rendered = "true";

  const unit = units.find(u => String(u.id) === String(unitId));
  if (!unit) return;

  const uIdx = units.findIndex(u => String(u.id) === String(unitId));
  const colorIndex = uIdx === -1 ? 1 : ((uIdx % 10) + 1);
  const totalInUnit = unit.lessons.length;
  const completedInUnit = unit.lessons.filter(lId => state.completedLessons.includes(lId)).length;

  const stepSize = window.innerWidth < 820 ? 95 : 130;
  const points = [];
  for (let idx = 0; idx < totalInUnit; idx++) {
    const u = unit.id;
    const phase = (u * 1.7) % (2 * Math.PI);
    const freq = 1.1 + (u * 0.1) % 0.6;
    const amp = 26 + (u * 2) % 6;
    const tilt = ((u % 3) - 1) * (0.8 + (u % 2));
    const centerIndex = (totalInUnit - 1) / 2;
    const offsetPercent = Math.sin(idx * freq + phase) * amp + (idx - centerIndex) * tilt;

    points.push({
      x: 50 + offsetPercent,
      y: idx * stepSize + (stepSize / 2)
    });
  }

  if (totalInUnit > 0) {
    let pathD = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i];
      const p1 = points[i + 1];
      const cy = (p0.y + p1.y) / 2;
      pathD += ` C ${p0.x} ${cy}, ${p1.x} ${cy}, ${p1.x} ${p1.y}`;
    }

    let progressD = "";
    const progressLimit = Math.min(totalInUnit - 1, completedInUnit);
    if (progressLimit > 0) {
      progressD = `M ${points[0].x} ${points[0].y}`;
      for (let i = 0; i < progressLimit; i++) {
         const p0 = points[i];
         const p1 = points[i + 1];
         const cy = (p0.y + p1.y) / 2;
         progressD += ` C ${p0.x} ${cy}, ${p1.x} ${cy}, ${p1.x} ${p1.y}`;
      }
    }

    const svgHTML = `
      <svg class="unit-path-svg" viewBox="0 0 100 ${totalInUnit * stepSize}" preserveAspectRatio="none">
        <path class="path-bg" d="${pathD}" />
        ${progressD ? `<path class="path-progress" d="${progressD}" />` : ''}
      </svg>
    `;
    pContainer.innerHTML = svgHTML;
  }

  unit.lessons.forEach((lId, idx) => {
    const lesson = lessons.find(l => l.id === lId);
    if (!lesson) return;

    const isCompleted = state.completedLessons.includes(lId);
    const isActive = !isCompleted && isLessonUnlocked(lId);
    const isLocked = !isCompleted && !isActive;

    const pt = points[idx];

    const nodeWrapper = document.createElement('div');
    nodeWrapper.className = 'lesson-node-wrapper';
    nodeWrapper.style.left = `${pt.x}%`;
    nodeWrapper.style.top = `${pt.y}px`;
    nodeWrapper.style.zIndex = `${100 + idx}`;

    let statusClass = 'locked';
    if (isCompleted) {
      statusClass = `completed unit-pin-color-${colorIndex}`;
    } else if (isActive) {
      statusClass = `active unit-pin-color-${colorIndex}`;
    }

    const illustrationContent = getLessonIllustration(lId, unit.id);

    let progressBadgeContent = '';
    const isNotUploadedLesson = (!lesson.exercises || lesson.exercises.length === 0 || lesson.exercises.every(ex => !ex.questions || ex.questions.length === 0)) && (!lesson.questions || lesson.questions.length === 0);
    if (isNotUploadedLesson) {
      progressBadgeContent = `<div class="node-progress-badge">0</div>`;
    } else if (lesson.exercises && lesson.exercises.length > 0) {
      const completedCount = lesson.exercises.filter(ex => state.completedLessons.includes(`${lesson.id}_${ex.id}`)).length;
      const totalCount = lesson.exercises.length;
      const isAllExCompleted = completedCount === totalCount;
      progressBadgeContent = `<div class="node-progress-badge ${isAllExCompleted ? 'completed' : ''}">
        ${completedCount}/${totalCount}
      </div>`;
    } else {
      const totalCount = 1;
      const completedCount = isCompleted ? 1 : 0;
      progressBadgeContent = `<div class="node-progress-badge ${isCompleted ? 'completed' : ''}">
        ${completedCount}/${totalCount}
      </div>`;
    }

    const isNew = isLessonNew(lesson);
    const activeBannerContent = ''; // Simgeler üzerinden Yeni butonu kaldırıldı.

    let lessonOriginalTagHTML = '';

    const labelPosClass = pt.x > 50 ? 'label-left' : 'label-right';

    nodeWrapper.innerHTML = `
      ${isActive ? '<div class="pulse-ring"></div>' : ''}
      ${activeBannerContent}
      <button class="lesson-node ${statusClass}" data-lesson-id="${lId}">
        <div class="pin-bg"></div>
        <div class="pin-inner">
          ${illustrationContent}
        </div>
        ${isLocked ? '<div class="pin-lock-badge">🔒</div>' : ''}
        ${progressBadgeContent}
      </button>
      <div class="lesson-node-label ${labelPosClass} ${isLocked ? 'label-blur-mask' : ''}">
        <strong>${lesson.title.replace(/(\([^)]+\))/g, `<span class="unit-text-color-${colorIndex}">$1</span>`)}</strong>
        ${lessonOriginalTagHTML}
        ${isNotUploadedLesson ? '<div class="lesson-not-uploaded-badge">⏳ Ders eklenmemiştir</div>' : ''}
      </div>
    `;

    const btn = nodeWrapper.querySelector('.lesson-node');
    btn.addEventListener('click', (e) => {
      e.stopPropagation();

      if (!hasLicenseOrTrialAccess(lId)) {
        showGuestBlockModal();
        return;
      }

      togglePopover(btn, lId, unit.id, pt.x, pt.y);
    });

    pContainer.appendChild(nodeWrapper);
  });
}

function ensureLessonRendered(lessonId) {
  const lesson = lessons.find(l => l.id === lessonId);
  if (!lesson) return;
  const unitId = lesson.unitId;
  const pContainer = document.querySelector(`.unit-section[data-unit-id="${unitId}"] .unit-path-container`);
  if (pContainer && pContainer.dataset.rendered === "false") {
    renderUnitPathAndNodes(pContainer, unitId);
  }
}



function renderLessonTree() {
  const container = document.getElementById('tree-container');
  container.innerHTML = `
    <svg style="position: absolute; width: 0; height: 0; overflow: hidden;">
      <defs>
        <linearGradient id="path-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="var(--accent-primary)" />
          <stop offset="100%" stop-color="var(--accent-primary-hover)" />
        </linearGradient>
        <linearGradient id="canva-path-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#5AB07F" />
          <stop offset="50%" stop-color="#439A68" />
          <stop offset="100%" stop-color="#2E754C" />
        </linearGradient>
        <linearGradient id="mint-path-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#76c893" />
          <stop offset="50%" stop-color="#52b788" />
          <stop offset="100%" stop-color="#34a0a4" />
        </linearGradient>
        <linearGradient id="sakura-path-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#ffb5a7" />
          <stop offset="50%" stop-color="#ff8fa3" />
          <stop offset="100%" stop-color="#c77dff" />
        </linearGradient>
        <linearGradient id="sunset-path-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#f4a261" />
          <stop offset="50%" stop-color="#e76f51" />
          <stop offset="100%" stop-color="#ffd166" />
        </linearGradient>
      </defs>
    </svg>
  `;

  // Dynamic injection of Formasyon Turu as starter lesson
  const isCompleted = state.formationTourCompleted;
  const buttonText = isCompleted ? "🔄 Turu Tekrarla" : "🚀 Turu Başlat";
  const btnClass = isCompleted ? "btn-formation-tour completed" : "btn-formation-tour";

  const tourBlock = document.createElement('div');
  tourBlock.className = 'formation-tour-hero-card compact minimal';
  tourBlock.innerHTML = `
    <div class="formation-tour-glow-bg"></div>
    <div class="formation-tour-content-wrap">
      <div class="formation-tour-left">
        <h3 class="formation-tour-title-compact">
          <span>🎓 Formasyon Turu</span>
          ${isCompleted ? '<span class="formation-tour-status-badge">Tamamlandı ✅</span>' : ''}
        </h3>
        <p class="formation-tour-desc-compact">
          amok'un metodolojisini, tüm soru tiplerini ve eğitim haritasını <strong>45 doğrusal soruda</strong> hızlıca keşfedin.
        </p>
      </div>
      <div class="formation-tour-btn-wrap">
        <button class="${btnClass}" id="btn-tree-start-formation">${buttonText}</button>
      </div>
    </div>
  `;
  container.appendChild(tourBlock);

  // Bind click
  const startBtn = tourBlock.querySelector('#btn-tree-start-formation');
  if (startBtn) {
    startBtn.addEventListener('click', () => {
      startFormationTour();
    });
  }

  const renderedUnits = [...units];

  const unitDisplayNames = {};
  renderedUnits.forEach((u, index) => {
    const cleanTitle = cleanAcademicUnitTitle(u.title);
    unitDisplayNames[u.id] = `Bölüm ${index + 1}: ${cleanTitle}`;
  });

  const observerOptions = {
    root: null,
    rootMargin: '500px 0px',
    threshold: 0
  };

  const observer = new IntersectionObserver((entries, self) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const section = entry.target;
        const pContainer = section.querySelector('.unit-path-container');
        const unitId = section.dataset.unitId;
        if (pContainer && pContainer.dataset.rendered === "false") {
          renderUnitPathAndNodes(pContainer, unitId);
        }
        self.unobserve(section);
      }
    });
  }, observerOptions);

  renderedUnits.forEach((unit, uIdx) => {
    const completedInUnit = unit.lessons.filter(lId => state.completedLessons.includes(lId)).length;
    const totalInUnit = unit.lessons.length;
    const progressPercent = Math.round((completedInUnit / totalInUnit) * 100);

    const isNotUploadedUnit = unit.lessons.every(lId => {
      const l = lessons.find(lesson => lesson.id === lId);
      return !l || ((!l.exercises || l.exercises.length === 0 || l.exercises.every(ex => !ex.questions || ex.questions.length === 0)) && (!l.questions || l.questions.length === 0));
    });
    let notUploadedBadgeHTML = '';
    if (isNotUploadedUnit) {
      notUploadedBadgeHTML = `
        <span class="unit-banner-not-uploaded-tag">
          <span class="tag-pulse-dot"></span>
          <span>Ders eklenmemiştir</span>
        </span>
      `;
    }

    let originalBadgeHTML = '';

    let extraBadgeHTML = '';
    const isStrictlyLocal = window.location.hostname === 'localhost' ||
                            window.location.hostname === '127.0.0.1' ||
                            window.location.protocol === 'file:';
    const extraUnitIds = [];
    if (isStrictlyLocal && extraUnitIds.includes(unit.id)) {
      extraBadgeHTML = `
        <span class="unit-banner-extra-tag">
          Ekstra
        </span>
      `;
    }

    let localTypesBadgeHTML = '';
    let localQuestionsBadgeHTML = '';
    let localLessonsBadgeHTML = '';

    const qTypes = new Set();
    let totalQuestions = 0;
    unit.lessons.forEach(lId => {
      const l = lessons.find(lesson => lesson.id === lId);
      if (l) {
        const qs = getLessonQuestions(l);
        totalQuestions += qs.length;
        qs.forEach(q => {
          if (q && q.type) {
            qTypes.add(q.type);
          }
        });
      }
    });

    if (isStrictlyLocal) {
      if (qTypes.size > 0) {
        const typesStr = Array.from(qTypes).join(',');
        localTypesBadgeHTML = `
          <span class="unit-banner-types-tag" style="cursor: pointer;" onclick="event.stopPropagation(); window.showQuestionTypesModal('${unitDisplayNames[unit.id].replace(/'/g, "\\'")}', '${typesStr}'.split(','))">
            ${qTypes.size} Soru Tipi
          </span>
        `;
      }
      localLessonsBadgeHTML = `
        <span class="unit-banner-lessons-tag">
          ${totalInUnit} Ders
        </span>
      `;
      localQuestionsBadgeHTML = `
        <span class="unit-banner-questions-tag">
          ${totalQuestions} Soru
        </span>
      `;
    }

    const unitSection = document.createElement('div');
    unitSection.className = 'unit-section';
    unitSection.dataset.unitId = unit.id;

    const banner = document.createElement('div');
    const colorIndex = (uIdx % 10) + 1;
    banner.className = `unit-banner unit-color-${colorIndex} ${isNotUploadedUnit ? 'not-uploaded-breath' : ''}`;
    
    const noDescUnitIds = [13, 17, 31, 32, 33, 34, 38, 36, 35, 37];
    const descCleaned = (unit.description || '').replace(/\s+,/g, ',');
    const descHTML = noDescUnitIds.includes(unit.id) ? '' : `<p>${descCleaned}</p>`;
    const unitPct = totalInUnit > 0 ? Math.round((completedInUnit / totalInUnit) * 100) : 0;
    banner.innerHTML = `
      <span class="unit-banner-icon-watermark" aria-hidden="true">${unit.icon || '📘'}</span>
      <div class="unit-banner-info">
        <h2 class="unit-banner-title-row">
          <span>${unitDisplayNames[unit.id]}</span>
          ${notUploadedBadgeHTML}
          ${originalBadgeHTML}
          ${extraBadgeHTML}
        </h2>
        ${(localTypesBadgeHTML || localLessonsBadgeHTML || localQuestionsBadgeHTML) ? `
          <div class="unit-banner-stats-row">
            ${localTypesBadgeHTML}
            ${localLessonsBadgeHTML}
            ${localQuestionsBadgeHTML}
          </div>
        ` : ''}
        ${descHTML}
      </div>
      <div class="unit-progress-container">
        <div class="unit-progress-ring" style="--pct: ${unitPct}%;">
          <div class="unit-progress-ring-inner">${completedInUnit}/${totalInUnit}</div>
        </div>
      </div>
    `;
    unitSection.appendChild(banner);

    banner.addEventListener('mouseenter', () => {
      setUnitTheme(unit.id);
    });
    banner.addEventListener('mouseleave', () => {
      updateActiveUnitTheme();
    });

    const pathContainer = document.createElement('div');
    pathContainer.className = `unit-path-container unit-path-color-${colorIndex}`;
    const stepSize = window.innerWidth < 820 ? 95 : 130;
    pathContainer.style.height = `${totalInUnit * stepSize}px`;
    pathContainer.dataset.rendered = "false";

    unitSection.appendChild(pathContainer);
    container.appendChild(unitSection);

    renderUnitPathAndNodes(pathContainer, unit.id);
  });
}

function getQuestionTypeLabel(type) {
  switch (type) {
    case 'multiple-choice':
    case 'vector-velocity-shift':
    case 'titan-boundary-defense':
    case 'vagon-to-suffix-match':
    case 'reverse-engineering-translation':
    case 'suffix-decapitation':
      return "Çoktan Seçmeli";
    case 'fill-blank-dropdown':
      return "Açılır Menü Boşluk Doldurma";
    case 'fill-blank':
      return "Butonlu Boşluk Doldurma";
    case 'vector-assembly':
      return "Öğe Sıralama (vector-assembly)";
    case 'fill-blank-text':
      return "Yazılı Boşluk Doldurma";
    case 'word-bank':
      return "Kelime Sıralama (Sözcük Kutusu)";
    case 'translation-text':
      return "Yazılı Çeviri";
    case 'matching':
      return "Eşleştirme";
    case 'multiple-fill-blank':
      return "Çoklu Boşluk Doldurma";
    case 'true-false':
      return "Doğru / Yanlış";
    case 'spotlight':
      return "Spotlight Seçimi";
    case 'swipe-question':
      return "Kaydırarak Seçim";
    case 'preposition-magnet':
      return "Preposition Magnet";
    case 'collocation-matching':
      return "Collocation Eşleştirme";
    default:
      return type;
  }
}

window.showQuestionTypesModal = showQuestionTypesModal;
function showQuestionTypesModal(title, typesList) {
  const modal = document.createElement('div');
  modal.className = 'custom-modal-overlay';
  modal.id = 'types-list-modal';
  
  const typesHtml = typesList.map(type => {
    const label = getQuestionTypeLabel(type);
    return `
      <div style="background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 8px 12px; font-weight: 600; color: var(--text-primary); font-size: 0.82rem; display: flex; align-items: center; gap: 8px;">
        <span style="display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--accent-primary, #8B7EC8); flex-shrink: 0;"></span>
        <span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" title="${escapeHtml(label)}">${escapeHtml(label)}</span>
        <span style="font-size: 0.68rem; color: var(--text-muted); font-family: monospace; margin-left: auto; flex-shrink: 0;">(${escapeHtml(type)})</span>
      </div>
    `;
  }).join('');

  modal.innerHTML = `
    <div class="custom-modal" style="max-width: 680px; width: 90%;">
      <div class="custom-modal-header">
        <h3>ℹ️ Bölüm Soru Tipleri</h3>
        <button class="modal-close-btn" id="btn-close-types-modal">&times;</button>
      </div>
      <div class="custom-modal-body" style="padding: 20px 24px;">
        <div style="font-size: 0.85rem; color: var(--text-muted); margin-bottom: 12px;">
          <strong>${escapeHtml(title)}</strong> bünyesinde yer alan toplam <strong>${typesList.length}</strong> farklı soru tipi aşağıda listelenmiştir:
        </div>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 8px;">
          ${typesHtml}
        </div>
      </div>
      <div class="custom-modal-footer">
        <button class="btn btn-secondary" id="btn-close-types-modal-footer" style="width: 100%;">Kapat</button>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  const close = () => modal.remove();
  document.getElementById('btn-close-types-modal').addEventListener('click', close);
  document.getElementById('btn-close-types-modal-footer').addEventListener('click', close);
  modal.addEventListener('click', (e) => {
    if (e.target === modal) close();
  });
}



// Birleştirilmiş dersler (ör. c59_l1 -> c58_l1) alıştırmalarını kaynak dersteki
// numaralarıyla taşıdığı için başlıkta "Alıştırma 1" yazan bir alıştırma listede
// 4. sırada görünebiliyor. Numarayı listedeki konumdan türeterek eşitliyoruz.
function correctExerciseNumber(lesson) {
  const title = (lesson && lesson.activeExerciseTitle) || '';
  if (!/Alıştırma\s*\d+/i.test(title) || !Array.isArray(lesson.exercises)) return title;
  const idx = lesson.exercises.findIndex(ex => ex.id === lesson.activeExerciseId);
  if (idx < 0) return title;
  return title.replace(/Alıştırma\s*\d+/i, `Alıştırma ${idx + 1}`);
}

// Ders panosunda aynı konu adı üst üste üç kez yazılıyordu: ders başlığında,
// alıştırma başlığında, bir de alıştırma açıklamasında. Aşağıdaki üç yardımcı
// tekrar eden kısmı ayıklar; ayırt edici kısım olduğu gibi kalır.
function titleWords(text) {
  return String(text || '')
    .replace(/<[^>]+>/g, ' ')
    .toLocaleLowerCase('tr-TR')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !['ile','ver','the','and','için','olan'].includes(w));
}

// Alıştırma başlığından, ders başlığıyla ortak olan baştaki sözcükleri atar.
// "Since & By the Time Zaman Sınırları I" -> "Zaman Sınırları I" gibi değil,
// tamamı ortaksa numaralı sade ada düşer.
// Örnek cümleler panoyu formülden önce dolduruyordu; kural görünsün diye
// formülün altına, katlanmış bir bloğa alındı.
// Türkçe harfler ASCII \b sınırını bozuyor ("açıktır" içindeki a, \ba\b ile
// eşleşiyordu); sözcük sınırları Unicode üzerinden kuruluyor.
const exWordRe = list => new RegExp('(?<![\\p{L}])(?:' + list + ')(?![\\p{L}])', 'iu');
const EX_EN_WORDS = exWordRe('the|a|an|is|are|was|were|be|been|have|has|had|will|would|could|should|can|they|we|you|it|of|in|on|at|to|that|this|and|or|but|by|for|not|with|from');
const EX_TR_WORDS = exWordRe('bir|ve|için|ile|bu|şu|olan|değil|daha|çok|gibi|kadar|sonra|önce|olarak|acaba|hangi');
const EX_TR_SUFFIX = /(?<![\p{L}])\p{L}+(iniz|ınız|unuz|ünüz|dır|dir|dur|dür|tır|tir|mış|miş|muş|müş|acak|ecek|ları|leri|ması|mesi|dan|den|tan|ten|nın|nin|nun|nün)(?![\p{L}])/iu;

const exWordCount = s => String(s).split(/\s+/).filter(Boolean).length;
const exLooksEnglish = s => EX_EN_WORDS.test(s);
const exLooksTurkish = s => /[ğşıçöüĞŞİÇÖÜ]/u.test(s) || EX_TR_WORDS.test(s) || EX_TR_SUFFIX.test(s);
const exIsTranslation = s => !!s && exWordCount(s) >= 2 && exLooksTurkish(s) && !exLooksEnglish(s);

// Örneklerin çoğu "Etiket: İngilizce cümle: Türkçe karşılık" ya da "İngilizce
// cümle (Türkçe karşılık)" biçiminde tek parça yazılmış. Ton farkı verebilmek
// için düz metin üzerinde parçalara ayrılır; dönen değerler metin konumudur.
function splitExampleLine(text) {
  let s = String(text || '').trim();
  if (!s) return null;
  let label = '';
  const head = s.match(/^([^:]{3,45}):\s*(\S[\s\S]*)$/);
  if (head && exWordCount(head[2]) >= 3 &&
      (!exLooksEnglish(head[1]) || (/\([^()]*\)\s*$/.test(head[1]) && exWordCount(head[1]) <= 5))) {
    label = head[1].trim();
    s = head[2].trim();
  }
  const paren = s.match(/^(.*\S)\s*\(([^()]{8,})\)\s*\.?\s*$/);
  if (paren && exIsTranslation(paren[2])) return { label, en: paren[1].trim(), tr: paren[2].trim() };
  const idx = s.lastIndexOf(':');
  if (idx > 0) {
    const left = s.slice(0, idx).trim(), right = s.slice(idx + 1).trim();
    if (left && exIsTranslation(right)) return { label, en: left, tr: right };
  }
  return label ? { label, en: s, tr: '' } : null;
}

// Örnek metinleri renkli <span>'ler taşıyabiliyor; ayrım düz metin üzerinde
// bulunduğu için parçaların etiketleri dengeli değilse biçimlendirme atılır.
function balancedTags(html) {
  const open = (html.match(/<span\b/gi) || []).length;
  const close = (html.match(/<\/span>/gi) || []).length;
  return open === close;
}

function splitExampleHTML(html) {
  const raw = String(html || '');
  const plain = raw.replace(/<[^>]+>/g, '');
  const parts = splitExampleLine(plain);
  if (!parts) return null;
  // Düz metindeki konumu HTML içindeki konuma çevir.
  const mapIndex = textIdx => {
    let seen = 0;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '<') { i = raw.indexOf('>', i); if (i === -1) return raw.length; continue; }
      if (seen === textIdx) return i;
      seen++;
    }
    return raw.length;
  };
  const enStart = plain.indexOf(parts.en);
  const enEnd = enStart + parts.en.length;
  if (enStart < 0) return { label: parts.label, en: parts.en, tr: parts.tr };
  const enHtml = raw.slice(mapIndex(enStart), mapIndex(enEnd)).trim();
  return balancedTags(enHtml)
    ? { label: parts.label, en: enHtml, tr: parts.tr }
    : { label: parts.label, en: parts.en, tr: parts.tr };
}

function examplesBlockHTML(example, label, exampleTr) {
  const split = text => String(text || '').split(/<br\s*\/?>/i).map(s => s.replace(/^\s*[•·-]\s*/, '').trim());
  const items = split(example);
  // Çeviriler örneklerle aynı sırada; bir kısmı zaten cümlenin içinde geçtiği
  // için karşılığı boş bırakılmış olabilir.
  const trs = split(exampleTr);
  const rows = items.map((s, i) => {
    if (!s) return '';
    // Çeviri ya ayrı alandan gelir ya da cümlenin içine gömülmüştür; ayrıştırma
    // her iki durumda da çalışır, çünkü baştaki etiketi de o ayırıyor.
    const parts = splitExampleHTML(s);
    const en = parts ? parts.en : s;
    const tr = trs[i] || (parts ? parts.tr : '');
    const tag = parts && parts.label ? parts.label : '';
    return `
    <div class="popover-example-item">
      ${tag ? `<div class="popover-example-label">${tag}</div>` : ''}
      <div class="popover-example-en">${en}</div>
      ${tr ? `<div class="popover-example-tr">${tr}</div>` : ''}
    </div>`;
  }).filter(Boolean);
  if (!rows.length) return '';
  return `
    <details class="popover-examples">
      <summary>${rows.length} ${label || 'örnek'}</summary>
      <div class="popover-examples-list">${rows.join('')}</div>
    </details>`;
}

function trimSharedLead(exTitle, lessonTitle) {
  const lessonSet = new Set(titleWords(lessonTitle));
  if (!lessonSet.size) return exTitle;
  const tokens = String(exTitle).split(/\s+/);
  let cut = 0;
  for (const tok of tokens) {
    const w = titleWords(tok)[0];
    // Bağlaç/işaret gibi kısa parçalar tek başına kesmeyi sürdürmez.
    if (w === undefined) { cut++; continue; }
    if (!lessonSet.has(w)) break;
    cut++;
  }
  // Başlığın tamamı ders adının tekrarıysa geriye ayırt edici bir şey kalmaz;
  // çağıran taraf sıra numaralı sade ada döner.
  if (cut === tokens.length) return '';
  if (!cut) return exTitle;
  const rest = tokens.slice(cut).join(' ').replace(/^[\s:–—-]+/, '').trim();
  return rest.length >= 3 ? rest.charAt(0).toLocaleUpperCase('tr-TR') + rest.slice(1) : exTitle;
}

// Açıklama, başlığın kelimelerini tekrarlamaktan ibaretse gösterilmez.
function isRedundantText(text, comparedTo) {
  const words = titleWords(text);
  if (!words.length) return true;
  const ref = new Set(titleWords(comparedTo));
  if (!ref.size) return false;
  const shared = words.filter(w => ref.has(w)).length;
  return shared / words.length >= 0.6;
}

function cleanExerciseTitle(title, idx) {
  if (!title) return `${idx}. Alıştırma`;
  let cleaned = title.replace(/^Alıştırma\s*\d+\s*:\s*/i, '');
  cleaned = cleaned.replace(/^Alıştırma\s*\d+\s*/i, '');
  cleaned = cleaned.trim();
  if (cleaned.length > 0) {
    cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
    return `${idx}. ${cleaned}`;
  }
  return `${idx}. Alıştırma`;
}

function cleanExerciseDescription(desc) {
  if (!desc) return '';
  
  // Soru sayısı satırdaki rozette zaten yazıyor; soru tipi de alıştırma
  // başlığında geçiyor. İkisi de açıklamadan düşer.
  desc = String(desc)
    .replace(/\(\s*\d+\s*soru\s*\)/gi, '')
    .replace(/\((?:[^()]*\b(?:çoktan seçmeli|kelime havuzu|kelime bankası|word bank|boşluk doldurma|eşleştirme|sıralama|çeviri)[^()]*)\)/gi, '');

  // Detect range like (1-15), (Cümleler 1-15), (13-24)
  const rangeMatch = desc.match(/\((?:Cümleler\s+)?(\d+-\d+)\)/i) || desc.match(/\b(\d+-\d+)\b/);
  const rangeStr = rangeMatch ? `Cümleler ${rangeMatch[1]}` : '';
  
  // Remove range from original description
  let baseText = desc.replace(/\((?:Cümleler\s+)?\d+-\d+\)/gi, '').replace(/\b\d+-\d+\b/gi, '');
  
  // Keywords to remove (question types)
  const keywords = [
    'eşleştirme', 'çoktan seçmeli', 'seçmeli', 'sıralama', 'çeviri', 'kelime bankası', 
    'kelime havuzu', 'yazarak çeviri', 'yazma', 'boşluk doldurma', 
    'kelime eşleştirme', 'blok sıralama', 'cümle çevirileri', 'bağlamsal çeviri',
    'öbek eşleştirme', 'katmanlı çeviri', 'paketleri', 'soruları'
  ];
  
  // Kelime sınırı olmadan silince "çevirisi" -> "si" gibi kırıntılar kalıyordu;
  // anahtar sözcük ancak kendi başına (ya da Türkçe ekiyle) geçtiğinde atılır.
  keywords.forEach(kw => {
    const esc = kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(^|\\s)${esc}(?=\\s|[.,;]|$)`, 'gi');
    baseText = baseText.replace(regex, '$1');
  });
  
  // Anahtar sözcük çıkınca geriye kalan boşta virgül/bağlaç artıkları toplanır;
  // cümlenin kendi noktalaması korunur, yoksa açıklama telgraf gibi okunuyordu.
  baseText = baseText
    .replace(/[•]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/\s+([.,;])/g, '$1')
    .replace(/([,;])\s*(?=[,;])/g, '')
    .replace(/(^|[,;])\s*ve\s*(?=[,;.]|$)/gi, '$1')
    .replace(/^[\s,;.\-–—]+/, '')
    .replace(/[\s,;\-–—]+$/, '')
    .trim();
    
  if (baseText.length > 10) {
    baseText = baseText.charAt(0).toUpperCase() + baseText.slice(1);
    return rangeStr ? `${baseText} (${rangeStr})` : baseText;
  }
  
  // Elde bir şey kalmadıysa "Genel Pratik" gibi bir dolgu yazmak yerine hiç
  // yazma; satırda zaten başlık ve soru sayısı var.
  return rangeStr || '';
}

function isGenericDescription(desc) {
  if (!desc) return true;
  const clean = desc.toLowerCase().trim();
  const keywords = [
    "boşluk doldurma",
    "kelime havuzu",
    "çoktan seçmeli",
    "eşleştirme",
    "cümle çevir",
    "kelime sıralama",
    "blok sıralama",
    "yapısal kalıplar",
    "cümle girişleri",
    "pratikleri",
    "çalışmaları",
    "analizi",
    "tanıma çalışmaları",
    "çeviri pratikleri"
  ];
  if (desc.includes("<li>") || desc.includes("<strong>") || desc.includes("🧠") || desc.includes("💡") || desc.length > 150) {
    return false;
  }
  return keywords.some(k => clean.includes(k));
}

function togglePopover(button, lessonId, unitId, pctX, pxY) {
  // Remove existing popover if any
  const existingPopover = document.querySelector('.lesson-popover');
  if (existingPopover) {
    const isSame = existingPopover.dataset.lessonId == lessonId;
    existingPopover.remove();
    updateBodyScrollLock();
    if (isSame) return;
  }

  const unit = units.find(u => u.id === unitId);
  const lesson = lessons.find(l => l.id === lessonId);
  if (!unit || !lesson) return;

  // Render preview details
  let previewHTML = '';
  const topic = rawTopics.find(t => (t.id !== undefined ? t.id : (rawTopics.indexOf(t) + 1)) === unit.id);
  const lessonIndex = unit.lessons.indexOf(lessonId);

  const exampleLabel = lesson.unitId === 8 ? 'rehber çeviri' : 'örnek';
  // Kutunun parçaları ayrı ayrı kuruluyor: gerçek bir kalıp yoksa FORMÜL satırı
  // hiç yazılmıyor, kutu da geriye bir şey kalmadıysa hiç açılmıyor.
  const previewBox = (formulaSrc, descSrc, exampleSrc, exampleTrSrc) => {
    const rows = [];
    if (looksLikeRealFormula(formulaSrc)) {
      rows.push(`<div class="grammar-formula"><span class="formula-badge">Formül</span>${formulaRowsHTML(formulaSrc, { hideTitleLike: lesson.title })}</div>`);
    }
    if (descSrc && !isGenericDescription(descSrc)) {
      rows.push(`<div class="grammar-description" style="font-size: 0.8rem; color: var(--text-secondary); ${rows.length ? 'margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--border-color);' : ''} line-height: 1.4;">${descSrc}</div>`);
    }
    const examples = examplesBlockHTML(exampleSrc, exampleLabel, exampleTrSrc);
    if (examples) rows.push(examples);
    return rows.length ? `<div class="grammar-preview-box">${rows.join('')}</div>` : '';
  };

  if (topic) {
    if (lesson.konuAnlatimi) {
      previewHTML = previewBox(
        lesson.konuAnlatimi.formul || lesson.konuAnlatimi.formula,
        lesson.konuAnlatimi.teorikMantik || lesson.konuAnlatimi.description,
        lesson.konuAnlatimi.ornek || lesson.example,
        lesson.konuAnlatimi.ornekCeviri || lesson.exampleTr);
    } else if (lesson.formula && lesson.example) {
      previewHTML = previewBox(lesson.formula, lesson.description, lesson.example, lesson.exampleTr);
    } else if (lesson.description && !isGenericDescription(lesson.description)) {
      previewHTML = `
        <div class="grammar-preview-box">
          <div class="grammar-description" style="font-size: 0.8rem; color: var(--text-secondary); line-height: 1.4;">${lesson.description}</div>
        </div>
      `;
    } else if (lessonIndex === 0 && topic.vocab && topic.vocab.length > 0) {
      const wordsList = topic.vocab.map(w => `<span class="preview-word-badge">${w.en}: ${w.tr}</span>`).join('');
      previewHTML = `
        <div class="lesson-preview-title">Öğrenilecek kelimeler:</div>
        <div class="lesson-preview-words">${wordsList}</div>
      `;
    } else if (lessonIndex === 1 && topic.sentences && topic.sentences.length > 0) {
      const sentencesList = topic.sentences.map(s => `<div class="preview-sentence-item"><strong>${s.en}</strong>: ${s.tr}</div>`).join('');
      previewHTML = `
        <div class="lesson-preview-title">Örnek cümle kalıpları:</div>
        <div class="preview-sentences-list">${sentencesList}</div>
      `;
    } else {
      previewHTML = '';
    }
  }

  const isCompleted = state.completedLessons.includes(lessonId);



  // Create popover element
  const popover = document.createElement('div');
  popover.className = 'lesson-popover';
  popover.dataset.lessonId = lessonId;
  // Positioned directly below the scaled-up labels (pxY + 65px) to prevent overlap with the smaller pins/labels
  popover.style.top = `${pxY + 65}px`;
  
  popover.style.left = `50%`;
  popover.style.setProperty('--arrow-left', `${pctX}%`);

  const isUnlocked = isLessonUnlocked(lessonId);

  // Altyazı bazı derslerde başlığın kopyası; aynı satırı iki kez yazmayız.
  const rawSubtitle = String(lesson.subtitle || '').trim();
  const popoverSubtitleHTML = (!rawSubtitle || isRedundantText(rawSubtitle, lesson.title)) ? '' : rawSubtitle;
  /* DEV NOTE: Disabled from visuals per user request, preserved in archive/database
  if (lesson.originalLessonId && lesson.originalLessonId <= 122 && lesson.originalLessonId !== lesson.displayId) {
    popoverSubtitleHTML += `<br><span style="font-size: 0.72rem; color: var(--text-muted); display: block; margin-top: 4px; font-weight: normal;">Eski Sırası: ${lesson.originalLessonId}. Ders</span>`;
  }
  */

  let popoverFooterHTML = '';
  const isNotUploadedLesson = (!lesson.exercises || lesson.exercises.length === 0 || lesson.exercises.every(ex => !ex.questions || ex.questions.length === 0)) && (!lesson.questions || lesson.questions.length === 0);
  if (isNotUploadedLesson) {
    popoverFooterHTML = `
      <div class="popover-exercises-container">
        <div class="popover-not-uploaded-message">
          <span class="not-uploaded-icon">⏳</span>
          <span class="not-uploaded-text">Ders eklenmemiştir</span>
        </div>
      </div>
    `;
  } else if (lesson.exercises && lesson.exercises.length > 0) {
    let hasAnyLockedExercise = false;
    let exercisesRows = lesson.exercises.map((ex, index) => {
      const isExCompleted = state.completedLessons.includes(`${lesson.id}_${ex.id}`);
      let isExUnlocked = true;
      if (!isLocalEnvironment()) {
        if (!checkLicence()) {
          // If no license, only the first exercise of the first 3 lessons is unlocked.
          if (index === 0) {
            isExUnlocked = isUnlocked;
          } else {
            isExUnlocked = false; // Lock everything else
            hasAnyLockedExercise = true;
          }
        } else {
          if (index === 0) {
            isExUnlocked = isUnlocked;
          } else {
            isExUnlocked = state.completedLessons.includes(`${lesson.id}_${lesson.exercises[index - 1].id}`);
          }
        }
      }
      
      // Ders adı zaten panonun tepesinde yazıyor; satırda yalnızca alıştırmayı
      // diğerlerinden ayıran kısım kalır.
      const rawExTitle = String(ex.title || '').replace(/^Alıştırma\s*\d+\s*:?\s*/i, '').trim();
      const shortExTitle = trimSharedLead(rawExTitle, lesson.title);
      const exTitle = cleanExerciseTitle(shortExTitle || 'Alıştırma', index + 1);
      const cleanedDesc = cleanExerciseDescription(ex.description);
      const exDesc = isRedundantText(cleanedDesc, `${lesson.title} ${rawExTitle}`) ? '' : cleanedDesc;

      const statusText = (isExCompleted && !isLocalEnvironment()) ? '✓ Tamamlandı' : (isExUnlocked ? 'Başlat' : 'Kilitli 🔒');
      const rowClass = isExUnlocked ? '' : 'locked';
      const badgeClass = isExCompleted ? 'completed' : '';
      
      return `
        <div class="popover-exercise-row ${rowClass}" data-exercise-id="${ex.id}">
          <div class="exercise-info">
            <span class="exercise-icon">${isExCompleted ? '✅' : '📝'}</span>
            <div class="exercise-meta">
              <div class="exercise-title-wrap">
                <span class="exercise-title">${exTitle}</span>
                <span class="exercise-q-badge ${badgeClass}">${ex.questions ? ex.questions.length : 0} Soru</span>
              </div>
              ${exDesc ? `<span class="exercise-subtitle">${exDesc}</span>` : ''}
            </div>
          </div>
          <div class="qp-btn-group">
            ${isLocalEnvironment() ? `<button class="exercise-preview-btn" ${isExUnlocked ? '' : 'disabled style="opacity: 0.5; pointer-events: none;"'} data-exercise-id="${ex.id}" title="Soruları Önizle">👁️ Önizle</button>` : ''}
            <button class="btn btn-primary exercise-start-btn" data-exercise-id="${ex.id}" data-locked="${!isExUnlocked}" style="${isExUnlocked ? '' : 'opacity: 0.85; background: var(--color-locked, #b5b5b5); border-color: var(--color-locked, #b5b5b5); color: var(--text-primary); cursor: pointer;'}">
              ${statusText}
            </button>
          </div>
        </div>
      `;
    }).join('');

    popoverFooterHTML = `
      <div class="popover-exercises-container">
        <h5 class="popover-exercises-title">Alıştırmalar</h5>
        <div class="popover-exercises-list">
          ${exercisesRows}
        </div>
        ${hasAnyLockedExercise ? `
          <div style="margin-top: 12px; padding: 10px 12px; background: rgba(245, 158, 11, 0.08); border: 1px dashed var(--accent-primary); border-radius: var(--radius-md); font-size: 0.8rem; color: var(--text-primary); display: flex; flex-direction: column; gap: 6px; text-align: left;">
            <div style="font-weight: 700; color: var(--accent-primary); display: flex; align-items: center; gap: 6px;">
              <span>🔑</span> Devam Etmek İçin Lisans Gerekli
            </div>
            <div style="color: var(--text-secondary); font-size: 0.75rem; line-height: 1.4;">
              Bu dersin sonraki alıştırmalarını tamamlamak ve diğer tüm bölümleri açmak için bir lisans anahtarı etkinleştirmeniz gerekmektedir.
            </div>
            <button id="popover-activate-licence-btn" style="background: var(--accent-primary); color: white; border: none; border-radius: 6px; padding: 6px 12px; font-weight: bold; font-size: 0.75rem; cursor: pointer; transition: all 0.2s; align-self: flex-start; margin-top: 2px;">
              Lisans Anahtarı Gir
            </button>
          </div>
        ` : ''}
      </div>
    `;
  } else {
    popoverFooterHTML = `
      <div class="popover-footer" style="display: flex; gap: 8px; justify-content: flex-end; align-items: center;">
        ${isUnlocked ? `
          ${isLocalEnvironment() ? `<button class="popover-preview-btn" title="Tüm Soruları Önizle">👁️ Önizle</button>` : ''}
          <button class="btn btn-primary popover-start-btn" style="flex: 1;">
            ${isCompleted ? 'Tekrar Et (+5 Puan)' : 'Dersi Başlat (+10 Puan)'}
          </button>
        ` : `
          <button class="btn btn-primary popover-start-btn" disabled>
            🔒 KİLİTLİ
          </button>
        `}
      </div>
    `;
  }

    const uIdx = units.findIndex(u => u.id === unitId);
    const colorIndex = uIdx === -1 ? 1 : ((uIdx % 10) + 1);
    // Başlıktaki sondaki parantez konunun ikinci bir adı; başlığı iki satıra
    // şişirmek yerine altına soluk bir not olarak iner.
    const titleParts = String(lesson.title || '').match(/^([\s\S]*?)\s*\(([^()]*)\)\s*$/);
    const titleMain = titleParts ? titleParts[1] : String(lesson.title || '');
    const titleNote = titleParts && !isRedundantText(titleParts[2], titleParts[1]) ? titleParts[2] : '';
    popover.innerHTML = `
    <div class="popover-arrow"></div>
    <div class="popover-header">
      <h4 class="popover-title">${titleMain.replace(/(\([^)]+\))/g, `<span class="unit-text-color-${colorIndex}">$1</span>`)}</h4>
      ${titleNote ? `<span class="popover-title-note">${titleNote}</span>` : ''}
      ${popoverSubtitleHTML ? `<span class="popover-subtitle">${popoverSubtitleHTML}</span>` : ''}
    </div>
    ${previewHTML ? `<div class="popover-body">${previewHTML}</div>` : ''}
    ${popoverFooterHTML}
  `;

  if (lesson.exercises && lesson.exercises.length > 0) {
    popover.querySelectorAll('.exercise-start-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const exerciseId = btn.dataset.exerciseId;
        const isLocked = btn.dataset.locked === 'true';
        if (isLocked) {
          popover.remove();
          showGuestBlockModal();
          return;
        }
        popover.remove();
        startLesson(lessonId, exerciseId);
      });
    });
    const popoverActivateBtn = popover.querySelector('#popover-activate-licence-btn');
    if (popoverActivateBtn) {
      popoverActivateBtn.addEventListener('click', () => {
        popover.remove();
        showGuestBlockModal();
      });
    }
    popover.querySelectorAll('.exercise-preview-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const exerciseId = btn.dataset.exerciseId;
        const exercise = lesson.exercises.find(ex => ex.id === exerciseId);
        if (exercise) {
          openQuestionPreview(exercise.title, exercise.questions, exercise);
        }
      });
    });
  } else if (isUnlocked) {
    popover.querySelector('.popover-start-btn').addEventListener('click', () => {
      popover.remove();
      startLesson(lessonId);
    });
    const prevBtn = popover.querySelector('.popover-preview-btn');
    if (prevBtn) {
      prevBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openQuestionPreview(lesson.title, lesson.questions, lesson);
      });
    }
  }

  popover.addEventListener('click', (e) => e.stopPropagation());

  const pathContainer = button.closest('.unit-path-container');
  if (pathContainer) {
    pathContainer.appendChild(popover);
    updateBodyScrollLock();
    
    // Dynamically adjust popover position to fit within the visible viewport bounds
    requestAnimationFrame(() => {
      const popoverRect = popover.getBoundingClientRect();
      const sidebar = document.querySelector('.sidebar-nav');
      
      const isSidebarLeft = sidebar && window.innerWidth >= 820 && window.getComputedStyle(sidebar).display !== 'none';
      const leftMargin = 16;
      const leftBound = (isSidebarLeft ? sidebar.getBoundingClientRect().right : 0) + leftMargin;
      const rightBound = window.innerWidth - leftMargin;
      
      const W_p = popoverRect.width || 450;
      const W_container = containerRect.width || 440;
      
      const X_btn = (pctX / 100) * W_container;
      let X_p = X_btn; // center of popover relative to container
      
      // Calculate current screen bounds of the popover
      let popLeftScreen = containerRect.left + X_p - W_p / 2;
      let popRightScreen = containerRect.left + X_p + W_p / 2;
      
      // Adjust for left boundary overflow
      if (popLeftScreen < leftBound) {
        const overflowL = leftBound - popLeftScreen;
        X_p += overflowL;
      }
      // Adjust for right boundary overflow
      else if (popRightScreen > rightBound) {
        const overflowR = popRightScreen - rightBound;
        X_p -= overflowR;
      }
      
      // Double check new bounds to make sure we didn't push it off the other side on very small screens
      popLeftScreen = containerRect.left + X_p - W_p / 2;
      if (popLeftScreen < leftBound) {
        X_p = leftBound - containerRect.left + W_p / 2;
      }
      
      // Apply the adjusted position
      popover.style.left = `${X_p}px`;
      
      // Calculate where the arrow should point (aligned with X_btn) relative to the popover's left edge
      const X_btn_rel_pop = X_btn - (X_p - W_p / 2);
      const arrowPct = Math.max(5, Math.min(95, (X_btn_rel_pop / W_p) * 100)); // Clamp between 5% and 95% to keep arrow within popover bounds
      popover.style.setProperty('--arrow-left', `${arrowPct}%`);

      // Auto-scroll to show the popover
      const rect = popover.getBoundingClientRect();
      if (rect.height > window.innerHeight) {
        popover.scrollIntoView({ behavior: 'smooth', block: 'start' });
      } else {
        popover.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    });
  }
}

// Global listener to close popover on outside click
document.addEventListener('click', () => {
  const popover = document.querySelector('.lesson-popover');
  if (popover) {
    popover.remove();
    updateBodyScrollLock();
  }
});

function isLessonUnlocked(lessonId) {
  if (isLocalEnvironment()) {
    return true;
  }

  // Find the lesson and its unit
  const lesson = lessons.find(l => l.id === lessonId);
  if (!lesson) return false;

  const currentUnitId = lesson.unitId;

  // Get units in their database/TOC sequence
  const sortedUnits = [...units];

  // Rule: First 3 lessons of Unit 1 are open by default
  const firstUnit = sortedUnits[0];
  let isFreeLesson = false;
  if (firstUnit && currentUnitId === firstUnit.id) {
    const lessonIdxInUnit = firstUnit.lessons.indexOf(lessonId);
    if (lessonIdxInUnit >= 0 && lessonIdxInUnit < 3) {
      isFreeLesson = true;
    }
  }

  // If NOT a free lesson, check if a valid license is present
  if (!isFreeLesson) {
    if (!checkLicence()) {
      return false; // Lock all other lessons without licence
    }
  }

  const sortedLessons = [];
  sortedUnits.forEach(u => {
    u.lessons.forEach(lId => {
      sortedLessons.push(lId);
    });
  });

  const idx = sortedLessons.indexOf(lessonId);
  if (idx === 0) return true; // Very first lesson is always unlocked

  // Check if all lessons in all previous units are completed
  const currentUnitIndex = sortedUnits.findIndex(u => u.id === currentUnitId);
  if (currentUnitIndex > 0) {
    for (let i = 0; i < currentUnitIndex; i++) {
      const prevUnit = sortedUnits[i];
      const allCompleted = prevUnit.lessons.every(lId => state.completedLessons.includes(lId));
      if (!allCompleted) return false;
    }
  }

  // Current lesson is unlocked if the previous lesson in visual progression is completed
  return state.completedLessons.includes(sortedLessons[idx - 1]);
}

