// BÖLÜM 36 (UNIT 101) GÖRSEL EĞİTİM YARDIMCILARI
// ════════════════════════════════════════════════════════

function colorCodeUnit101Sentence(sentence) {
  if (!sentence) return sentence;
  
  // Önce mevcut span etiketlerini ve stillerini temizleyelim
  let cleaned = sentence.replace(/<span[^>]*>(.*?)<\/span>/gi, '$1');
  
  // Konnektörlerin renklendirilmesi
  cleaned = cleaned.replace(/\b(since|by the time|it is high time|it is time)\b/gi, '<span class="color-code-connector">$1</span>');
  
  // Present Perfect (Green)
  cleaned = cleaned.replace(/\b(has|have)\s+([\w'-]+ed|been|grown|expanded|seen|read|done|completed|arrived|updated)\b/gi, '<span class="color-code-perfect">$1 $2</span>');
  
  // Past Perfect (Purple)
  cleaned = cleaned.replace(/\b(had)\s+([\w'-]+ed|been|left|finished|completed|gone|seen|read|done)\b/gi, '<span class="color-code-past-perfect">$1 $2</span>');
  
  // Future Perfect (Blue)
  cleaned = cleaned.replace(/\b(will\s+have)\s+([\w'-]+ed|been|left|finished|completed|gone|seen|read|done)\b/gi, '<span class="color-code-future-perfect">$1 $2</span>');
  
  // Simple Past / V2 (Red)
  const v2Verbs = ['was passed', 'were planted', 'arrived', 'left', 'updated', 'passed', 'failed', 'started', 'commenced', 'concluded'];
  v2Verbs.forEach(verb => {
    const regex = new RegExp(`\\b(${verb})\\b`, 'gi');
    cleaned = cleaned.replace(regex, '<span class="color-code-v2">$1</span>');
  });

  // Simple Present / V1 (Orange)
  const v1Verbs = ['arrives', 'leaves', 'updates', 'passes', 'fails', 'starts', 'commences', 'concluded'];
  v1Verbs.forEach(verb => {
    const regex = new RegExp(`\\b(${verb})\\b`, 'gi');
    cleaned = cleaned.replace(regex, '<span class="color-code-v1">$1</span>');
  });
  
  return cleaned;
}

function colorCodeUnit12Sentence(sentence) {
  if (!sentence || typeof sentence !== 'string') return sentence;

  // 1. Birleşik ve Zarflı Sıfat-Fiiller + Niteledikleri İsim (e.g. soil-enriching humus, well-preserved paintings, culture-shaping norms, mind-bending paradox, path-breaking theory, well-documented events) -> Amber
  let cleaned = sentence.replace(/\b([\w]+-(?:enriching|developed|preserved|shaping|bending|breaking|rooted|documented|damaged|discovered|shifting)\s+[\w]+)\b/gi, '<span class="participle-adv">$1</span>');
  cleaned = cleaned.replace(/\b((?:well|highly|deeply|newly|poorly|rapidly|heavily)\s+[\w]+(?:ed|ing)\s+[\w]+)\b/gi, '<span class="participle-adv">$1</span>');

  // Fallback for compound adjectives without following noun captured yet
  cleaned = cleaned.replace(/\b([\w]+-(?:enriching|developed|preserved|shaping|bending|breaking|rooted|documented|damaged|discovered|shifting))\b/gi, (match) => {
    if (cleaned.includes(match) && cleaned.indexOf(`">${match}`) !== -1) return match;
    return `<span class="participle-adv">${match}</span>`;
  });
  cleaned = cleaned.replace(/\b((?:well|highly|deeply|newly|poorly|rapidly|heavily)\s+[\w]+(?:ed|ing))\b/gi, (match) => {
    if (cleaned.includes(match) && cleaned.indexOf(`">${match}`) !== -1) return match;
    return `<span class="participle-adv">${match}</span>`;
  });

  // 2. Participle Clause Reductions (e.g. moving in the gas, containing organisms, cooked with electricity, recovered from ruins) -> Pink
  cleaned = cleaned.replace(/\b((?:moving|containing|cooked|recovered|preserved|excavated|living|working|written|built|designed|produced|created)\s+(?:in|with|from|by|of|on|at|about)\s+[\w\s]+?)(?=[.,;!?]|$)/gi, (match) => {
    // Avoid double wrapping if already wrapped
    if (match.includes('<span')) return match;
    return `<span class="participle-phrase">${match}</span>`;
  });

  // 3. Present Participle (...ing) sıfatları + Niteledikleri İsim (e.g. emerging technologies, evolving languages, crying child, shining monuments, varying opinions) -> Green
  cleaned = cleaned.replace(/\b((?:emerging|evolving|crying|shining|varying|lasting|hiding|shifting|rooting)\s+[\w]+)\b/gi, (match) => {
    if (match.includes('<span')) return match;
    return `<span class="participle-ing">${match}</span>`;
  });

  // 4. Past Participle (...ed/V3) sıfatları + Niteledikleri İsim (e.g. detailed reports, stolen manuscript, excavated artifacts, written laws, broken treaties, forgotten civilisations) -> Purple
  cleaned = cleaned.replace(/\b((?:detailed|stolen|excavated|written|broken|forgotten|hidden|damaged)\s+[\w]+)\b/gi, (match) => {
    if (match.includes('<span')) return match;
    return `<span class="participle-ed">${match}</span>`;
  });

  return cleaned;
}

function colorCodeUnit29Sentence(sentence) {
  if (!sentence || typeof sentence !== 'string') return sentence;
  const patterns = [
    // 🟢 GRUP 1: İsim & V-ing Alan Yapılar (Edatlar / Prepositions) - YEŞİL (#10b981)
    { 
      regex: /\b(In spite of|In addition to|In contrast to|Despite|Notwithstanding|On account of|As a consequence of|As a result of|Owing to|Due to|In view of|Because of|Thanks to|with a view to|for the purpose of|by means of|for the sake of|by virtue of|on the grounds of|Regardless of|In case of|with regard to|in terms of)\b/gi, 
      color: "#10b981" 
    },

    // 🔵 GRUP 2: Cümle (Özne+Yüklem) Alan Yapılar (Cümle Bağlaçları) - MAVİ (#3b82f6)
    { 
      regex: /\b(Even though|Although|Even if|Though|Because|Since|While|Whereas|in order that|so that|Provided that|As long as|on condition that|Unless|Provided|By the time|As soon as|Until|Before|After)\b/gi, 
      color: "#3b82f6" 
    },

    // 🔴 GRUP 3: İki Cümle Arasına Gelenler (Geçiş Zarfları / Transitions) - KIRMIZI (#ef4444)
    { 
      regex: /\b(However|Nevertheless|Nonetheless|Moreover|Furthermore|Accordingly|Consequently|Therefore|On the other hand|On the contrary|Otherwise|Besides|In addition|Hence|Thus)\b/gi, 
      color: "#ef4444" 
    }
  ];

  const tokens = sentence.split(/(<[^>]+>)/g);
  for (let i = 0; i < tokens.length; i++) {
    if (!tokens[i].startsWith("<")) {
      patterns.forEach(p => {
        tokens[i] = tokens[i].replace(p.regex, (m) => 
          `<span class="conjunction-highlight" style="color: ${p.color}; font-weight: 700; font-family: inherit;">${m}</span>`
        );
      });
    }
  }
  return tokens.join("");
}

function colorCodeUnit104Sentence(sentence) {
  if (!sentence || typeof sentence !== 'string') return sentence;
  let res = sentence;

  const modalPatterns = [
    /\b((?:don't|doesn't|didn't)?\s*(?:have|has|had)\s+to)\b/gi,
    /\b(needn't|(?:don't|doesn't|didn't)\s+need\s+to)\b/gi,
    /\b((?:am|is|are|was|were|will\s+be|be)?\s*able\s+to)\b/gi,
    /\b(ought\s+(?:not\s+)?to)\b/gi,
    /\b(had\s+better(?:\s+not)?)\b/gi,
    /\b((?:didn't\s+)?used?\s+to)\b/gi,
    /\b((?:am|is|are|was|were|get|gets|got|getting|have\s+got|has\s+got)\s+used\s+to)\b/gi
  ];

  modalPatterns.forEach(pattern => {
    res = res.replace(pattern, (match, p1, offset, fullStr) => {
      const before = fullStr.slice(0, offset);
      const lastOpen = before.lastIndexOf('<');
      const lastClose = before.lastIndexOf('>');
      if (lastOpen > lastClose) return match;

      const after = fullStr.slice(offset + match.length);
      const nextCloseSpan = after.indexOf('</span>');
      const nextOpenSpan = after.indexOf('<span');
      if (nextCloseSpan !== -1 && (nextOpenSpan === -1 || nextCloseSpan < nextOpenSpan)) {
        return match;
      }

      return `<span style="color: #ff6b6b; font-weight: bold;">${p1}</span>`;
    });
  });

  return res;
}

function getConjunctionGroupInfo(optText) {
  if (!optText || typeof optText !== 'string') return null;
  const clean = optText.trim();
  const g1Regex = /\b(In spite of|In addition to|In contrast to|Despite|Notwithstanding|On account of|As a consequence of|As a result of|Owing to|Due to|In view of|Because of|Thanks to|with a view to|for the purpose of|by means of|for the sake of|by virtue of|on the grounds of|Regardless of|In case of|with regard to|in terms of)\b/i;
  const g2Regex = /\b(Even though|Although|Even if|Though|Because|Since|While|Whereas|in order that|so that|Provided that|As long as|on condition that|Unless|Provided|By the time|As soon as|Until|Before|After)\b/i;
  const g3Regex = /\b(However|Nevertheless|Nonetheless|Moreover|Furthermore|Accordingly|Consequently|Therefore|On the other hand|On the contrary|Otherwise|Besides|In addition|Hence|Thus)\b/i;

  if (g1Regex.test(clean)) {
    return { name: "Grup 1 (İsim & V-ing Alan)", color: "#10b981", badge: "🟢" };
  }
  if (g2Regex.test(clean)) {
    return { name: "Grup 2 (Tam Cümle Alan)", color: "#3b82f6", badge: "🔵" };
  }
  if (g3Regex.test(clean)) {
    return { name: "Grup 3 (İki Cümle Arasına Gelen - Noktalamacı)", color: "#ef4444", badge: "🔴" };
  }
  return null;
}

