// ── Noktalama İşaretli Seçim (punctuation-check) ──────────
function renderPunctuationCheck(container, question) {
  const rawSentence = question.sentence.replace(
    /__________/g, 
    `<span class="punctuation-gap">[ ? ]</span>`
  ).replace(
    /___/g,
    `<span class="punctuation-gap">[ ? ]</span>`
  );
  const formattedQuestion = makeTextHoverable(rawSentence);

  const optionsHtml = question.options.map((opt, i) => {
    const meaning = getOptionMeaning(question, opt);
    const hasTags = String(opt).includes('<');
    const displayText = (meaning && !String(opt).includes('/')) 
      ? (hasTags ? `${opt} <span style="opacity: 0.8; font-weight: 400; font-size: 0.9em; margin-left: 6px; color: var(--text-secondary, #64748b);">/ ${meaning}</span>` : `<strong>${opt}</strong> <span style="opacity: 0.8; font-weight: 400; font-size: 0.9em; margin-left: 6px; color: var(--text-secondary, #64748b);">/ ${meaning}</span>`)
      : opt;
    return `<button class="mc-option" data-index="${i}">${displayText}</button>`;
  }).join('');

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt || "Noktalama İşaretlerine Dikkat Ederek Doğru Bağlacı Seçin"}</p>
    <div class="punctuation-context" style="text-align: center; margin: 24px 0;">
      ${formattedQuestion}
    </div>
    <div class="mc-options">
      ${optionsHtml}
    </div>
  `;

  container.querySelectorAll('.mc-option').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked) return;
      container.querySelectorAll('.mc-option').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedAnswer = parseInt(btn.dataset.index);
      document.getElementById('btn-check').disabled = false;

      // Seçim yapıldıktan 250ms sonra cevabı otomatik olarak kontrol et
      setTimeout(() => {
        checkAnswer();
      }, 250);
    });
  });
}

