// ── Deyim İnşa Etme (idiom-builder) ──────────
function renderIdiomBuilder(container, question) {
  let currentSelection = [];
  const shuffledTokens = [...question.tokens].sort(() => Math.random() - 0.5);

  let displaySentence = question.sentence || question.question || "";
  const targetPhrase = Array.isArray(question.correctSequence) 
    ? question.correctSequence.join(' ') 
    : (Array.isArray(question.tokens) ? question.tokens.join(' ') : "");

  if (displaySentence && targetPhrase) {
    const escapedPhrase = targetPhrase.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const phraseRegex = new RegExp(escapedPhrase.split('\\s+').join('\\s+'), 'gi');
    displaySentence = displaySentence.replace(phraseRegex, '_______');
  }

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt || "Deyimi Doğru Kelimelerle Sırasıyla İnşa Edin"}</p>
    <div style="text-align: center; margin-bottom: 20px;">
      <span class="idiom-meaning-badge">Anlamı: ${question.meaningTr}</span>
    </div>
    
    <div class="idiom-build-zone" id="build-zone">
      <span class="build-placeholder">Deyimi tamamlamak için aşağıdaki kelimelere sırasıyla tıklayın...</span>
    </div>
    
    <div class="context-sentence" style="text-align: center; margin: 20px 0;">
      ${displaySentence}
    </div>
    
    <div class="tokens-flex" id="idiom-tokens" style="display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 20px;"></div>
  `;

  const tokensParent = document.getElementById("idiom-tokens");
  const buildZone = document.getElementById("build-zone");

  shuffledTokens.forEach(token => {
    const button = document.createElement("button");
    button.className = "amok-token-btn";
    button.innerText = token;
    
    button.addEventListener('click', () => {
      if (isAnswerChecked) return;
      if (button.classList.contains("token-used")) return;
      
      if (currentSelection.length === 0) buildZone.innerHTML = "";
      
      currentSelection.push(token);
      button.classList.add("token-used");
      
      const wordSpan = document.createElement("span");
      wordSpan.className = "selected-idiom-word animate-pop";
      wordSpan.innerText = token;
      buildZone.appendChild(wordSpan);
      
      if (currentSelection.length === question.correctSequence.length) {
        selectedAnswer = currentSelection;
        document.getElementById('btn-check').disabled = false;
        
        setTimeout(() => {
          checkAnswer();
        }, 300);
      }
    });
    
    tokensParent.appendChild(button);
  });
}

// ── Vector Assembly (vector-assembly) ──────────
function renderVectorAssembly(container, question) {
  let currentSelection = [];
  const tokens = [...question.scrambled_elements];
  
  let displaySentence = question.sentence || question.question || "";
  if (displaySentence && question.correct_sequence) {
    const correctPhrase = question.correct_sequence.join(' ').trim();
    if (correctPhrase) {
      const escapedPhrase = correctPhrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const spanRegex = new RegExp(`<span[^>]*>\\s*${escapedPhrase.split('\\s+').join('\\s+')}\\s*<\\/span>`, 'i');
      if (spanRegex.test(displaySentence)) {
        displaySentence = displaySentence.replace(spanRegex, '_______');
      } else {
        const rawRegex = new RegExp(escapedPhrase.split('\\s+').join('\\s+'), 'i');
        if (rawRegex.test(displaySentence)) {
          displaySentence = displaySentence.replace(rawRegex, '_______');
        }
      }
    }
  }

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt || "Öğeleri doğru sırayla birleştirerek eylemi inşa edin:"}</p>
    
    <div class="vector-build-zone" id="vector-build-zone" style="min-height: 50px; display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; align-items: center; border: 2px dashed var(--border-color); border-radius: var(--radius-md); padding: 15px; background: var(--bg-secondary); margin-bottom: 20px;">
      <span class="build-placeholder" style="color: var(--text-muted); font-size: 0.95rem;">Öğeleri sırasıyla seçerek eylemi oluşturun...</span>
    </div>
    
    <div class="context-sentence" style="text-align: center; margin: 20px 0; font-size: 1.15rem; font-weight: 500; color: var(--text-primary);">
      ${displaySentence}
    </div>
    
    <div class="tokens-flex" id="vector-tokens" style="display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 20px;"></div>
  `;

  const tokensParent = document.getElementById("vector-tokens");
  const buildZone = document.getElementById("vector-build-zone");

  tokens.forEach(token => {
    const button = document.createElement("button");
    button.className = "amok-token-btn";
    button.innerText = token;
    
    button.addEventListener('click', () => {
      if (isAnswerChecked) return;
      if (button.classList.contains("token-used")) return;
      
      if (currentSelection.length === 0) buildZone.innerHTML = "";
      
      currentSelection.push(token);
      button.classList.add("token-used");
      
      const wordSpan = document.createElement("span");
      wordSpan.className = "selected-idiom-word animate-pop";
      wordSpan.innerText = token;
      buildZone.appendChild(wordSpan);
      
      if (currentSelection.length === question.correct_sequence.length) {
        selectedAnswer = currentSelection;
        document.getElementById('btn-check').disabled = false;
        
        setTimeout(() => {
          checkAnswer();
        }, 300);
      }
    });
    
    tokensParent.appendChild(button);
  });
}

// ── Kelime Bankası ──────────────────────────────────────────
function segmentSentence(fullSentence, isEngToTr) {
  let segments = [fullSentence];

  function escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function applySplitBefore(segs, substring) {
    const result = [];
    const regex = new RegExp(`\\b${escapeRegex(substring)}\\b`, 'i');
    for (let s of segs) {
      const match = regex.exec(s);
      if (match) {
        const idx = match.index;
        const part1 = s.substring(0, idx).trim();
        const part2 = s.substring(idx).trim();
        if (part1) result.push(part1);
        if (part2) result.push(part2);
      } else {
        result.push(s);
      }
    }
    return result;
  }

  function applySplitBeforeAndAfter(segs, substring) {
    const result = [];
    const regex = new RegExp(`\\b${escapeRegex(substring)}\\b`, 'i');
    for (let s of segs) {
      const match = regex.exec(s);
      if (match) {
        const idx = match.index;
        const part1 = s.substring(0, idx).trim();
        const matchText = match[0].trim();
        const part2 = s.substring(idx + match[0].length).trim();
        if (part1) result.push(part1);
        if (matchText) result.push(matchText);
        if (part2) result.push(part2);
      } else {
        result.push(s);
      }
    }
    return result;
  }

  function applySplitAfter(segs, substring) {
    const result = [];
    const regex = new RegExp(`\\b${escapeRegex(substring)}\\b`, 'i');
    for (let s of segs) {
      const match = regex.exec(s);
      if (match) {
        let idx = match.index + match[0].length;
        while (idx < s.length && [';', ',', '.', '?', '!'].includes(s[idx])) {
          idx++;
        }
        const part1 = s.substring(0, idx).trim();
        const part2 = s.substring(idx).trim();
        if (part1) result.push(part1);
        if (part2) result.push(part2);
      } else {
        result.push(s);
      }
    }
    return result;
  }

  if (isEngToTr) {
    // ─── TURKISH GRAMMATICAL SPLITTER ───
    const splitBeforeAndAfterTr = [
      "sonuç olarak", "bu nedenle", "bu yüzden", "böylece", "buna göre",
      "ve sonuç olarak", "bunun bir sonucu olarak", "bu sebepten",
      "ani bir sonuç olarak", "gerekçesiyle", "veya", "ya da", "ve", "ile",
      "gelince", "aksine", "birlikte", "ilişkin", "konusunda", "açısından"
    ];

    const splitAfterTr = [
      "olarak", "ederek", "yaparak", "edildiğinde", "yapıldığında", "olduğunda", "olduğu gibi",
      "meydana geldi", "ortaya çıktı", "yol açar", "sonuçlanır", "neden olur",
      "sorumludur", "kaynaklanır", "katkıda bulunur", "tetikler", "geciktirir",
      "çöktü", "düştü", "güvende kalır", "ertelendi", "gecikti", "tetiklendi",
      "yol açmıştır", "sonuçlanmıştır", "neden olmuştur", "kaynaklanmaktadır",
      "geciktirmiştir", "çökmüştür", "düşmüştür", "ertelenmiştir", "gelişti",
      "açındı", "aşındı", "kilitlendi", "arttı", "durgunlaştı", "engellendi",
      "azalttı", "çeşitlilik gösterir", "çeşitlilik göstermesine neden oldu",
      "değişmesine neden oldu", "daralmasına neden oldu", "kaymasına neden oldu",
      "en aza indirmesine neden oldu", "hatalara yol açmasına neden oldu",
      "etkileşime girmesine neden oldu", "değişmesine neden oldu", "düşmesine neden oldu",
      "genişlemesine neden oldu", "aşınmasına neden oldu", "doğrulamasına neden oldu",
      "evrilmesine neden oldu", "çakışmasına neden oldu",
      "izlemelidir", "gelişir", "artar", "değişiklik gerektirir", "genişleme gerektirir",
      "talep etti", "yansıtılmıştır",
      "sırasında", "esnasında", "boyunca", "nedeniyle", "yüzünden", "dolayı",
      "sayesinde", "için", "ölçüde", "kadar", "başka", "itibaren", "rağmen",
      "katmanlarında", "merkezinde", "bölümünde", "düğümlerinde", "odasında",
      "altında", "aşamasında", "durumunda", "çerçevesinde", "yönünde", "genelinde",
      "üzerinde", "altından", "dışında", "yakınında", "öncesinde", "sonrasında"
    ];

    // 1. Semicolon split
    let temp = [];
    for (let s of segments) {
      if (s.includes(';')) {
        const parts = s.split(';');
        temp.push(parts[0].trim() + ';');
        if (parts[1].trim()) temp.push(parts[1].trim());
      } else {
        temp.push(s);
      }
    }
    segments = temp;

    // 1b. Comma split for natural phrase clauses
    let tempComma = [];
    for (let s of segments) {
      if (s.includes(',')) {
        const parts = s.split(',');
        for (let i = 0; i < parts.length; i++) {
          let p = parts[i].trim();
          if (!p) continue;
          if (i < parts.length - 1) {
            tempComma.push(p + ',');
          } else {
            tempComma.push(p);
          }
        }
      } else {
        tempComma.push(s);
      }
    }
    segments = tempComma;

    // 2. Split before/after
    const sortedBeforeAndAfter = [...splitBeforeAndAfterTr].sort((a, b) => b.length - a.length);
    for (let marker of sortedBeforeAndAfter) {
      segments = applySplitBeforeAndAfter(segments, marker);
    }

    // 3. Split after
    const sortedAfter = [...splitAfterTr].sort((a, b) => b.length - a.length);
    for (let marker of sortedAfter) {
      segments = applySplitAfter(segments, marker);
    }

  } else {
    // ─── ENGLISH GRAMMATICAL SYNTACTIC SPLITTER ───
    const phrasalModals = [
      "is accustomed to", "are accustomed to", "was accustomed to", "were accustomed to", "am accustomed to",
      "is used to", "are used to", "was used to", "were used to", "am used to",
      "get used to", "gets used to", "got used to", "getting used to",
      "is willing to", "are willing to", "was willing to", "were willing to", "am willing to",
      "is unwilling to", "are unwilling to", "was unwilling to", "were unwilling to", "am unwilling to",
      "is reluctant to", "are reluctant to", "was reluctant to", "were reluctant to", "am reluctant to",
      "is doomed to", "are doomed to", "was doomed to", "were doomed to", "am doomed to",
      "is unable to", "are unable to", "was unable to", "were unable to", "am unable to",
      "is able to", "are able to", "was able to", "were able to", "am able to",
      "is bound to", "are bound to", "was bound to", "were bound to", "am bound to",
      "is likely to", "are likely to", "was likely to", "were likely to", "am likely to",
      "is unlikely to", "are unlikely to", "was unlikely to", "were unlikely to", "am unlikely to",
      "is about to", "are about to", "was about to", "were about to", "am about to",
      "is supposed to", "are supposed to", "was supposed to", "were supposed to", "am supposed to",
      "is set to", "are set to", "was set to", "were set to", "am set to",
      "is eager to", "are eager to", "was eager to", "were eager to", "am eager to"
    ];

    const splitBeforeAndAfter = [
      "give rise to", "gives rise to", "gave rise to",
      "result in", "results in", "has resulted in", "have resulted in", "resulted in",
      "is responsible for", "are responsible for", "was responsible for", "were responsible for",
      "lead to", "leads to", "led to",
      "bring about", "brings about", "brought about",
      "contribute to", "contributes to", "contributed to",
      "stem from", "stems from", "stemmed from",
      "trigger", "triggers", "triggered",
      "causes", "produce", "produces", "produced",
      "therefore", "consequently", "as a result", "hence", "thus", "accordingly", "so"
    ];

    const splitBefore = [
      "who", "which", "that", "whose", "whom", "where", "when", "while",
      "publish", "publishes", "published",
      "evaluate", "evaluates", "evaluated",
      "examine", "examines", "examined",
      "analyze", "analyzes", "analyzed",
      "identify", "identifies", "identified",
      "observe", "observes", "observed",
      "conduct", "conducts", "conducted",
      "investigate", "investigates", "investigated",
      "discover", "discovers", "discovered",
      "challenge", "challenges", "challenged",
      "transform", "transforms", "transformed",
      "approve", "approves", "approved",
      "revise", "revises", "revised",
      "reinterpreting", "evaluating", "examining", "analyzing", "identifying", "observing",
      "conducting", "investigating", "discovering", "challenging", "transforming", "producing",
      "developing", "creating", "establishing", "demonstrating", "determining", "highlighting",
      "reflecting", "demanding", "influencing", "illustrating", "revealing", "focusing",
      "addressing", "incorporating", "surrounding", "featuring", "containing", "involving",
      "living", "reading", "excavating", "forcing", "reducing", "degrading", "altering",
      "due to", "because of", "owing to", "on account of", "thanks to",
      "because", "since", "inasmuch as", "although", "even though", "whereas",
      "to inspect", "to meet", "to request", "to isolate", "to maintain", "to validate",
      "to change", "to vary", "to collapse", "to contract", "to shift", "to minimize",
      "to induce", "to interact", "to mutate", "to decline", "to expand", "to decay",
      "to evolve", "to conflict", "unless", "if", "the moment", "under", "in order that",
      "on grounds that", "with the result that", "as a consequence", "for this reason",
      "as an immediate result", "on that account", "inside", "during", "before", "after", "until",
      "last week", "last month", "yesterday", "recently", "in 2012", "in 1994"
    ];

    // 1. Semicolon split
    let temp = [];
    for (let s of segments) {
      if (s.includes(';')) {
        const parts = s.split(';');
        temp.push(parts[0].trim() + ';');
        if (parts[1].trim()) temp.push(parts[1].trim());
      } else {
        temp.push(s);
      }
    }
    segments = temp;

    // 1b. Comma split
    let tempComma = [];
    for (let s of segments) {
      if (s.includes(',')) {
        const parts = s.split(',');
        for (let i = 0; i < parts.length; i++) {
          let p = parts[i].trim();
          if (!p) continue;
          if (i < parts.length - 1) {
            tempComma.push(p + ',');
          } else {
            tempComma.push(p);
          }
        }
      } else {
        tempComma.push(s);
      }
    }
    segments = tempComma;

    // 2. Split Phrasal Modals & Connectors (Split Before and After to preserve modals & isolate subject)
    const pureModals = ["should", "must", "could", "will", "would", "can", "might", "may", "is", "are", "was", "were", "am", "Is", "Are", "Was", "Were", "Am"];
    const allBeforeAndAfter = [...pureModals, ...phrasalModals, ...splitBeforeAndAfter].sort((a, b) => b.length - a.length);
    for (let marker of allBeforeAndAfter) {
      segments = applySplitBeforeAndAfter(segments, marker);
    }

    // 3. Split Before (Action Verbs, Participle Clauses, Relative Clause Connectors)
    const sortedBefore = [...splitBefore].sort((a, b) => b.length - a.length);
    for (let marker of sortedBefore) {
      segments = applySplitBefore(segments, marker);
    }
  }

  // ─── FALLBACKS FOR BOTH LANGUAGES ───
  if (segments.length < 3) {
    if (isEngToTr) {
      const prepMarkersTr = ["ile", "veya", "ve", "olarak", "altında", "önce", "sonra", "karşın", "rağmen"];
      for (let prep of prepMarkersTr) {
        if (segments.length >= 3) break;
        segments = applySplitBefore(segments, prep);
      }
    } else {
      const prepMarkers = ["in", "on", "at", "for", "with", "by", "from", "to", "about", "that", "which", "who", "when", "while"];
      for (let prep of prepMarkers) {
        if (segments.length >= 3) break;
        segments = applySplitBefore(segments, prep);
      }
    }
  }

  // Final fallback
  if (segments.length < 3) {
    const words = fullSentence.split(' ');
    // If the sentence is short (4 words or less), split it into individual words (chunkSize = 1)
    // to keep the exercise interactive and meaningful.
    const chunkSize = words.length <= 4 ? 1 : Math.max(2, Math.ceil(words.length / 3));
    segments = [];
    for (let i = 0; i < words.length; i += chunkSize) {
      segments.push(words.slice(i, i + chunkSize).join(' '));
    }
  }

  return segments.map(s => s.trim()).filter(s => s.length > 0);
}

// ── Kelime Bankası ──────────────────────────────────────────
function renderWordBank(container, question) {
  // Clean up any inline HTML style tags and residues from correctOrder and words arrays
  if (Array.isArray(question.correctOrder)) {
    const isPreSegmented = question.correctOrder.some(w => w.includes(' '));
    if (isPreSegmented) {
      const cleanTargetWords = question.correctOrder.map(w => w.replace(/<[^>]+>/g, '').trim()).filter(Boolean);
      const rawDistractors = Array.isArray(question.words)
        ? question.words.filter(w => !question.correctOrder.includes(w))
        : [];
      const cleanDistractors = rawDistractors
        .map(w => w.replace(/<[^>]+>/g, '').trim())
        .filter(Boolean)
        .filter(w => !cleanTargetWords.includes(w));
      
      question.correctOrder = cleanTargetWords;
      question.words = [...cleanTargetWords, ...cleanDistractors];
    } else {
      const rawTargetSentence = question.correctOrder.join(' ');
      const cleanTargetSentence = rawTargetSentence.replace(/<[^>]+>/g, '');
      const cleanTargetWords = cleanTargetSentence.split(/\s+/)
        .map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").trim())
        .filter(Boolean);
      
      const rawDistractors = Array.isArray(question.words)
        ? question.words.filter(w => !question.correctOrder.includes(w))
        : [];
      const cleanDistractors = rawDistractors
        .map(w => w.replace(/<[^>]+>/g, '').replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").trim())
        .filter(Boolean)
        .filter(w => !cleanTargetWords.includes(w));
      
      question.correctOrder = cleanTargetWords;
      question.words = [...cleanTargetWords, ...cleanDistractors];
    }
  }

  // Apply grammatical chunking to all word ordering sentences with 3 or more elements
  if (Array.isArray(question.correctOrder) && question.correctOrder.length >= 3 && !question.correctOrder.some(w => w.includes(' '))) {
    const fullSentence = question.correctOrder.join(' ');
    const isEngToTr = question.isEngToTr !== undefined
      ? question.isEngToTr
      : (detectPromptDirection(question.prompt) === true);
    const segments = segmentSentence(fullSentence, isEngToTr);
    const distractors = question.words.filter(w => !question.correctOrder.includes(w));
    
    question.correctOrder = segments;
    question.words = [...segments, ...distractors];
  }

  // Generate English modal distractors dynamically for English word bank questions
  if (Array.isArray(question.correctOrder) && question.words) {
    const pureModals = ["should", "must", "could", "will", "would", "can", "might", "may"];
    const capitalPureModals = ["Should", "Must", "Could", "Will", "Would", "Can", "Might", "May"];
    
    let foundModal = "";
    let isCapitalized = false;
    for (let m of pureModals) {
      if (question.correctOrder.includes(m)) {
        foundModal = m;
        break;
      }
    }
    if (!foundModal) {
      for (let m of capitalPureModals) {
        if (question.correctOrder.includes(m)) {
          foundModal = m;
          isCapitalized = true;
          break;
        }
      }
    }
    
    if (foundModal) {
      const conjunctions = ["although", "because", "before", "after", "however", "and", "or", "while", "Although", "Because", "Before", "After", "However", "And", "Or", "While"];
      question.words = question.words.filter(w => !conjunctions.includes(w));
      
      const lowerFound = foundModal.toLowerCase();
      const listToChoose = isCapitalized ? capitalPureModals : pureModals;
      const extraModals = listToChoose.filter(m => m.toLowerCase() !== lowerFound);
      
      let count = 0;
      for (let extra of extraModals) {
        if (count >= 2) break;
        if (!question.words.includes(extra)) {
          question.words.push(extra);
          count++;
        }
      }
    }
  }

  const shuffledWords = [...question.words].sort(() => Math.random() - 0.5);

  const isEngToTr = question.isEngToTr !== undefined
    ? question.isEngToTr
    : (detectPromptDirection(question.prompt) === true);

  // Eğer Türkçe çeviri/dizme isteniyorsa (isEngToTr == true), gösterilecek kaynak cümle İngilizce olmalıdır.
  let displaySentence = "";
  if (isEngToTr) {
    displaySentence = question.sentence || question.enSentence || question.paragraph || question.mainSentence || (question.sentenceTokens ? question.sentenceTokens.join(' ') : "") || "";
  } else {
    displaySentence = question.translation || question.trSentence || "";
  }

  let formattedSourceText = displaySentence ? makeTextHoverable(displaySentence) : "";

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    ${formattedSourceText ? `<p class="quiz-translation">${formattedSourceText}</p>` : ''}
    <div class="wb-sentence" id="wb-sentence"></div>
    <div class="wb-bank" id="wb-bank">
      ${shuffledWords.map((w, i) => `
        <button class="wb-word" data-word="${escapeAttr(w)}" data-idx="${i}">${w}</button>
      `).join('')}
    </div>
  `;

  const sentenceContainer = document.getElementById('wb-sentence');
  const selectedWords = [];

  container.querySelectorAll('.wb-word').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked) return;

      if (btn.classList.contains('in-sentence')) {
        // Cümleden kaldır
        const word = btn.dataset.word;
        const idx = selectedWords.indexOf(word);
        if (idx > -1) selectedWords.splice(idx, 1);
        btn.classList.remove('in-sentence');

        // Orijinal kelimeyi tekrar göster
        const original = container.querySelector(`.wb-word[data-word="${word}"]:not(.in-sentence).used`);
        if (original) original.classList.remove('used');

        updateSentenceDisplay();
        return;
      }

      if (btn.classList.contains('used')) return;

      btn.classList.add('used');
      selectedWords.push(btn.dataset.word);

      // Cümleye ekle
      const sentenceWord = document.createElement('button');
      sentenceWord.className = 'wb-word in-sentence';
      sentenceWord.dataset.word = btn.dataset.word;
      sentenceWord.textContent = btn.dataset.word;
      sentenceWord.addEventListener('click', () => {
        if (isAnswerChecked) return;
        const idx = selectedWords.indexOf(sentenceWord.dataset.word);
        if (idx > -1) selectedWords.splice(idx, 1);
        sentenceWord.remove();
        btn.classList.remove('used');
        updateSentenceDisplay();
      });
      sentenceContainer.appendChild(sentenceWord);

      updateSentenceDisplay();
    });
  });

  function updateSentenceDisplay() {
    sentenceContainer.classList.toggle('has-words', selectedWords.length > 0);
    selectedAnswer = selectedWords.length > 0 ? [...selectedWords] : null;
    document.getElementById('btn-check').disabled = false; // Keep enabled to allow click validation & shake feedback
  }
}

// ── Eşleştirme ──────────────────────────────────────────────
function applyReadingPassageHighlights() {
  const passageBox = document.querySelector('.reading-passage-box');
  if (!passageBox) return;



  if (typeof window.completedReadingHighlights === 'undefined') {
    window.completedReadingHighlights = [];
  }

  if (!passageBox.dataset.originalHtml) {
    passageBox.dataset.originalHtml = passageBox.innerHTML;
  }

  let html = passageBox.dataset.originalHtml;

  const sortedHighlights = [...new Set(window.completedReadingHighlights)]
    .filter(Boolean)
    .sort((a, b) => b.length - a.length);

  sortedHighlights.forEach(phrase => {
    // Avoid double wrapping and regex errors
    const cleanPhrase = phrase.replace(/<[^>]+>/g, "").replace(/^[\.\?!,;\s]+|[\.\?!,;\s]+$/g, "");
    if (cleanPhrase.length < 3) return;
    
    const escaped = cleanPhrase.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    const regex = new RegExp(`(?<!<[^>]*)${escaped}(?![^<]*>)`, 'gi');
    html = html.replace(regex, match => {
      return `<span style="background: rgba(46, 204, 113, 0.12); color: #2ecc71; border-bottom: 2px dashed #2ecc71; border-radius: 4px; padding: 1px 3px; font-weight: bold; transition: all 0.3s ease;">${match}</span>`;
    });
  });

  passageBox.innerHTML = html;
}

function formatEnglishInfinitiveHighlight(text) {
  if (!text) return '';
  let res = text;
  res = res.replace(/\b(which(?:\s+[a-zA-Z]+){1,4}\s+to)\s+([a-zA-Z]+)\b/gi, (match, p1, p2) =>
    `<span style="color: #9333ea; font-weight: 700;">${p1} ${p2}</span>`);
  res = res.replace(/\b(in order to|so as to|how to|where to|when to|what to)\s+([a-zA-Z]+)\b/gi, (match, p1, p2) =>
    `<span style="color: #9333ea; font-weight: 700;">${p1} ${p2}</span>`);
  res = res.replace(/\b(for\s+[a-zA-Z\s]{2,35}?\s+to)\s+([a-zA-Z]+)\b/gi, (match, p1, p2) =>
    `<span style="color: #9333ea; font-weight: 700;">${p1} ${p2}</span>`);
  res = res.replace(/(?<!<span[^>]*>)\bto\s+([a-zA-Z]+)\b(?!<\/span>)/gi, (match, p1) => {
    const verb = p1.toLowerCase();
    if (['today', 'tomorrow', 'local', 'the', 'a', 'an', 'this', 'that', 'my', 'your', 'our', 'their', 'his', 'her'].includes(verb)) return match;
    return `<span style="color: #9333ea; font-weight: 700;">to ${p1}</span>`;
  });
  return res;
}

function renderMatching(container, question) {
  // Bazı sorular eşleştirmeyi [sol, sağ] dizisi olarak taşıyor; nesneye
  // çevrilmezse kutular boş çiziliyordu.
  const pairs = (question.pairs || [])
    .map(p => (Array.isArray(p) ? { left: p[0], right: p[1] } : p))
    .filter(p => p && p.left !== undefined && p.right !== undefined);
  question.pairs = pairs;
  // Sağ sütunu Fisher–Yates ile karıştır; `sort(() => Math.random()-0.5)` 4
  // öğede sık sık diziyi hiç değiştirmiyor ve şıklar sol sütunla birebir
  // karşı karşıya kalıyordu. Kimlik sıralaması çıkarsa yeniden karıştır.
  const shuffledRight = (() => {
    const arr = [...pairs];
    if (arr.length < 2) return arr;
    for (let attempt = 0; attempt < 20; attempt++) {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      if (arr.some((p, i) => p.right !== pairs[i].right)) break;
    }
    return arr;
  })();

  // `/^[a-zA-Z]/` yetersizdi: "Belge", "Fiyat" gibi Türkçe sözcükler de ASCII
  // harfle başladığından sol sütun yanlışlıkla İngilizce sanılıp başlıklar ters
  // yazılıyordu. Onun yerine iki sütunu dil işaretlerine göre puanlayıp
  // karşılaştırıyoruz (eşleştirme her zaman bir İngilizce + bir Türkçe taraf).
  const englishScore = (text) => {
    const t = String(text || '').toLowerCase().replace(/<[^>]+>/g, ' ');
    let score = 0;
    if (/[çşğıöü]/i.test(t)) score -= 3;
    const trMarkers = t.match(/\b\w*(?:midir|mıdır|mudur|müdür|mıydı|miydi|muydu|müydü|değil|için|ması|mesi)\b|\b(?:mi|mı|mu|mü|ve|bir|bu|şu|da|de|ile)\b|\w+(?:dır|dir|dur|dür|dığı|diği|lar|ler)\b/g) || [];
    score -= trMarkers.length * 2;
    const enWords = t.match(/\b(?:the|is|are|was|were|a|an|do|does|did|why|what|how|of|to|and|in|on|for|with|by|has|have|will|would|should|can|could|not|this|that|it|be)\b/g) || [];
    score += enWords.length * 2;
    return score;
  };
  const isLeftEnglish = pairs.length > 0 &&
    englishScore(pairs[0].left) > englishScore(pairs[0].right);
  const leftHeader = question.leftHeader || (isLeftEnglish ? "İngilizce İfade" : "Türkçe Karşılık");
  const rightHeader = question.rightHeader || (isLeftEnglish ? "Türkçe Karşılık" : "İngilizce İfade");

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <div class="match-grid">
      <span class="match-col-header">${leftHeader}</span>
      <span class="match-col-header">${rightHeader}</span>
      ${pairs.map((pair, i) => `
        <button class="match-item match-left" data-left="${escapeAttr(pair.left)}" data-pair-index="${i}">${isLeftEnglish ? formatEnglishInfinitiveHighlight(pair.left) : pair.left}</button>
        <button class="match-item match-right" data-right="${escapeAttr(shuffledRight[i].right)}">${!isLeftEnglish ? formatEnglishInfinitiveHighlight(shuffledRight[i].right) : makeTextHoverable(shuffledRight[i].right, true)}</button>
      `).join('')}
    </div>
  `;

  matchState = {
    pairs: pairs,
    selectedLeftBtn: null,
    selectedRightBtn: null,
    matchedCount: 0,
    totalPairs: pairs.length,
    wrongAttempts: 0
  };

  container.querySelectorAll('.match-left').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked || btn.classList.contains('matched')) return;
      container.querySelectorAll('.match-left').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      matchState.selectedLeftBtn = btn;
      tryMatch(container, question);
    });
  });

  container.querySelectorAll('.match-right').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked || btn.classList.contains('matched')) return;
      container.querySelectorAll('.match-right').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      matchState.selectedRightBtn = btn;

      // Highlight target chunk in reading-passage-box if it exists
      const passageBox = document.querySelector('.reading-passage-box');
      if (passageBox) {
        if (!passageBox.dataset.originalHtml) {
          passageBox.dataset.originalHtml = passageBox.innerHTML;
        }
        const originalHtml = passageBox.dataset.originalHtml;
        const rightText = btn.dataset.right;
        const escaped = rightText.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
        const regex = new RegExp(`(${escaped})`, 'gi');
        passageBox.innerHTML = originalHtml.replace(regex, `<mark style="background: #ffe066; color: #000; font-weight: bold; border-radius: 4px; padding: 2px 4px; box-shadow: 0 0 8px rgba(255,224,102,0.6);">$1</mark>`);
      }

      tryMatch(container, question);
    });
  });
}

function tryMatch(container, question) {
  if (!matchState.selectedLeftBtn || !matchState.selectedRightBtn) return;

  const leftText = matchState.selectedLeftBtn.dataset.left;
  const rightText = matchState.selectedRightBtn.dataset.right;

  // Check if this pair exists in correct pairs
  const isCorrectMatch = question.pairs.some(p => p.left === leftText && p.right === rightText);

  if (isCorrectMatch) {
    // Doğru eşleşme
    if (typeof window.completedReadingHighlights === 'undefined') {
      window.completedReadingHighlights = [];
    }
    window.completedReadingHighlights.push(leftText.trim());
    window.completedReadingHighlights.push(rightText.trim());
    applyReadingPassageHighlights();

    const leftBtn = matchState.selectedLeftBtn;
    const rightBtn = matchState.selectedRightBtn;

    leftBtn.classList.remove('selected');
    rightBtn.classList.remove('selected');
    leftBtn.classList.add('matched');
    rightBtn.classList.add('matched');

    matchState.matchedCount++;
  } else {
    // Yanlış eşleşme
    matchState.wrongAttempts++;

    const leftBtn = matchState.selectedLeftBtn;
    const rightBtn = matchState.selectedRightBtn;

    if (leftBtn) leftBtn.classList.add('wrong-flash');
    if (rightBtn) rightBtn.classList.add('wrong-flash');

    setTimeout(() => {
      if (leftBtn) { leftBtn.classList.remove('selected', 'wrong-flash'); }
      if (rightBtn) { rightBtn.classList.remove('selected', 'wrong-flash'); }
    }, 500);
  }

  matchState.selectedLeftBtn = null;
  matchState.selectedRightBtn = null;

  // Re-apply correct highlights after matching cleanup
  applyReadingPassageHighlights();

  // Tüm çiftler eşleşti mi?
  if (matchState.matchedCount === matchState.totalPairs) {
    selectedAnswer = matchState.wrongAttempts === 0 ? 'perfect' : 'with-errors';
    // Eşleştirme tamamlandı, otomatik kontrol
    setTimeout(() => {
      checkAnswer();
    }, 400);
  }
}

// ── Boşluk Doldurma - Açılır Menü (Dropdown) ──────────────────
function getOptionMeaning(question, opt) {
  if (!opt) return '';
  if (question && question.noOptionMeanings) return '';
  opt = String(opt).replace(/<[^>]+>/g, '').trim();
  if (!opt) return '';
  const lowerOpt = opt.toLowerCase();
  if (lowerOpt.startsWith('to ') || lowerOpt.startsWith('how to') || lowerOpt.startsWith('where to') || lowerOpt.startsWith('when to') || lowerOpt.startsWith('which ') || lowerOpt.startsWith('what to')) {
    return '';
  }
  if (question && question.optionMeanings && question.optionMeanings[opt]) {
    return question.optionMeanings[opt];
  }
  if (question && question.explanations && question.explanations[opt]) {
    const exp = String(question.explanations[opt]);
    const match = exp.match(/["'“]([^"'”]+)["'”]/);
    if (match && match[1]) {
      return match[1].trim();
    }
  }

  const cleanOpt = opt.toLowerCase().trim().replace(/^[\s;,\.\:]+|[\s;,\.\:]+$/g, '');

  // Comprehensive dictionary of conjunctions, linkers, prepositions, phrasal modals & multi-word expressions
  const phrasalMap = {
    "such": "öyle / o kadar (such ... that)",
    "for this reason": "bu nedenle / bu yüzden",
    "at the same time": "aynı zamanda / bir yandan da",
    "by comparison": "kıyaslandığında / buna kıyasla",
    "paradoxically": "çelişkili biçimde / ne gariptir ki",
    "additionally": "ayrıca / ek olarak",
    "alternatively": "alternatif olarak / ya da",
    "subsequently": "sonrasında / ardından",
    "simultaneously": "eşzamanlı olarak / aynı anda",
    "unfortunately": "ne yazık ki",
    "fortunately": "neyse ki",
    "meanwhile": "bu arada / bu esnada",
    "instead": "onun yerine / bunun yerine",
    "albeit": "her ne kadar / -e rağmen",
    "whether": "olup olmadığı / ister",
    "than": "-den (karşılaştırma)",
    "even though": "-e rağmen",
    "much as": "-e rağmen / her ne kadar",
    "although": "-e rağmen / karşın",
    "even if": "-se bile",
    "though": "-e rağmen / yine de",
    "despite": "-e rağmen",
    "in spite of": "-e rağmen",
    "notwithstanding": "-e rağmen / -e karşın",
    "in contrast to": "-in aksine",
    "whereas": "-e karşın (oysa)",
    "while": "iken / -e rağmen",
    "unlike": "-in aksine",
    "contrary to": "-in aksine",
    "as opposed to": "-in aksine",
    "conversely": "aksine / tersine",
    "on the other hand": "diğer yandan",
    "on the contrary": "aksine / tersine",
    "however": "ancak / yine de",
    "nevertheless": "yine de / buna rağmen",
    "nonetheless": "yine de / buna rağmen",
    "even so": "yine de / öyle olsa bile",
    "inasmuch as": "-dığı için / -den dolayı",
    "now that": "-dığı için / artık",
    "seeing that": "-dığı için / mademki",
    "given that": "-dığı göz önüne alınırsa",
    "because of": "-den dolayı / yüzünden",
    "due to": "-den dolayı / yüzünden",
    "owing to": "-den dolayı / yüzünden",
    "on account of": "-den dolayı / yüzünden",
    "in view of": "-den dolayı / göz önüne alındığında",
    "as a consequence of": "-in sonucu olarak",
    "as a result of": "-in sonucu olarak",
    "thanks to": "sayesinde",
    "therefore": "bu yüzden / dolayısıyla",
    "hence": "bu yüzden / dolayısıyla",
    "thus": "bu yüzden / böylece",
    "consequently": "sonuç olarak",
    "as a result": "sonuç olarak",
    "accordingly": "bu doğrultuda / dolayısıyla",
    "that's why": "bu yüzden",
    "furthermore": "dahası / ayrıca",
    "moreover": "dahası / ayrıca",
    "besides": "ayrıca / -in yanı sıra",
    "as well as": "-in yanı sıra",
    "in addition to": "-in yanı sıra",
    "in addition": "ayrıca / ek olarak",
    "along with": "-in yanı sıra",
    "likewise": "aynı şekilde / benzer şekilde",
    "similarly": "aynı şekilde / benzer şekilde",
    "such as": "gibi (örneğin)",
    "for example": "örneğin",
    "for instance": "örneğin",
    "in other words": "başka bir deyişle",
    "namely": "yani (adlandırmak gerekirse)",
    "that is to say": "yani / başka bir deyişle",
    "in order to": "-mek amacıyla",
    "so as to": "-mek amacıyla",
    "with a view to": "-amacıyla",
    "for the purpose of": "-amacıyla",
    "by virtue of": "sayesinde / -den dolayı",
    "on the grounds of": "gerekçesiyle",
    "so that": "-sin diye / amacıyla",
    "in order that": "-sin diye / amacıyla",
    "except for": "-den başka / hariç",
    "aside from": "-den başka / hariç",
    "apart from": "-den başka / hariç",
    "according to": "-e göre",
    "in terms of": "açısından / bakımından",
    "with regard to": "ile ilgili olarak",
    "in accordance with": "-e uygun olarak",
    "in favor of": "lehine / yararına",
    "instead of": "-in yerine",
    "rather than": "-den ziyade / yerine",
    "for the sake of": "uğruna / hatırına",
    "as if": "sanki / -miş gibi",
    "as though": "sanki / -miş gibi",
    "when it comes to": "söz konusu olduğunda",
    "by means of": "aracılığıyla / vasıtasıyla",
    "by reason of": "-den dolayı / yüzünden",
    "that is": "yani / başka bir deyişle",
    "in that": "-mesi bakımından / çünkü",
    "provided that": "şartıyla",
    "providing that": "şartıyla",
    "as long as": "sürece / şartıyla",
    "so long as": "sürece / şartıyla",
    "on condition that": "şartıyla",
    "unless": "-madıkça / aksi takdirde",
    "in case of": "durumunda / halinde",
    "in case": "durumunda / ihtimaline karşı",
    "for fear that": "korkusuyla",
    "lest": "korkusuyla / -mesin diye",
    "regardless of": "bakılmaksızın / ne olursa olsun",
    "irrespective of": "bakılmaksızın",
    "no matter": "ne olursa olsun",
    "because": "çünkü / -dığı için",
    "since": "-dığı için / beri",
    "as": "-dığı için / olarak / gibi",
    "but": "ama / fakat",
    "yet": "yine de / fakat",
    "still": "yine de / hala",
    "so": "bu yüzden / öyle",
    "or": "veya / ya da",
    "and": "ve",
    "nor": "ne de",
    "also": "ayrıca / de",
    "certain to": "kesin",
    "reluctant to": "gönülsüz / isteksiz",
    "unable to": "yapamamak",
    "doomed to": "mahkum (kötü sona)",
    "bound to": "kaçınılmaz",
    "likely to": "muhtemel",
    "unlikely to": "beklenmeyen",
    "supposed to": "bekleniyor / gerekli",
    "obliged to": "zorunlu",
    "unwilling to": "isteksiz / gönülsüz",
    "willing to": "istekli",
    "accustomed to": "alışkın",
    "used to": "alışkın",
    "about to": "üzere",
    "be to": "planlanan",
    "be able to": "yapabilmek",
    "was able to": "yapabildi",
    "were able to": "yapabildiler",
    "have to": "zorunda olmak",
    "has to": "zorunda olmak",
    "had to": "zorunda kaldı",
    "would rather": "tercih eder",
    "would prefer": "tercih eder",
    "had better": "iyi olur",
    "ought to": "malı-meli"
  };

  if (phrasalMap[cleanOpt]) {
    return phrasalMap[cleanOpt];
  }

  const sortedKeys = Object.keys(phrasalMap).sort((a, b) => b.length - a.length);
  for (const key of sortedKeys) {
    const reg = new RegExp(`(?:^|\\b)${key.replace(/ /g, '\\s+')}(?:\\b|$)`, 'i');
    if (reg.test(cleanOpt)) {
      return phrasalMap[key];
    }
  }

  const wordMeaning = typeof getWordMeaning === 'function' ? getWordMeaning(cleanOpt) : '';
  if (wordMeaning) return wordMeaning;

  // Son çare: uygulamanın kendi bağlaç matrislerinden türetilen anlamlar.
  // phrasalMap elle yazıldığı için "for this reason", "in fact" gibi kalıplar
  // eksik kalıyordu; matrislerde bunların Türkçe karşılığı zaten mevcut.
  const fromMatrix = getConnectorMeaning(cleanOpt);
  if (fromMatrix) return fromMatrix;

  return '';
}

// TRANSITIONS / CAUSE_EFFECT / TIME matrislerindeki term–meaning çiftlerinden
// tek seferlik bir arama tablosu kurar. Terimler "however / nevertheless" gibi
// eğik çizgiyle ayrılmış olabildiğinden her parça ayrı anahtar olarak eklenir.
let _connectorMeaningMap = null;
function getConnectorMeaning(opt) {
  if (!opt) return '';
  if (!_connectorMeaningMap) {
    _connectorMeaningMap = {};
    const add = (term, meaning) => {
      if (!term || !meaning) return;
      String(term).split('/').forEach(part => {
        const k = part.replace(/\([^)]*\)/g, '').trim().toLowerCase();
        if (k && !_connectorMeaningMap[k]) _connectorMeaningMap[k] = String(meaning).trim();
      });
    };
    [typeof TRANSITIONS_MATRIX_DATA !== 'undefined' ? TRANSITIONS_MATRIX_DATA : null,
     typeof CAUSE_EFFECT_DATA !== 'undefined' ? CAUSE_EFFECT_DATA : null,
     typeof TIME_MATRIX_DATA !== 'undefined' ? TIME_MATRIX_DATA : null].forEach(src => {
      if (!src) return;
      Object.values(src).forEach(list => (list || []).forEach(item => add(item.term, item.meaning)));
    });
  }
  return _connectorMeaningMap[opt] || '';
}


// Açılır kutunun "dışarı tıklayınca kapan" dinleyicisi. Her soru render'ında
// yenisi eklendiği için öncekini kaldırmak üzere referansı saklıyoruz.
let fbDropdownOutsideHandler = null;

function renderFillBlankDropdown(container, question) {
  // Normalize arguments in case it is called as renderFillBlankDropdown(question)
  if (!question && container && !container.nodeType) {
    question = container;
    container = document.getElementById("exercise-container") || document.querySelector(".quiz-card-body");
  }

  const parts = question.sentence.split(/_{3,}/);

  // If sentence has multiple blanks (2 or more), delegate to renderFillBlank for proper multi-blank button display
  if (parts.length > 2) {
    renderFillBlank(container, question);
    return;
  }

  const part0Html = makeTextHoverable(parts[0]);
  const part1Html = parts[1] ? makeTextHoverable(parts[1]) : '';
  const displayPrompt = question.prompt === 'Boşluğu doldur' ? 'Boşluğu doldur!' : question.prompt;

  const menuItemsHtml = question.options.map((opt, i) => {
    const meaning = getOptionMeaning(question, opt);
    const displayText = meaning ? `<strong>${opt}</strong> <span style="opacity: 0.75; font-weight: 400; font-size: 0.9em; margin-left: 6px;">/ ${meaning}</span>` : `<strong>${opt}</strong>`;
    return `
      <div class="custom-dropdown-item" data-index="${i}" style="padding: 10px 16px; border-radius: 8px; cursor: pointer; font-size: 1.05rem; color: var(--text-primary); transition: background 0.15s ease; border-bottom: 1px solid rgba(128,128,128,0.1); text-align: left; white-space: normal; word-break: break-word;">
        ${displayText}
      </div>
    `;
  }).join('');

  container.innerHTML = `
    <div class="question-prompt-title quiz-prompt">${displayPrompt}</div>
    <div class="question-sentence-body dropdown-sentence-layout" style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 2.2; display: block; width: 100%;">
      ${part0Html}
      <span class="custom-dropdown-wrapper" style="position: relative; display: inline-block; vertical-align: middle; margin: 0 6px;">
        <button class="custom-dropdown-trigger" id="fb-custom-trigger" style="min-width: 140px; padding: 6px 18px; border: 2px dashed var(--color-primary, #9c27b0); border-radius: 10px; background: rgba(156, 39, 176, 0.08); color: var(--color-primary, #9c27b0); font-weight: 600; font-size: 1.1rem; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 8px; transition: all 0.2s ease;">
          <span class="trigger-label" id="fb-trigger-label">Seçin...</span>
          <span class="trigger-arrow" id="fb-trigger-arrow" style="font-size: 0.75rem; transition: transform 0.2s ease;">▼</span>
        </button>
        <div class="custom-dropdown-menu" id="fb-custom-menu" style="display: none; position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%); width: 340px; max-width: calc(100vw - 32px); box-sizing: border-box; white-space: normal; word-break: break-word; background: var(--bg-card, #ffffff); border: 1px solid var(--border-color, rgba(156, 39, 176, 0.3)); border-radius: 12px; box-shadow: 0 12px 32px rgba(0,0,0,0.22); z-index: 1000; overflow: hidden; padding: 6px; backdrop-filter: blur(12px);">
          ${menuItemsHtml}
        </div>
      </span>
      ${part1Html}
    </div>
  `;

  const triggerBtn = container.querySelector('#fb-custom-trigger');
  const menuEl = container.querySelector('#fb-custom-menu');
  const labelEl = container.querySelector('#fb-trigger-label');
  const arrowEl = container.querySelector('#fb-trigger-arrow');
  const itemEls = container.querySelectorAll('.custom-dropdown-item');

  function toggleMenu(show) {
    const isVisible = show !== undefined ? show : menuEl.style.display === 'none';
    menuEl.style.display = isVisible ? 'block' : 'none';
    if (arrowEl) {
      arrowEl.style.transform = isVisible ? 'rotate(180deg)' : 'rotate(0deg)';
    }
    if (isVisible) {
      menuEl.style.left = '50%';
      menuEl.style.right = 'auto';
      menuEl.style.transform = 'translateX(-50%)';

      requestAnimationFrame(() => {
        const menuRect = menuEl.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();
        const padding = 12;

        const leftEdge = containerRect.left + padding;
        const rightEdge = containerRect.right - padding;

        if (menuRect.left < leftEdge) {
          const shift = Math.round(leftEdge - menuRect.left);
          menuEl.style.transform = 'translateX(calc(-50% + ' + shift + 'px))';
        } else if (menuRect.right > rightEdge) {
          const shift = Math.round(menuRect.right - rightEdge);
          menuEl.style.transform = 'translateX(calc(-50% - ' + shift + 'px))';
        }
      });
    }

  }
  if (triggerBtn && menuEl) {
    triggerBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (isAnswerChecked) return;
      toggleMenu();
    });

    itemEls.forEach(item => {
      item.addEventListener('mouseenter', () => {
        item.style.background = 'rgba(156, 39, 176, 0.12)';
      });
      item.addEventListener('mouseleave', () => {
        item.style.background = 'transparent';
      });

      item.addEventListener('click', (e) => {
        e.stopPropagation();
        if (isAnswerChecked) return;

        const idx = parseInt(item.dataset.index);
        selectedAnswer = idx;

        const optText = question.options[idx];
        const englishOnly = optText.split(/\s*\/\s*/)[0].trim();
        if (labelEl) labelEl.textContent = englishOnly;

        triggerBtn.style.borderStyle = 'solid';
        triggerBtn.style.background = 'var(--color-primary, #9c27b0)';
        triggerBtn.style.color = '#ffffff';

        toggleMenu(false);

        const checkBtn = document.getElementById('btn-check');
        if (checkBtn) checkBtn.disabled = isNaN(selectedAnswer);
      });
    });

    // Menü açıkken, açılır kutunun kendisi dışında herhangi bir yere (cümle
    // metni, boşluk, sayfa boşluğu vb.) tıklanınca menü kapanmalı.
    const dropdownWrapper = container.querySelector('.custom-dropdown-wrapper');
    if (fbDropdownOutsideHandler) {
      document.removeEventListener('click', fbDropdownOutsideHandler);
    }
    fbDropdownOutsideHandler = function(e) {
      if (menuEl.style.display === 'none') return;
      if (dropdownWrapper && dropdownWrapper.contains(e.target)) return;
      toggleMenu(false);
    };
    document.addEventListener('click', fbDropdownOutsideHandler);
  }
}

// ── Boşluk Doldurma - Serbest Metin (Text) ────────────────────
function renderFillBlankText(container, question) {
  const parts = question.sentence.split(/_{3,}/);

  const part0Html = makeTextHoverable(parts[0]);
  const part1Html = parts[1] ? makeTextHoverable(parts[1]) : '';

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <div style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 1.6;">
      ${part0Html}<input type="text" class="inline-text-input" id="fb-text-input" autocomplete="off" placeholder="yazın">${part1Html}
    </div>
  `;

  const inputEl = document.getElementById('fb-text-input');
  setTimeout(() => inputEl.focus(), 100);

  inputEl.addEventListener('input', () => {
    if (isAnswerChecked) return;
    selectedAnswer = inputEl.value.trim();
    document.getElementById('btn-check').disabled = selectedAnswer.length === 0;
  });
}

// ── Boşluk Doldurma - Butonlu Seçenekler (fill-blank) ──────────
function renderFillBlank(container, question) {
  // Normalize arguments in case it is called as renderFillBlank(question)
  if (!question && container && !container.nodeType) {
    question = container;
    container = document.getElementById("exercise-container") || document.querySelector(".quiz-card-body");
  }

  // Support single or multiple blanks (3 or more underscores)
  const parts = question.sentence.split(/_{3,}/);
  let sentenceInnerHtml = '';
  parts.forEach((part, pIdx) => {
    sentenceInnerHtml += makeTextHoverable(part);
    if (pIdx < parts.length - 1) {
      sentenceInnerHtml += `<span class="fb-blank" id="fb-blank-word-${pIdx}">______</span>`;
    }
  });

  const optionsHtml = question.options.map((opt, i) => {
    const meaning = getOptionMeaning(question, opt);
    const displayText = (meaning && !opt.includes('/')) ? `${opt} <span style="opacity: 0.75; font-weight: 400; font-size: 0.9em; margin-left: 6px;">/ ${meaning}</span>` : opt;
    return `<button class="fb-option" data-index="${i}">
      <span class="fb-number">${i + 1}</span>
      <span class="fb-text">${displayText}</span>
    </button>`;
  }).join('');

  const displayPrompt = question.prompt === 'Boşluğu doldur' ? 'Boşluğu doldur!' : question.prompt;

  container.innerHTML = `
    <p class="quiz-prompt">${displayPrompt}</p>
    <div class="fb-sentence" style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 1.6;">
      ${sentenceInnerHtml}
    </div>
    <div class="fb-options">
      ${optionsHtml}
    </div>
  `;

  container.querySelectorAll('.fb-option').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked) return;
      container.querySelectorAll('.fb-option').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      
      const idx = parseInt(btn.dataset.index);
      selectedAnswer = idx;
      
      const selectedOptText = question.options[idx] || '';
      const tokens = selectedOptText.split(/\s*\/\s*/);

      for (let pIdx = 0; pIdx < parts.length - 1; pIdx++) {
        const blank = document.getElementById(`fb-blank-word-${pIdx}`);
        if (blank) {
          blank.innerHTML = tokens[pIdx] || tokens[0] || '______';
        }
      }
      
      document.getElementById('btn-check').disabled = false;

      const isTargetUnit = question.translation ? true : false;
      const isCorrect = idx === question.correctIndex;

      setTimeout(() => {
        checkAnswer();
      }, 250);
    });
  });
}

// ── Scrambled Words Translation Gate ────────────────────────
function startTranslationGate(container, question) {
  isTranslationGateActive = true;
  isTranslationGateTriggered = true;
  
  // Set primary check button state
  const btnCheck = document.getElementById('btn-check');
  btnCheck.disabled = true;
  btnCheck.textContent = 'ÇEVİRİYİ KONTROL ET';

  // Hide skip button to focus on translation
  const btnSkip = document.getElementById('btn-skip');
  if (btnSkip) {
    btnSkip.style.display = 'none';
  }

  // Make the sentence complete with highlighted answer
  let completedSentence = question.sentence || question.enSentence || question.en || "";
  if (question.options && typeof question.correctIndex === 'number' && question.options[question.correctIndex]) {
    const correctWord = question.options[question.correctIndex];
    if (correctWord && completedSentence.includes("___")) {
      const tokens = String(correctWord).split(/\s*\/\s*/);
      const parts = completedSentence.split(/_{3,}/);
      let filledSentence = '';
      parts.forEach((part, pIdx) => {
        filledSentence += part;
        if (pIdx < parts.length - 1) {
          const tokenVal = tokens[pIdx] || tokens[0] || '';
          filledSentence += `<span class="fb-blank" style="color: var(--color-correct); border-bottom-color: var(--color-correct); font-weight: bold; background: var(--color-correct-bg); padding: 2px 8px; border-radius: 4px;">${tokenVal}</span>`;
        }
      });
      completedSentence = filledSentence;
    }
  }
  completedSentence = makeTextHoverable(completedSentence);

  // Clean translation and split into words or grammatical blocks if > 12 words
  let correctWords;
  const rawWordCount = question.translation.split(/\s+/).filter(Boolean).length;
  if (rawWordCount >= 3) {
    correctWords = segmentSentence(question.translation, true);
  } else {
    const rawWords = question.translation.split(/\s+/);
    const cleanWord = (w) => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").trim();
    correctWords = rawWords.map(cleanWord).filter(Boolean);
  }
  
  // Distractors
  const distractorsList = ["farklı", "başlayana", "her zaman", "sonra", "önce", "tüm", "ancak", "çünkü", "kadar", "yeni", "hızlı", "güvenli", "sistem", "sunucu", "ekip", "uygulama", "veri", "kod", "zaman", "büyük", "olarak"];
  const correctCleaned = correctWords.map(w => w.toLowerCase());
  const filteredDistractors = distractorsList.filter(d => !correctCleaned.includes(d.toLowerCase()));
  const selectedDistractors = [...filteredDistractors].sort(() => 0.5 - Math.random()).slice(0, 3);
  
  // Combine chips
  let chips = [...correctWords, ...selectedDistractors];
  chips = chips.sort(() => 0.5 - Math.random());
  
  container.innerHTML = `
    <p class="quiz-prompt">Cümleyi Türkçe'ye Çevirin!</p>
    <div class="fb-sentence" style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 1.6;">
      ${completedSentence}
    </div>
    
    <div class="gate-title">Çeviri Geçidi</div>
    <div class="assembled-translation-area" id="assembled-area"></div>
    <div class="scrambled-words-container" id="scrambled-container"></div>
  `;

  const assembledArea = document.getElementById('assembled-area');
  const scrambledContainer = document.getElementById('scrambled-container');

  let assembledWords = [];

  const renderChips = () => {
    assembledArea.innerHTML = '';
    assembledWords.forEach((word, idx) => {
      const chip = document.createElement('button');
      chip.className = 'word-chip';
      chip.textContent = word;
      chip.addEventListener('click', () => {
        assembledWords.splice(idx, 1);
        renderChips();
      });
      assembledArea.appendChild(chip);
    });

    if (assembledWords.length > 0) {
      assembledArea.classList.add('active');
      btnCheck.disabled = false;
    } else {
      assembledArea.classList.remove('active');
      btnCheck.disabled = true;
    }

    scrambledContainer.innerHTML = '';
    chips.forEach((word) => {
      const chip = document.createElement('button');
      chip.className = 'word-chip';
      chip.textContent = word;
      
      const countInAssembled = assembledWords.filter(w => w === word).length;
      const totalInChips = chips.filter(w => w === word).length;
      
      if (countInAssembled >= totalInChips) {
        chip.classList.add('disabled');
      } else {
        chip.addEventListener('click', () => {
          assembledWords.push(word);
          renderChips();
        });
      }
      scrambledContainer.appendChild(chip);
    });
  };

  renderChips();

  onTranslationGateVerify = () => {
    const cleanWordForComparison = (w) => w.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").trim();
    const userCleaned = assembledWords.map(cleanWordForComparison);
    const correctCleaned = correctWords.map(cleanWordForComparison);
    
    const isCorrect = userCleaned.length === correctCleaned.length && userCleaned.every((w, i) => w === correctCleaned[i]);
    
    if (isCorrect) {
      isTranslationGateActive = false;
      onTranslationGateVerify = null;
      wasTranslationCorrect = true;
      
      assembledArea.querySelectorAll('.word-chip').forEach(chip => {
        chip.classList.add('correct-assemble');
        chip.disabled = true;
      });
      scrambledContainer.querySelectorAll('.word-chip').forEach(chip => {
        chip.classList.add('disabled');
        chip.disabled = true;
      });
      
      checkAnswer();
      btnCheck.textContent = 'DEVAM ET';
    } else {
      isTranslationGateActive = false;
      onTranslationGateVerify = null;
      wasTranslationCorrect = false;

      assembledArea.classList.add('shake');
      assembledArea.querySelectorAll('.word-chip').forEach(chip => {
        chip.style.borderColor = 'var(--color-wrong)';
        chip.style.backgroundColor = 'var(--color-wrong-bg)';
        chip.style.color = 'var(--color-wrong)';
        chip.disabled = true;
      });
      scrambledContainer.querySelectorAll('.word-chip').forEach(chip => {
        chip.classList.add('disabled');
        chip.disabled = true;
      });

      checkAnswer();
      btnCheck.textContent = 'DEVAM ET';
    }
  };
}

// ── Tam Metin Çeviri Testi (Klavyeli Girdi) ──────────────────
function renderTranslationText(container, question) {
  const placeholderText = question.isEngToTr ? "Türkçe çeviriyi buraya yazın..." : "İngilizce çeviriyi buraya yazın...";
  
  let headerText = question.isEngToTr ? "Aşağıdaki ifadeyi Türkçe'ye çevirin;" : "Aşağıdaki ifadeyi İngilizce'ye çevirin;";
  
  let sentenceToTranslate = question.isEngToTr ? (question.enSentence || "") : (question.translation || "");
  if (!sentenceToTranslate) {
    sentenceToTranslate = question.enSentence || "";
  }
  if (!sentenceToTranslate) {
    const match = question.prompt.match(/"([^"]+)"/);
    sentenceToTranslate = match ? match[1] : question.prompt;
  }
  
  let sentenceHtml = `"${sentenceToTranslate}"`;
  if (question.isEngToTr) {
    sentenceHtml = `"${makeTextHoverable(sentenceToTranslate)}"`;
  }

  container.innerHTML = `
    <p class="quiz-prompt" style="text-align: center; margin-bottom: 8px;">${headerText}</p>
    <p class="quiz-translation-source" style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 16px 0 24px 0; color: var(--text-primary); line-height: 1.6;">${sentenceHtml}</p>
    <div class="translation-input-wrap">
      <textarea class="translation-textarea" id="translation-text-area" placeholder="${placeholderText}" autocomplete="off"></textarea>
    </div>
  `;

  const textEl = document.getElementById('translation-text-area');
  setTimeout(() => textEl.focus(), 100);

  textEl.addEventListener('input', () => {
    if (isAnswerChecked) return;
    selectedAnswer = textEl.value.trim();
    document.getElementById('btn-check').disabled = selectedAnswer.length === 0;
  });
}

// ── Çoklu Boşluk Doldurma (multiple-fill-blank) ────────────────────
function renderMultipleFillBlank(container, question) {
  const parts = question.sentence.split(/_{3,}/);
  let sentenceHtml = '';
  
  const hasOptions = Array.isArray(question.options) && question.options.length > 0;
  
  parts.forEach((part, index) => {
    sentenceHtml += makeTextHoverable(part);
    if (index < parts.length - 1) {
      if (hasOptions) {
        sentenceHtml += `<span class="inline-text-gap multi-fb-gap" data-index="${index}" style="display: inline-block; min-width: 80px; height: 32px; border-bottom: 2px solid var(--accent-primary); margin: 0 6px; text-align: center; vertical-align: middle; cursor: pointer; color: var(--accent-primary); font-weight: bold; padding: 0 8px; line-height: 32px; transition: background-color 0.2s;">...</span>`;
      } else {
        sentenceHtml += `<input type="text" class="inline-text-input multi-fb-input" data-index="${index}" autocomplete="off" placeholder="...">`;
      }
    }
  });

  let optionsHtml = '';
  if (hasOptions) {
    optionsHtml = `
      <div class="multi-fb-options-container" style="display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 20px;">
        ${question.options.map((opt, i) => `
          <button class="multi-fb-option-chip" data-val="${opt}" style="background: var(--bg-card); border: 1.5px solid var(--border-color); border-radius: var(--radius-md); padding: 8px 16px; font-size: 1rem; color: var(--text-primary); cursor: pointer; transition: all 0.2s; font-weight: bold; font-family: var(--font-heading);">${opt}</button>
        `).join('')}
      </div>
    `;
  }

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    ${question.translation ? `<p class="quiz-translation">${question.translation}</p>` : ''}
    <div style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 2;">
      ${sentenceHtml}
    </div>
    ${optionsHtml}
  `;

  if (hasOptions) {
    const gaps = container.querySelectorAll('.multi-fb-gap');
    const chips = container.querySelectorAll('.multi-fb-option-chip');
    let activeGapIndex = 0;
    
    const updateGapHighlights = () => {
      gaps.forEach((g, idx) => {
        if (idx === activeGapIndex) {
          g.style.borderBottomColor = 'var(--accent-primary)';
          g.style.backgroundColor = 'rgba(139, 126, 200, 0.15)';
        } else {
          g.style.borderBottomColor = 'var(--border-color)';
          g.style.backgroundColor = 'transparent';
        }
      });
    };
    updateGapHighlights();

    gaps.forEach(gap => {
      gap.addEventListener('click', () => {
        if (isAnswerChecked) return;
        const idx = parseInt(gap.dataset.index);
        activeGapIndex = idx;
        
        const val = gap.textContent.trim();
        if (val !== '...') {
          gap.textContent = '...';
          chips.forEach(chip => {
            if (chip.dataset.val === val) {
              chip.disabled = false;
              chip.style.opacity = '1';
              chip.style.pointerEvents = 'auto';
            }
          });
          selectedAnswer = Array.from(gaps).map(g => g.textContent.trim() === '...' ? '' : g.textContent.trim());
          document.getElementById('btn-check').disabled = selectedAnswer.some(s => !s);
        }
        updateGapHighlights();
      });
    });

    chips.forEach(chip => {
      chip.addEventListener('click', () => {
        if (isAnswerChecked) return;
        const val = chip.dataset.val;
        
        const targetGap = gaps[activeGapIndex];
        if (targetGap) {
          const prevVal = targetGap.textContent.trim();
          if (prevVal !== '...') {
            chips.forEach(c => {
              if (c.dataset.val === prevVal) {
                c.disabled = false;
                c.style.opacity = '1';
                c.style.pointerEvents = 'auto';
              }
            });
          }
          
          targetGap.textContent = val;
          chip.disabled = true;
          chip.style.opacity = '0.4';
          chip.style.pointerEvents = 'none';
          
          let nextEmptyIdx = -1;
          for (let i = 0; i < gaps.length; i++) {
            const nextIdx = (activeGapIndex + 1 + i) % gaps.length;
            if (gaps[nextIdx].textContent.trim() === '...') {
              nextEmptyIdx = nextIdx;
              break;
            }
          }
          if (nextEmptyIdx !== -1) {
            activeGapIndex = nextEmptyIdx;
          }
          
          updateGapHighlights();
          
          selectedAnswer = Array.from(gaps).map(g => g.textContent.trim() === '...' ? '' : g.textContent.trim());
          document.getElementById('btn-check').disabled = selectedAnswer.some(s => !s);
        }
      });
    });
  } else {
    const inputs = container.querySelectorAll('.multi-fb-input');
    if (inputs.length > 0) {
      setTimeout(() => inputs[0].focus(), 100);
    }

    inputs.forEach(input => {
      input.addEventListener('input', () => {
        if (isAnswerChecked) return;
        
        const allFilled = Array.from(inputs).every(inp => inp.value.trim().length > 0);
        document.getElementById('btn-check').disabled = !allFilled;
        
        selectedAnswer = Array.from(inputs).map(inp => inp.value.trim());
      });
    });
  }
}

// ── Hız Tüneli (Time-Attack Reflex Blitz - true-false) ──────────
function renderTrueFalse(container, question) {
  if (reflexTimer) {
    clearTimeout(reflexTimer);
    reflexTimer = null;
  }
  if (reflexInterval) {
    clearInterval(reflexInterval);
    reflexInterval = null;
  }

  const hasPhrases = question.englishPhrase || question.turkishTranslation;
  const cardHtml = hasPhrases ? `
    <div class="blitz-card" style="background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.1); padding: 30px; border-radius: 12px; text-align: center; margin-bottom: 30px; box-shadow: var(--shadow-sm);">
      ${question.englishPhrase ? `
      <div class="blitz-english" style="font-size: 1.5rem; font-weight: 700; color: var(--accent-color, #a855f7); margin-bottom: 15px; line-height: 1.4;">
        ${question.englishPhrase}
      </div>` : ''}
      ${question.turkishTranslation ? `
      <div class="blitz-turkish" style="font-size: 1.3rem; font-weight: 500; color: var(--text-primary); line-height: 1.4;">
        ${question.turkishTranslation}
      </div>` : ''}
    </div>
  ` : '';

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt || 'Hız Tüneli: Hızlıca karar ver!'}</p>
    <div class="blitz-timer-container" style="width: 100%; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden; margin-bottom: 20px;">
      <div id="blitz-timer-bar" style="width: 100%; height: 100%; background: var(--accent-color, #a855f7); transition: width 50ms linear;"></div>
    </div>
    
    ${cardHtml}

    <div class="blitz-buttons" style="display: flex; gap: 20px; justify-content: center; width: 100%;">
      <button class="blitz-btn wrong-btn" id="blitz-btn-wrong" style="flex: 1; padding: 18px; border-radius: 12px; border: none; font-size: 1.2rem; font-weight: 700; cursor: pointer; background: rgba(239, 68, 68, 0.15); border: 2px solid rgb(239, 68, 68); color: rgb(239, 68, 68); transition: all 0.2s ease;">
        ✗ YANLIŞ (←)
      </button>
      <button class="blitz-btn correct-btn" id="blitz-btn-correct" style="flex: 1; padding: 18px; border-radius: 12px; border: none; font-size: 1.2rem; font-weight: 700; cursor: pointer; background: rgba(34, 197, 94, 0.15); border: 2px solid rgb(34, 197, 94); color: rgb(34, 197, 94); transition: all 0.2s ease;">
        ✓ DOĞRU (→)
      </button>
    </div>
  `;

  const textContent = (question.prompt || "") + (question.englishPhrase || "") + (question.turkishTranslation || "");
  const duration = Math.min(20000, Math.max(5000, textContent.length * 100));
  const startTime = Date.now();
  const timerBar = document.getElementById('blitz-timer-bar');

  const updateTimer = () => {
    const elapsed = Date.now() - startTime;
    const remainingPercent = Math.max(0, 100 - (elapsed / duration) * 100);
    if (timerBar) {
      timerBar.style.width = remainingPercent + '%';
    }
    
    if (elapsed >= duration) {
      clearInterval(reflexInterval);
      reflexInterval = null;
      handleBlitzAnswer(null);
    }
  };

  reflexInterval = setInterval(updateTimer, 50);

  const handleBlitzAnswer = (answer) => {
    if (isAnswerChecked) return;
    
    if (reflexTimer) {
      clearTimeout(reflexTimer);
      reflexTimer = null;
    }
    if (reflexInterval) {
      clearInterval(reflexInterval);
      reflexInterval = null;
    }

    selectedAnswer = answer;
    
    document.getElementById('btn-check').disabled = false;
    checkAnswer();
  };

  const btnWrong = document.getElementById('blitz-btn-wrong');
  const btnCorrect = document.getElementById('blitz-btn-correct');
  
  if (btnWrong) {
    btnWrong.addEventListener('click', () => handleBlitzAnswer(false));
    btnWrong.addEventListener('mouseenter', () => {
      if (isAnswerChecked) return;
      btnWrong.style.background = 'rgb(239, 68, 68)';
      btnWrong.style.color = '#fff';
    });
    btnWrong.addEventListener('mouseleave', () => {
      if (isAnswerChecked) return;
      btnWrong.style.background = 'rgba(239, 68, 68, 0.15)';
      btnWrong.style.color = 'rgb(239, 68, 68)';
    });
  }
  if (btnCorrect) {
    btnCorrect.addEventListener('click', () => handleBlitzAnswer(true));
    btnCorrect.addEventListener('mouseenter', () => {
      if (isAnswerChecked) return;
      btnCorrect.style.background = 'rgb(34, 197, 94)';
      btnCorrect.style.color = '#fff';
    });
    btnCorrect.addEventListener('mouseleave', () => {
      if (isAnswerChecked) return;
      btnCorrect.style.background = 'rgba(34, 197, 94, 0.15)';
      btnCorrect.style.color = 'rgb(34, 197, 94)';
    });
  }

  if (blitzKeyHandler) {
    window.removeEventListener('keydown', blitzKeyHandler);
  }

  blitzKeyHandler = (e) => {
    if (isAnswerChecked) return;
    if (e.key === 'ArrowLeft') {
      e.preventDefault();
      window.removeEventListener('keydown', blitzKeyHandler);
      blitzKeyHandler = null;
      handleBlitzAnswer(false);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      window.removeEventListener('keydown', blitzKeyHandler);
      blitzKeyHandler = null;
      handleBlitzAnswer(true);
    }
  };

  window.addEventListener('keydown', blitzKeyHandler);
}

function showTFFeedback(question) {
  const btnWrong = document.getElementById('blitz-btn-wrong');
  const btnCorrect = document.getElementById('blitz-btn-correct');
  
  const isTargetCorrect = (question.isTrue !== undefined)
    ? Boolean(question.isTrue)
    : (question.correctAnswer === true || String(question.correctAnswer).toLowerCase() === 'true');

  if (isTargetCorrect) {
    if (btnCorrect) {
      btnCorrect.style.background = 'var(--color-correct-bg)';
      btnCorrect.style.color = 'var(--color-correct)';
      btnCorrect.style.borderColor = 'var(--color-correct)';
    }
    if (selectedAnswer === false && btnWrong) {
      btnWrong.style.background = 'var(--color-wrong-bg)';
      btnWrong.style.color = 'var(--color-wrong)';
      btnWrong.style.borderColor = 'var(--color-wrong)';
    }
  } else {
    if (btnWrong) {
      btnWrong.style.background = 'var(--color-correct-bg)';
      btnWrong.style.color = 'var(--color-correct)';
      btnWrong.style.borderColor = 'var(--color-correct)';
    }
    if (selectedAnswer === true && btnCorrect) {
      btnCorrect.style.background = 'var(--color-wrong-bg)';
      btnCorrect.style.color = 'var(--color-wrong)';
      btnCorrect.style.borderColor = 'var(--color-wrong)';
    }
  }
}

// ── Projektör Modu (The Spotlight Match - spotlight) ──────────
function renderSpotlight(container, question) {
  const paragraph = question.paragraph;
  const target = question.highlightChunk;
  
  let displayHtml = "";
  const escapedTarget = target.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
  const regex = new RegExp(`(${escapedTarget})`, 'i');
  const parts = paragraph.split(regex);
  if (parts.length >= 3) {
    const prefix = parts[0];
    const matched = parts[1];
    const suffix = parts.slice(2).join('');
    displayHtml = `<span class="spotlight-dim-text">${prefix}</span>` + 
                  `<span class="spotlight-bright">${matched}</span>` + 
                  `<span class="spotlight-dim-text">${suffix}</span>`;
  } else {
    displayHtml = paragraph;
  }

  // Shuffle spotlight options dynamically to randomize UI layout
  const indexedOptions = question.options.map((opt, i) => ({ opt, originalIndex: i }));
  const shuffledOptions = [...indexedOptions].sort(() => Math.random() - 0.5);

  const optionsHtml = shuffledOptions.map((item) => {
    const meaning = getOptionMeaning(question, item.opt);
    const displayText = (meaning && !item.opt.includes('/')) ? `${item.opt} <span style="opacity: 0.75; font-weight: 400; font-size: 0.9em; margin-left: 6px;">/ ${meaning}</span>` : item.opt;
    return `<button class="spotlight-option-card" data-index="${item.originalIndex}" style="padding: 16px; border-radius: 12px; color: var(--text-primary); font-size: 1.1rem; font-weight: 600; cursor: pointer; text-align: center; width: 100%;">
      ${displayText}
    </button>`;
  }).join('');

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt || 'Projektör Modu: Parlayan öbeğin Türkçe anlamını seçin!'}</p>
    
    <div class="spotlight-paragraph-container" style="text-align: left; position: relative; margin-bottom: 25px;">
      ${displayHtml}
    </div>
    
    <div class="spotlight-options-grid" style="display: grid; grid-template-columns: 1fr; gap: 12px; width: 100%;">
      ${optionsHtml}
    </div>
  `;

  container.querySelectorAll('.spotlight-option-card').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isAnswerChecked) return;
      
      const idx = parseInt(btn.dataset.index);
      selectedAnswer = idx;
      
      document.getElementById('btn-check').disabled = false;
      checkAnswer();
    });
  });

  // Automatically scroll the highlighted text into view within the container
  setTimeout(() => {
    const brightEl = container.querySelector('.spotlight-bright');
    const scrollParent = container.querySelector('.spotlight-paragraph-container');
    if (brightEl && scrollParent) {
      const parentRect = scrollParent.getBoundingClientRect();
      const elRect = brightEl.getBoundingClientRect();
      const relativeTop = elRect.top - parentRect.top + scrollParent.scrollTop;
      scrollParent.scrollTo({
        top: relativeTop - (parentRect.height / 2) + (elRect.height / 2),
        behavior: 'smooth'
      });
    }
  }, 120);
}

function showSpotlightFeedback(question) {
  const options = document.querySelectorAll('.spotlight-option-card');
  options.forEach(btn => {
    const idx = parseInt(btn.dataset.index);
    if (idx === question.correctIndex) {
      btn.style.borderColor = 'var(--color-correct)';
      btn.style.background = 'var(--color-correct-bg)';
      btn.style.color = 'var(--color-correct)';
    } else if (idx === selectedAnswer && idx !== question.correctIndex) {
      btn.style.borderColor = 'var(--color-wrong)';
      btn.style.background = 'var(--color-wrong-bg)';
      btn.style.color = 'var(--color-wrong)';
    }
  });
}

// ── Hata Avcısı / Bug Debugger (Swipe Mode) ──
function renderSwipeQuestion(container, question) {
  const mainText = question.phrase || question.prompt || "";
  const subText = question.translation || "";

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    
    <div class="swipe-area" id="swipe-area">
      <div class="swipe-timer-container">
        <div class="swipe-timer-bar" id="swipe-timer-bar"></div>
      </div>
      
      <div class="swipe-card" id="swipe-card">
        <div class="swipe-overlay swipe-overlay-bug">BUG</div>
        <div class="swipe-overlay swipe-overlay-valid">VALID</div>
        <div class="swipe-card-content">
          <div class="swipe-phrase">${mainText}</div>
          <div class="swipe-translation-hint">${subText}</div>
        </div>
      </div>
      
      <div class="swipe-buttons">
        <button class="swipe-btn bug-btn" id="swipe-bug-btn" title="Hatalı (Bug) - Sol">
          <span class="swipe-btn-icon">🪲</span>
          <span class="swipe-btn-label">BUG</span>
        </button>
        <button class="swipe-btn valid-btn" id="swipe-valid-btn" title="Doğru (Valid) - Sağ">
          <span class="swipe-btn-icon">✓</span>
          <span class="swipe-btn-label">VALID</span>
        </button>
      </div>
    </div>
  `;

  const card = document.getElementById('swipe-card');
  const overlayBug = card.querySelector('.swipe-overlay-bug');
  const overlayValid = card.querySelector('.swipe-overlay-valid');
  const timerBar = document.getElementById('swipe-timer-bar');

  let startX = 0;
  let startY = 0;
  let currentX = 0;
  let currentY = 0;
  let isDragging = false;

  const dragStart = (e) => {
    if (isAnswerChecked) return;
    isDragging = true;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    startX = clientX;
    startY = clientY;
    card.style.transition = 'none';

    window.addEventListener('mousemove', dragMove);
    window.addEventListener('mouseup', dragEnd);
    window.addEventListener('touchmove', dragMove, { passive: true });
    window.addEventListener('touchend', dragEnd);
  };

  const dragMove = (e) => {
    if (!isDragging || isAnswerChecked) return;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    currentX = clientX - startX;
    currentY = clientY - startY;

    const rotate = currentX * 0.1;
    card.style.transform = `translate(${currentX}px, ${currentY}px) rotate(${rotate}deg)`;

    const limit = 100;
    if (currentX > 0) {
      const opacity = Math.min(1, currentX / limit);
      overlayValid.style.opacity = opacity;
      overlayBug.style.opacity = 0;
    } else {
      const opacity = Math.min(1, -currentX / limit);
      overlayBug.style.opacity = opacity;
      overlayValid.style.opacity = 0;
    }
  };

  const removeWindowListeners = () => {
    window.removeEventListener('mousemove', dragMove);
    window.removeEventListener('mouseup', dragEnd);
    window.removeEventListener('touchmove', dragMove);
    window.removeEventListener('touchend', dragEnd);
  };

  const dragEnd = () => {
    if (!isDragging || isAnswerChecked) return;
    isDragging = false;
    removeWindowListeners();
    
    const threshold = 120;
    if (currentX > threshold) {
      swipeRight();
    } else if (currentX < -threshold) {
      swipeLeft();
    } else {
      card.style.transition = 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.3s ease';
      card.style.transform = 'translate(0px, 0px) rotate(0deg)';
      overlayBug.style.opacity = 0;
      overlayValid.style.opacity = 0;
    }
  };

  card.addEventListener('mousedown', dragStart);
  card.addEventListener('touchstart', dragStart, { passive: true });

  const swipeLeft = () => {
    if (isAnswerChecked) return;
    removeWindowListeners();
    clearInterval(reflexInterval);
    clearTimeout(reflexTimer);
    
    card.style.transition = 'transform 0.4s cubic-bezier(0.1, 0.8, 0.3, 1), opacity 0.4s';
    card.style.transform = 'translate(-400px, 50px) rotate(-30deg)';
    card.style.opacity = 0;
    overlayBug.style.opacity = 1;
    overlayValid.style.opacity = 0;

    selectedAnswer = false; 
    document.getElementById('btn-check').disabled = false;
    setTimeout(() => {
      checkAnswer();
    }, 200);
  };

  const swipeRight = () => {
    if (isAnswerChecked) return;
    removeWindowListeners();
    clearInterval(reflexInterval);
    clearTimeout(reflexTimer);

    card.style.transition = 'transform 0.4s cubic-bezier(0.1, 0.8, 0.3, 1), opacity 0.4s';
    card.style.transform = 'translate(400px, 50px) rotate(30deg)';
    card.style.opacity = 0;
    overlayValid.style.opacity = 1;
    overlayBug.style.opacity = 0;

    selectedAnswer = true; 
    document.getElementById('btn-check').disabled = false;
    setTimeout(() => {
      checkAnswer();
    }, 200);
  };

  document.getElementById('swipe-bug-btn').addEventListener('click', swipeLeft);
  document.getElementById('swipe-valid-btn').addEventListener('click', swipeRight);

  const textContent = (question.phrase || "") + (question.prompt || "") + (question.translation || "");
  const duration = Math.min(20000, Math.max(5000, textContent.length * 100));
  let remainingTime = duration;
  const timerTick = 50;
  timerBar.style.width = '100%';

  reflexInterval = setInterval(() => {
    if (isAnswerChecked) {
      clearInterval(reflexInterval);
      return;
    }
    remainingTime -= timerTick;
    const percentage = Math.max(0, (remainingTime / duration) * 100);
    timerBar.style.width = `${percentage}%`;

    if (remainingTime <= 0) {
      clearInterval(reflexInterval);
      removeWindowListeners();
      selectedAnswer = null; 
      document.getElementById('btn-check').disabled = false;
      checkAnswer();
    }
  }, timerTick);
}

// ── Edat Mıknatısı (The Preposition Magnet) ──
function renderPrepositionMagnet(container, question) {
  const parts = question.sentence.split(/_{3,}/);
  let sentenceHtml = "";
  if (parts.length >= 2) {
    sentenceHtml = `${parts[0]} <span class="magnet-blank-slot" id="magnet-drop-target">_____</span> ${parts[1]}`;
  } else {
    sentenceHtml = question.sentence;
  }

  const optionsHtml = question.options.map((opt, i) => {
    return `<div class="magnet-draggable" data-index="${i}" id="magnet-opt-${i}">${opt}</div>`;
  }).join('');

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <p class="quiz-translation" style="margin-bottom: 20px;">${question.translation || ''}</p>
    
    <div class="magnet-sentence-container">
      ${sentenceHtml}
    </div>
    
    <div class="magnet-bank-container" id="magnet-bank">
      ${optionsHtml}
    </div>
  `;

  const draggables = container.querySelectorAll('.magnet-draggable');
  const target = document.getElementById('magnet-drop-target');

  draggables.forEach(el => {
    let startX = 0, startY = 0;
    let currentX = 0, currentY = 0;
    let isDragging = false;

    const onStart = (e) => {
      if (isAnswerChecked) return;
      isDragging = true;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      startX = clientX;
      startY = clientY;
      el.style.transition = 'none';
      el.style.zIndex = '1000';
      el.classList.add('dragging');

      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onEnd);
      window.addEventListener('touchmove', onMove, { passive: false });
      window.addEventListener('touchend', onEnd);
    };

    const onMove = (e) => {
      if (!isDragging) return;
      if (e.cancelable) e.preventDefault();
      
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      currentX = clientX - startX;
      currentY = clientY - startY;

      el.style.transform = `translate3d(${currentX}px, ${currentY}px, 0) scale(1.05)`;

      const rectEl = el.getBoundingClientRect();
      const rectTarget = target.getBoundingClientRect();

      const overlap = !(rectEl.right < rectTarget.left || 
                        rectEl.left > rectTarget.right || 
                        rectEl.bottom < rectTarget.top || 
                        rectEl.top > rectTarget.bottom);

      if (overlap) {
        target.classList.add('magnet-slot-hover');
      } else {
        target.classList.remove('magnet-slot-hover');
      }
    };

    const onEnd = () => {
      if (!isDragging) return;
      isDragging = false;
      el.classList.remove('dragging');

      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onEnd);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('touchend', onEnd);

      const rectEl = el.getBoundingClientRect();
      const rectTarget = target.getBoundingClientRect();

      const overlap = !(rectEl.right < rectTarget.left || 
                        rectEl.left > rectTarget.right || 
                        rectEl.bottom < rectTarget.top || 
                        rectEl.top > rectTarget.bottom);

      target.classList.remove('magnet-slot-hover');

      if (overlap) {
        const index = parseInt(el.dataset.index);
        if (index === question.correctIndex) {
          el.style.display = 'none';
          target.textContent = el.textContent;
          target.classList.add('correct-snapped');
          selectedAnswer = index;
          document.getElementById('btn-check').disabled = false;
          checkAnswer();
        } else {
          target.classList.add('magnet-shake');
          el.classList.add('magnet-shake');
          
          el.style.transition = 'transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
          el.style.transform = 'translate3d(0, 0, 0)';
          
          setTimeout(() => {
            target.classList.remove('magnet-shake');
            el.classList.remove('magnet-shake');
            el.style.zIndex = '';
          }, 500);
        }
      } else {
        el.style.transition = 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
        el.style.transform = 'translate3d(0, 0, 0)';
        setTimeout(() => {
          el.style.zIndex = '';
        }, 300);
      }
    };

    el.addEventListener('mousedown', onStart);
    el.addEventListener('touchstart', onStart, { passive: true });
  });
}

// ── Çift Boşluklu Mıknatıs (Double Preposition Magnet) ──
function renderDoublePrepositionMagnet(container, question) {
  const parts = question.sentence.split(/_{3,}/);
  let sentenceHtml = "";
  if (parts.length >= 3) {
    sentenceHtml = `${parts[0]} <span class="magnet-blank-slot" id="magnet-drop-target-1" data-slot="0" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span> ${parts[1]} <span class="magnet-blank-slot" id="magnet-drop-target-2" data-slot="1" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span> ${parts[2]}`;
  } else if (parts.length === 2) {
    sentenceHtml = `${parts[0]} <span class="magnet-blank-slot" id="magnet-drop-target-1" data-slot="0" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span> <span class="magnet-blank-slot" id="magnet-drop-target-2" data-slot="1" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span> ${parts[1]}`;
  } else {
    sentenceHtml = `${question.sentence} <span class="magnet-blank-slot" id="magnet-drop-target-1" data-slot="0" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span> <span class="magnet-blank-slot" id="magnet-drop-target-2" data-slot="1" style="cursor:pointer; border: 2px dashed var(--border-color); padding: 2px 10px; border-radius: 8px; font-weight: 700; color: var(--accent-primary);">_____</span>`;
  }

  const optionsHtml = question.options.map((opt, i) => {
    return `<div class="magnet-draggable" data-index="${i}" id="magnet-double-opt-${i}">${opt}</div>`;
  }).join('');

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <p class="quiz-translation" style="margin-bottom: 20px;">${question.translation || ''}</p>
    
    <div class="magnet-sentence-container" style="line-height: 2.5; font-size: 1.25rem;">
      ${sentenceHtml}
    </div>
    
    <div class="magnet-bank-container" id="magnet-double-bank" style="margin-top: 30px;">
      ${optionsHtml}
    </div>
    <div style="font-size: 0.8rem; color: var(--text-secondary); margin-top: 15px; text-align: center; opacity: 0.8;">* Sürüklediğiniz kelimeyi geri almak veya değiştirmek için boşluğun üzerine tıklayabilirsiniz.</div>
  `;

  const draggables = container.querySelectorAll('.magnet-draggable');
  const target1 = document.getElementById('magnet-drop-target-1');
  const target2 = document.getElementById('magnet-drop-target-2');

  let localSelection = [null, null];
  let elementMappedToSlot = [null, null];

  // Click on slot to reset it
  [target1, target2].forEach((target, slotIdx) => {
    target.addEventListener('click', () => {
      if (isAnswerChecked) return;
      if (localSelection[slotIdx] !== null) {
        const el = elementMappedToSlot[slotIdx];
        if (el) {
          el.style.display = 'inline-block';
          el.style.transition = 'none';
          el.style.transform = 'translate3d(0, 0, 0)';
          el.style.zIndex = '';
        }
        target.textContent = '_____';
        target.classList.remove('correct-snapped');
        localSelection[slotIdx] = null;
        elementMappedToSlot[slotIdx] = null;
        selectedAnswer = [...localSelection];
        document.getElementById('btn-check').disabled = true;
      }
    });
  });

  draggables.forEach(el => {
    let startX = 0, startY = 0;
    let currentX = 0, currentY = 0;
    let isDragging = false;

    const onStart = (e) => {
      if (isAnswerChecked) return;
      isDragging = true;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      startX = clientX;
      startY = clientY;
      el.style.transition = 'none';
      el.style.zIndex = '1000';
      el.classList.add('dragging');

      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onEnd);
      window.addEventListener('touchmove', onMove, { passive: false });
      window.addEventListener('touchend', onEnd);
    };

    const onMove = (e) => {
      if (!isDragging) return;
      if (e.cancelable) e.preventDefault();
      
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      currentX = clientX - startX;
      currentY = clientY - startY;

      el.style.transform = `translate3d(${currentX}px, ${currentY}px, 0) scale(1.05)`;

      const rectEl = el.getBoundingClientRect();
      const rectT1 = target1.getBoundingClientRect();
      const rectT2 = target2.getBoundingClientRect();

      const overlap1 = !(rectEl.right < rectT1.left || rectEl.left > rectT1.right || rectEl.bottom < rectT1.top || rectEl.top > rectT1.bottom);
      const overlap2 = !(rectEl.right < rectT2.left || rectEl.left > rectT2.right || rectEl.bottom < rectT2.top || rectEl.top > rectT2.bottom);

      if (overlap1) {
        target1.classList.add('magnet-slot-hover');
      } else {
        target1.classList.remove('magnet-slot-hover');
      }

      if (overlap2) {
        target2.classList.add('magnet-slot-hover');
      } else {
        target2.classList.remove('magnet-slot-hover');
      }
    };

    const onEnd = () => {
      if (!isDragging) return;
      isDragging = false;
      el.classList.remove('dragging');

      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onEnd);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('touchend', onEnd);

      const rectEl = el.getBoundingClientRect();
      const rectT1 = target1.getBoundingClientRect();
      const rectT2 = target2.getBoundingClientRect();

      const overlap1 = !(rectEl.right < rectT1.left || rectEl.left > rectT1.right || rectEl.bottom < rectT1.top || rectEl.top > rectT1.bottom);
      const overlap2 = !(rectEl.right < rectT2.left || rectEl.left > rectT2.right || rectEl.bottom < rectT2.top || rectEl.top > rectT2.bottom);

      target1.classList.remove('magnet-slot-hover');
      target2.classList.remove('magnet-slot-hover');

      const optionIdx = parseInt(el.dataset.index);

      if (overlap1) {
        if (localSelection[0] !== null) {
          const oldEl = elementMappedToSlot[0];
          if (oldEl) {
            oldEl.style.display = 'inline-block';
            oldEl.style.transition = 'none';
            oldEl.style.transform = 'translate3d(0, 0, 0)';
            oldEl.style.zIndex = '';
          }
        }
        el.style.display = 'none';
        target1.textContent = el.textContent;
        target1.classList.add('correct-snapped');
        localSelection[0] = optionIdx;
        elementMappedToSlot[0] = el;
      } else if (overlap2) {
        if (localSelection[1] !== null) {
          const oldEl = elementMappedToSlot[1];
          if (oldEl) {
            oldEl.style.display = 'inline-block';
            oldEl.style.transition = 'none';
            oldEl.style.transform = 'translate3d(0, 0, 0)';
            oldEl.style.zIndex = '';
          }
        }
        el.style.display = 'none';
        target2.textContent = el.textContent;
        target2.classList.add('correct-snapped');
        localSelection[1] = optionIdx;
        elementMappedToSlot[1] = el;
      } else {
        el.style.transition = 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
        el.style.transform = 'translate3d(0, 0, 0)';
        setTimeout(() => {
          el.style.zIndex = '';
        }, 300);
      }

      if (localSelection[0] !== null && localSelection[1] !== null) {
        selectedAnswer = [...localSelection];
        document.getElementById('btn-check').disabled = false;
      } else {
        document.getElementById('btn-check').disabled = true;
      }
    };

    el.addEventListener('mousedown', onStart);
    el.addEventListener('touchstart', onStart, { passive: true });
  });
}

