function showCollocationPopup(english, turkish) {
  const existing = document.getElementById('collocation-popup');
  if (existing) {
    existing.remove();
  }

  const popup = document.createElement('div');
  popup.id = 'collocation-popup';
  popup.className = 'collocation-success-popup';
  popup.innerHTML = `
    <div class="collocation-popup-icon">🔑</div>
    <div class="collocation-popup-content">
      <div class="collocation-popup-en">${english}</div>
      <div class="collocation-popup-tr">${turkish}</div>
    </div>
  `;

  document.body.appendChild(popup);

  // Trigger animation after append
  setTimeout(() => {
    popup.classList.add('show');
  }, 10);
}

// ── Bağlantı Kilidi (Collocation Matcher) ──
function renderCollocationMatching(container, question) {
  const words = question.pairs.map(p => ({ type: 'word', text: p.word, prep: p.prep }));
  const preps = question.pairs.map(p => ({ type: 'prep', text: p.prep }));
  const allCards = [...words, ...preps].sort(() => Math.random() - 0.5);

  const cardsHtml = allCards.map((card, i) => {
    return `<div class="match-card" data-index="${i}" data-type="${card.type}" data-text="${card.text}" data-prep="${card.prep || ''}">
      ${card.text}
    </div>`;
  }).join('');

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <div class="collocation-matching-grid">
      ${cardsHtml}
    </div>
  `;

  const matchCards = container.querySelectorAll('.match-card');
  let selectedWordEl = null;
  let selectedPrepEl = null;
  let matchesCount = 0;

  matchCards.forEach(card => {
    card.addEventListener('click', () => {
      if (card.classList.contains('matched') || card.classList.contains('error') || isAnswerChecked) return;

      // Hide the collocation popup as the user is starting a new match attempt
      const existingPopup = document.getElementById('collocation-popup');
      if (existingPopup) {
        existingPopup.classList.remove('show');
        setTimeout(() => existingPopup.remove(), 300);
      }

      const type = card.dataset.type;

      if (type === 'word') {
        if (selectedWordEl) {
          selectedWordEl.classList.remove('selected');
        }
        selectedWordEl = card;
        card.classList.add('selected');
      } else {
        if (selectedPrepEl) {
          selectedPrepEl.classList.remove('selected');
        }
        selectedPrepEl = card;
        card.classList.add('selected');
      }

      if (selectedWordEl && selectedPrepEl) {
        const reqPrep = selectedWordEl.dataset.prep;
        const actPrep = selectedPrepEl.dataset.text;

        const wEl = selectedWordEl;
        const pEl = selectedPrepEl;
        selectedWordEl = null;
        selectedPrepEl = null;

        if (reqPrep === actPrep) {
          wEl.classList.remove('selected');
          pEl.classList.remove('selected');
          wEl.classList.add('matched');
          pEl.classList.add('matched');
          matchesCount++;

          // Show Collocation Success Popup
          const englishPhrase = wEl.dataset.text + " " + pEl.dataset.text;
          const normalized = englishPhrase.toLowerCase().replace(/\s+/g, " ").trim();
          const turkishTranslation = COLLOCATION_DICT[normalized] || "";
          if (turkishTranslation) {
            showCollocationPopup(englishPhrase, turkishTranslation);
            wEl.innerHTML = `<span class="match-card-en">${wEl.dataset.text}</span><span class="match-card-tr" style="display: block; font-size: 0.75rem; color: #10b981; margin-top: 4px; font-weight: 700;">(${turkishTranslation})</span>`;
          }

          if (matchesCount === question.pairs.length) {
            selectedAnswer = 'perfect';
            document.getElementById('btn-check').disabled = false;
            setTimeout(() => {
              checkAnswer();
            }, 600);
          }
        } else {
          wEl.classList.add('error');
          pEl.classList.add('error');

          setTimeout(() => {
            wEl.classList.remove('selected', 'error');
            pEl.classList.remove('selected', 'error');
          }, 600);
        }
      }
    });
  });
}

// ── Refleks Blitz (Hız Tüneli) ──
function renderReflexBlitz(container, question) {
  const optionsHtml = question.options.map((opt, i) => {
    return `<button class="blitz-option-btn" data-index="${i}">
      <span class="blitz-shortcut-hint">${i + 1}</span>
      <span class="blitz-opt-text">${opt}</span>
    </button>`;
  }).join('');

  container.innerHTML = `
    <div class="blitz-header-row">
      <div class="blitz-timer-container">
        <div class="blitz-timer-bar" id="blitz-timer-bar"></div>
      </div>
      <div class="blitz-streak-badge ${blitzStreak >= 3 ? 'streak-ignited' : ''}" id="blitz-streak-badge">
        🔥 COMBO: ${blitzStreak}
      </div>
    </div>
    
    <p class="quiz-prompt">${question.prompt}</p>
    <div class="blitz-sentence-box">
      ${question.sentence}
    </div>
    
    <div class="blitz-options-grid">
      ${optionsHtml}
    </div>
  `;

  // Apply ignited glow to container
  const quizBox = document.querySelector('.quiz-screen .quiz-box') || document.querySelector('.quiz-container');
  if (quizBox) {
    if (blitzStreak >= 3) {
      quizBox.classList.add('quiz-container-streak-ignited');
    } else {
      quizBox.classList.remove('quiz-container-streak-ignited');
    }
  }

  const selectOption = (idx) => {
    if (isAnswerChecked) return;
    clearInterval(reflexInterval);
    if (blitzKeyHandler) {
      window.removeEventListener('keydown', blitzKeyHandler);
      blitzKeyHandler = null;
    }
    
    selectedAnswer = idx;
    
    const buttons = container.querySelectorAll('.blitz-option-btn');
    buttons.forEach((btn, i) => {
      if (i === idx) btn.classList.add('selected');
    });

    if (idx === question.correctIndex) {
      blitzStreak++;
    } else {
      blitzStreak = 0;
    }

    document.getElementById('btn-check').disabled = false;
    checkAnswer();
  };

  const onKey = (e) => {
    if (isAnswerChecked) return;
    if (e.key === '1') {
      selectOption(0);
    } else if (e.key === '2' && question.options.length > 1) {
      selectOption(1);
    }
  };
  window.addEventListener('keydown', onKey);
  blitzKeyHandler = onKey;

  container.querySelectorAll('.blitz-option-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.index);
      selectOption(idx);
    });
  });

  const timerBar = document.getElementById('blitz-timer-bar');
  let remainingTime = 3000;
  const tick = 50;

  reflexInterval = setInterval(() => {
    if (isAnswerChecked) {
      clearInterval(reflexInterval);
      return;
    }
    remainingTime -= tick;
    const percentage = Math.max(0, (remainingTime / 3000) * 100);
    timerBar.style.width = `${percentage}%`;

    if (remainingTime <= 0) {
      clearInterval(reflexInterval);
      if (blitzKeyHandler) {
        window.removeEventListener('keydown', blitzKeyHandler);
        blitzKeyHandler = null;
      }
      
      selectedAnswer = null;
      blitzStreak = 0;
      document.getElementById('btn-check').disabled = false;
      checkAnswer();
    }
  }, tick);
}

function showBlitzFeedback(question) {
  const buttons = document.querySelectorAll('.blitz-option-btn');
  buttons.forEach(btn => {
    const idx = parseInt(btn.dataset.index);
    if (idx === question.correctIndex) {
      btn.classList.add('correct');
    } else if (idx === selectedAnswer && idx !== question.correctIndex) {
      btn.classList.add('wrong');
    }
  });

  // Remove streak animation from box if incorrect
  if (selectedAnswer !== question.correctIndex) {
    const quizBox = document.querySelector('.quiz-screen .quiz-box') || document.querySelector('.quiz-container');
    if (quizBox) {
      quizBox.classList.remove('quiz-container-streak-ignited');
    }
  }
}

function checkAnswer() {
  if (isAnswerChecked) return;

  const question = isFormationMode ? FORMATION_QUESTIONS[currentQuestionIndex] : (isReviewMode ? reviewQuestions[currentQuestionIndex] : currentQuizQuestions[currentQuestionIndex]);
  let isCorrect = false;

  const activeType = (question.type === 'fill-blank-dropdown' || question.type === 'fill-blank')
    ? question._dynamicType
    : question.type;

  switch (activeType) {
    case 'multiple-choice':
    case 'error-spotting':
    case 'context-clue':
    case 'chain-expansion-differential':
    case 'structural-deconstruction':
    case 'vector-velocity-shift':
    case 'titan-boundary-defense':
    case 'vagon-to-suffix-match':
    case 'reverse-engineering-translation':
    case 'suffix-decapitation':
    case 'inversion-transformer':
    case 'punctuation-check':
    case 'structure-match':
    case 'sentence-connector':
    case 'context-distractor':
    case 'error-finder':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
    case 'idiom-builder':
      isCorrect = Array.isArray(selectedAnswer) &&
        selectedAnswer.length === question.correctSequence.length &&
        selectedAnswer.every((w, i) => w === question.correctSequence[i]);
      break;
    case 'vector-assembly':
      isCorrect = Array.isArray(selectedAnswer) &&
        selectedAnswer.length === question.correct_sequence.length &&
        selectedAnswer.every((w, i) => w === question.correct_sequence[i]);
      break;
    case 'word-bank':
      isCorrect = Array.isArray(selectedAnswer) &&
        selectedAnswer.length === question.correctOrder.length &&
        selectedAnswer.every((w, i) => w === question.correctOrder[i]);
      break;
    case 'matching':
      isCorrect = selectedAnswer === 'perfect';
      break;
    case 'fill-blank-dropdown':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
    case 'fill-blank':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
    case 'fill-blank-text':
      {
        const userVal = (selectedAnswer || "").toLowerCase().trim();
        const correctVal = (question.correct || question.correctAnswer || "").toLowerCase().trim();
        isCorrect = userVal === correctVal;
      }
      break;
    case 'translation-text':
      {
        const cleanUser = (selectedAnswer || "").toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").replace(/\s+/g, " ").trim();
        const cleanCorrect = question.correctSentence.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "").replace(/\s+/g, " ").trim();
        isCorrect = cleanUser === cleanCorrect;
      }
      break;
    case 'multiple-fill-blank':
      {
        const userVals = (selectedAnswer || []).map(val => val.toLowerCase().trim());
        const correctVals = question.corrects.map(val => val.toLowerCase().trim());
        isCorrect = userVals.length === correctVals.length && userVals.every((val, i) => val === correctVals[i]);
      }
      break;
    case 'true-false':
      {
        // Soruların bir kısmı doğru cevabı isTrue/correctAnswer yerine
        // options: ["True","False"] + correctIndex olarak taşıyor. O alanlar
        // okunmadığında cevap her zaman "yanlış" sayılıyordu; doğru cevabı
        // True olan sorular bu yüzden hatalı puanlanıyordu.
        let targetCorrect;
        if (question.isTrue !== undefined) {
          targetCorrect = Boolean(question.isTrue);
        } else if (question.correctAnswer !== undefined) {
          targetCorrect = question.correctAnswer === true || String(question.correctAnswer).toLowerCase() === 'true';
        } else {
          const picked = String((question.options || [])[question.correctIndex] || '');
          targetCorrect = /^(true|doğru|dogru|yes|evet)$/i.test(picked.trim());
        }
        isCorrect = Boolean(selectedAnswer) === targetCorrect;
      }
      break;
    case 'spotlight':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
    case 'swipe':
      isCorrect = selectedAnswer === question.isCorrect;
      break;
    case 'preposition-magnet':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
    case 'double-preposition-magnet':
      isCorrect = Array.isArray(selectedAnswer) &&
        selectedAnswer.length === 2 &&
        selectedAnswer[0] === question.correctIndices[0] &&
        selectedAnswer[1] === question.correctIndices[1];
      break;
    case 'collocation-matching':
      isCorrect = selectedAnswer === 'perfect';
      break;
    case 'reflex-blitz':
      isCorrect = selectedAnswer === question.correctIndex;
      break;
  }

  // Intercept if translation exists, primary is correct, type is not formula matching, and translation gate hasn't been triggered yet
  const isFormulaQuestion = question.type === 'structure-match' || (question.sentence && (question.sentence.includes('➔') || question.sentence.includes('[Ana Cümle]') || question.sentence.includes('[Yan Cümle]')));

  // true-false'ta çevrilecek kaynak cümle prompt içine gömülü olduğundan
  // question.sentence/enSentence boş kalıyor; kaynak yoksa çeviri geçidi
  // "boş cümleyi çevir" ekranı üretiyordu — bu durumda geçidi atla.
  const tfHasSource = activeType === 'true-false' && (question.sentence || question.enSentence || question.en);
  if (question && question.translation && isCorrect && !isFormulaQuestion && (activeType === 'fill-blank-dropdown' || activeType === 'fill-blank' || activeType === 'spotlight' || activeType === 'error-finder' || tfHasSource || activeType === 'multiple-fill-blank' || activeType === 'preposition-magnet' || activeType === 'double-preposition-magnet') && !isTranslationGateTriggered && !isTranslationGateActive) {
    isTranslationGateTriggered = true;
    startTranslationGate(document.getElementById('quiz-body'), question);
    return;
  }

  isAnswerChecked = true;
  state.totalQuestionsAnswered = (state.totalQuestionsAnswered || 0) + 1;

  // Deneme modu: doğru/yanlış anında gösterilmez. Cevap kaydedilip bir sonraki
  // soruya geçilir; tüm geri bildirim sınav sonundaki sonuç ekranında verilir.
  if (isExamMode) {
    examAnswers.push({
      id: question.id,
      correct: !!isCorrect,
      skill: getExamSkill(question),
      selected: selectedAnswer
    });
    if (isCorrect) correctCount++; else wrongCount++;
    nextQuestion();
    return;
  }

  // Apply visual styles and call feedback rendering functions
  switch (activeType) {
    case 'multiple-choice':
    case 'error-spotting':
    case 'context-clue':
    case 'chain-expansion-differential':
    case 'structural-deconstruction':
    case 'vector-velocity-shift':
    case 'titan-boundary-defense':
    case 'vagon-to-suffix-match':
    case 'reverse-engineering-translation':
    case 'suffix-decapitation':
    case 'inversion-transformer':
    case 'punctuation-check':
    case 'structure-match':
    case 'sentence-connector':
      showMCFeedback(question);
      break;
    case 'error-finder':
      showEFFeedback(question);
      break;
    case 'context-distractor':
    case 'fill-blank-dropdown':
      const selectEl = document.getElementById('fb-dropdown-select');
      if (selectEl) {
        selectEl.style.borderColor = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
        selectEl.style.backgroundColor = isCorrect ? 'var(--color-correct-bg)' : 'var(--color-wrong-bg)';
        selectEl.style.color = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
      }
      break;
    case 'fill-blank':
      showFBFeedback(question);
      break;
    case 'fill-blank-text':
      {
        const inputEl = document.getElementById('fb-text-input');
        if (inputEl) {
          inputEl.style.borderBottomColor = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
          inputEl.style.color = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
        }
      }
      break;
    case 'translation-text':
      {
        const textEl = document.getElementById('translation-text-area');
        if (textEl) {
          textEl.style.borderColor = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
          textEl.style.backgroundColor = isCorrect ? 'var(--color-correct-bg)' : 'var(--color-wrong-bg)';
          textEl.style.color = isCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
        }
      }
      break;
    case 'multiple-fill-blank':
      {
        const userVals = (selectedAnswer || []).map(val => val.toLowerCase().trim());
        const correctVals = question.corrects.map(val => val.toLowerCase().trim());
        const inputs = document.querySelectorAll('.multi-fb-input');
        inputs.forEach((inputEl, idx) => {
          const isInputCorrect = userVals[idx] === correctVals[idx];
          if (inputEl) {
            inputEl.style.borderColor = isInputCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
            inputEl.style.backgroundColor = isInputCorrect ? 'var(--color-correct-bg)' : 'var(--color-wrong-bg)';
            inputEl.style.color = isInputCorrect ? 'var(--color-correct)' : 'var(--color-wrong)';
          }
        });
      }
      break;
    case 'true-false':
      showTFFeedback(question);
      break;
    case 'spotlight':
      showSpotlightFeedback(question);
      break;
    case 'reflex-blitz':
      showBlitzFeedback(question);
      break;
    case 'double-preposition-magnet':
      {
        const t1 = document.getElementById('magnet-drop-target-1');
        const t2 = document.getElementById('magnet-drop-target-2');
        if (t1 && t2) {
          const isT1Correct = selectedAnswer[0] === question.correctIndices[0];
          const isT2Correct = selectedAnswer[1] === question.correctIndices[1];
          t1.style.borderColor = isT1Correct ? 'var(--color-correct)' : 'var(--color-wrong)';
          t1.style.backgroundColor = isT1Correct ? 'var(--color-correct-bg)' : 'var(--color-wrong-bg)';
          t1.style.color = isT1Correct ? 'var(--color-correct)' : 'var(--color-wrong)';

          t2.style.borderColor = isT2Correct ? 'var(--color-correct)' : 'var(--color-wrong)';
          t2.style.backgroundColor = isT2Correct ? 'var(--color-correct-bg)' : 'var(--color-wrong-bg)';
          t2.style.color = isT2Correct ? 'var(--color-correct)' : 'var(--color-wrong)';
        }
      }
      break;
  }

  const isTargetUnit = question && question.translation ? true : false;
  if (isTargetUnit && question.translation && !wasTranslationCorrect) {
    isCorrect = false;
  }

  // Feedback panel
  const feedbackPanel = document.getElementById('feedback-panel');
  const feedbackIcon = document.getElementById('feedback-icon');
  const feedbackText = document.getElementById('feedback-text');

  feedbackPanel.classList.add('show');
  playFeedbackSound(isCorrect);

  if (isCorrect) {
    if (typeof window.completedReadingHighlights === 'undefined') {
      window.completedReadingHighlights = [];
    }
    if (question) {
      if (question.enSentence) window.completedReadingHighlights.push(question.enSentence.trim());
      if (question.highlightChunk) window.completedReadingHighlights.push(question.highlightChunk.trim());
      if (question.translation) window.completedReadingHighlights.push(question.translation.trim());
      if (question.pairs) {
        question.pairs.forEach(p => {
          if (p.left) window.completedReadingHighlights.push(p.left.trim());
          if (p.right) window.completedReadingHighlights.push(p.right.trim());
        });
      }
      if (question.type === 'multiple-choice' && question.options && typeof question.correctIndex === 'number') {
        const correctOpt = question.options[question.correctIndex];
        const isEnglish = /^(It|Will|Is|Has|They)\b/i.test(correctOpt) || /\b(to|be|is|was|has|been|that)\b/i.test(correctOpt);
        if (isEnglish) {
          window.completedReadingHighlights.push(correctOpt.trim());
        }
      }
    }
    applyReadingPassageHighlights();

    feedbackPanel.classList.add('correct');
    feedbackPanel.classList.remove('wrong');
    feedbackText.innerHTML = question.explanation 
      ? `<div>Harika! Doğru cevap! 🎉</div><div class="explanation-box" style="font-size: 0.9rem; margin-top: 8px; text-align: left; background: rgba(255,255,255,0.15); padding: 10px 14px; border-radius: 8px; line-height: 1.5; color: inherit;">${question.explanation}</div>` 
      : 'Harika! Doğru cevap! 🎉';
    correctCount++;
    saveActiveQuizState();
    // ⚡ XP Katlayıcı aktifse bu doğru cevap 2× puan getirir
    const xpMult = (state.boosts && state.boosts.xpBoosterQ > 0) ? 2 : 1;
    if (xpMult === 2) {
      state.boosts.xpBoosterQ--;
      showToast(`⚡ XP Katlayıcı: +${XP_PER_CORRECT * 2} puan! (${state.boosts.xpBoosterQ} hak kaldı)`, 'success');
    }
    state.xp += XP_PER_CORRECT * xpMult;
    animateStat('stat-xp', 'xp-gain');
    updateDailyTaskProgress('xp', XP_PER_CORRECT * xpMult);

    // Sorular doğru cevaplandığında sayfanın sağında ve solunda küçük havai fişek patlamaları oluşsun
    if (typeof confetti === 'function') {
      confetti({
        particleCount: 65,
        spread: 360,
        startVelocity: 35,
        origin: { x: 0.2, y: 0.4 },
        scalar: 1.2
      });
      confetti({
        particleCount: 65,
        spread: 360,
        startVelocity: 35,
        origin: { x: 0.8, y: 0.4 },
        scalar: 1.2
      });
    }
    
    // Remove from wrongQuestions if answered correctly (or defer to session completion if in review mode)
    if (isFormationMode) {
      // Do nothing for wrong questions
    } else if (isReviewMode) {
      if (!reviewSessionCorrectIds.includes(question.id)) {
        reviewSessionCorrectIds.push(question.id);
      }
    } else {
      const qIndex = state.wrongQuestions.indexOf(question.id);
      if (qIndex > -1) {
        state.wrongQuestions.splice(qIndex, 1);
      }
    }
  } else {
    feedbackPanel.classList.add('wrong');
    feedbackPanel.classList.remove('correct');
    feedbackIcon.textContent = '✗';

    let correctAnswerText = '';
    if (question.type === 'error-finder') {
      correctAnswerText = question.sentenceTokens[question.correctIndex] + (question.suggestedCorrection ? ` (Doğrusu: ${question.suggestedCorrection})` : '');
    } else if (question.type === 'context-distractor' || question.type === 'sentence-connector') {
      correctAnswerText = question.options[question.correctIndex];
    } else if (question.type === 'multiple-choice' || question.type === 'error-spotting' || question.type === 'context-clue' || question.type === 'inversion-transformer' || question.type === 'fill-blank-dropdown' || question.type === 'fill-blank' || question.type === 'spotlight' || question.type === 'preposition-magnet' || question.type === 'reflex-blitz' || question.type === 'punctuation-check' || question.type === 'structure-match') {
      correctAnswerText = question.options[question.correctIndex];
    } else if (question.type === 'swipe') {
      correctAnswerText = question.isCorrect ? 'VALID (DOĞRU)' : 'BUG (HATALI)';
    } else if (question.type === 'collocation-matching') {
      correctAnswerText = question.explanation;
    } else if (question.type === 'fill-blank-text') {
      correctAnswerText = question.correct || question.correctAnswer;
    } else if (question.type === 'translation-text') {
      correctAnswerText = question.correctSentence;
    } else if (question.type === 'word-bank') {
      correctAnswerText = question.correctOrder.join(' ');
    } else if (question.type === 'idiom-builder') {
      correctAnswerText = question.correctSequence.join(' ');
    } else if (question.type === 'vector-assembly') {
      correctAnswerText = question.correct_sequence.join(' ');
    } else if (question.type === 'multiple-fill-blank') {
      correctAnswerText = question.corrects.join(', ');
    } else if (question.type === 'true-false') {
      const targetCorrect = (question.isTrue !== undefined)
        ? Boolean(question.isTrue)
        : (question.correctAnswer === true || String(question.correctAnswer).toLowerCase() === 'true');
      correctAnswerText = targetCorrect ? 'DOĞRU' : 'YANLIŞ';
    }

    if (question.type === 'true-false') {
      const tfLead = selectedAnswer === null
        ? `Süre Doldu! Doğru cevap: ${correctAnswerText}`
        : `Yanlış! Doğru cevap: ${correctAnswerText}`;
      feedbackText.innerHTML = `<div>${tfLead}</div>` +
        (question.explanation ? `<div class="explanation-box" style="font-size: 0.9rem; margin-top: 8px; text-align: left; background: rgba(0,0,0,0.06); padding: 10px 14px; border-radius: 8px; line-height: 1.5; color: inherit;">${question.explanation}</div>` : '');
    } else if (isTargetUnit && question.translation && !wasTranslationCorrect) {
      feedbackText.innerHTML = `<strong>Yanlış çeviri!</strong> Doğrusu:<br><span style="color: var(--color-correct); font-weight: 600;">${question.translation}</span>`;
    } else {
      feedbackText.innerHTML = `<div>Doğru cevap: <strong>${correctAnswerText}</strong></div>` + 
        (question.explanation ? `<div class="explanation-box" style="font-size: 0.9rem; margin-top: 8px; text-align: left; background: rgba(0,0,0,0.06); padding: 10px 14px; border-radius: 8px; line-height: 1.5; color: inherit;">${question.explanation}</div>` : '');
    }
    wrongCount++;
    saveActiveQuizState();
    
    if (!isReviewMode && !isFormationMode) {
      // 🛡️ Can Kalkanı aktifse bu yanlış can götürmez
      if (state.boosts && state.boosts.heartShieldQ > 0) {
        state.boosts.heartShieldQ--;
        showToast(`🛡️ Can Kalkanı korudu! (${state.boosts.heartShieldQ} hak kaldı)`, 'info');
      } else {
        state.hearts = Math.max(0, state.hearts - 1);
        animateStat('stat-hearts', 'heart-lose');
      }
      updateTopBar();

      // Add to wrongQuestions for spaced repetition
      if (!state.wrongQuestions.includes(question.id)) {
        state.wrongQuestions.push(question.id);
      }
    }

    // Render Hızlı Eleme Refleksi & Şık Analizi if options exist.
    // true-false'ta seçenekler yalnızca "True/False" olduğundan şık-şık analizi
    // anlamsız; açıklama zaten geri bildirim kutusunda gösteriliyor.
    const optionAnalysisEl = document.getElementById('feedback-option-analysis');
    if (optionAnalysisEl && question && question.type !== 'true-false' && question.options && typeof question.correctIndex === 'number') {
      const correctOpt = question.options[question.correctIndex];
      // Çeviri ve öge-analizi (spotlight) sorularında zaman-uyumu odaklı jenerik
      // açıklamalar konuyla alakasız kalıyor; bu sorulara özel analiz üretilir.
      const isTranslationQ = question.type === 'multiple-choice' &&
        ((question.isEngToTr !== undefined) || !!question.enSentence ||
         /Türkçe karşıl|İngilizce karşıl|çevir/i.test(question.prompt || ""));
      const isSpotlightQ = question.type === 'spotlight';
      const useTopicAnalysis = isTranslationQ || isSpotlightQ;
      const correctCleanText = (correctOpt || "").split(/\s*\/\s*/)[0].replace(/<[^>]+>/g, "").trim();
      let analysisHtml = `<div style="font-weight: 800; margin-bottom: 4px; color: var(--text-primary); font-size: 0.8rem;">🔍 Hızlı Eleme Refleksi & Şık Analizi:</div>`;

      question.options.forEach((opt, idx) => {
        const cleanOptText = (opt || "").split(/\s*\/\s*/)[0].replace(/<[^>]+>/g, "").trim();
        const groupInfo = useTopicAnalysis ? null : getConjunctionGroupInfo(cleanOptText);
        let groupTag = '';
        if (groupInfo) {
          groupTag = ` <span style="background: rgba(255,255,255,0.06); border: 1px solid ${groupInfo.color}; color: ${groupInfo.color}; padding: 1px 7px; border-radius: 6px; font-size: 0.72rem; font-weight: 700; margin-left: 4px;">${groupInfo.badge} ${groupInfo.name}</span>`;
        }

        if (idx === question.correctIndex) {
          if (useTopicAnalysis) {
            const okReason = isSpotlightQ
              ? "Altı çizili öbeğin cümledeki dil bilgisi işlevini doğru tanımlar."
              : "Kaynak cümledeki tüm ögeleri (isim + edat öbeği, sayı ve yer/nesne bildirimi) eksiksiz ve doğru karşılar.";
            analysisHtml += `<div style="color: var(--color-correct); font-weight: 700; margin-top: 4px; line-height: 1.4;">🟢 <strong>${cleanOptText}</strong> (DOĞRU): ${okReason}</div>`;
            return;
          }
          const detail = groupInfo ? ` [Grup Sentakslı Doğru Yapı]` : '';
          analysisHtml += `<div style="color: var(--color-correct); font-weight: 700; margin-top: 4px; line-height: 1.4;">🟢 <strong>${cleanOptText}</strong>${groupTag}${detail} (DOĞRU): Cümle yapısıyla ve sentaks kuralıyla tam uyumludur.</div>`;
        } else {
          if (useTopicAnalysis) {
            let tReason;
            if (isSpotlightQ) {
              tReason = "Altı çizili öbeğin işlevi bu değildir; öbek cümlede farklı bir dil bilgisi görevi üstlenir.";
            } else {
              const cw = cleanOptText.toLowerCase().split(/[\s.,;]+/).filter(Boolean);
              const rw = correctCleanText.toLowerCase().split(/[\s.,;]+/).filter(Boolean);
              const extra = cw.filter(w => !rw.includes(w));
              tReason = extra.length
                ? `Kaynak cümlenin birebir karşılığı değil: "${extra.join(', ')}" kısmı kaynakla örtüşmüyor (sözcük seçimi, sayı ya da yer/nesne ayrıntısı farkı).`
                : "Kaynak cümlenin anlamını tam karşılamıyor (sözcük seçimi, tekil/çoğul ya da yer/nesne ayrıntısı farkı).";
            }
            analysisHtml += `<div style="color: var(--text-secondary); opacity: 0.9; margin-top: 4px; line-height: 1.4;">❌ <strong>${cleanOptText}</strong> (ELENDİ): ${tReason}</div>`;
            return;
          }
          let reason = groupInfo ? `${groupInfo.name} yapısıdır. Soru kurgusundaki sentaks beklentisine uymadığı için elenir.` : "Zaman, bağlaç veya söz dizimi uyumsuzluğu sebebiyle elenir.";
          const optLower = (opt || "").toLowerCase();
          const sentenceLower = (question.sentence || "").toLowerCase();
          
          if (sentenceLower.includes("the first") || sentenceLower.includes("the last") || sentenceLower.includes("the only") || sentenceLower.includes("the second")) {
            reason = "[KURAL 7: First/Last/Only] Sıralama ve üstünlük sıfatlarından sonra V-ing/V2 gelemez; kesinlikle 'TO + V1' (veya To be V3) seçilmelidir!";
          } else if (sentenceLower.includes("recently") || sentenceLower.includes("lately")) {
            reason = "[KURAL 8: Recently/Lately] 'Recently' ve 'Lately' belirteçleri Simple Tenses alamaz; doğrudan 'Present Perfect (Have/Has V3)' gerektirir!";
          } else if (sentenceLower.includes("realized") || sentenceLower.includes("noticed") || sentenceLower.includes("discovered") || sentenceLower.includes("understood")) {
            reason = "[KURAL 6: Realize Grubu] Past farkındalık fiillerinden sonra gerçekleşen eylem daha eski olduğu için 'Past Perfect (Had V3)' gerektirir!";
          } else if (sentenceLower.includes("by ") || sentenceLower.includes("by the time")) {
            reason = "[KURAL 4: BY Miladı] 'By' zaman sınırlayıcısı olan yerde Simple/Continuous zamanlar elenir; 'Past Perfect (Had V3)' veya 'Future Perfect (Will Have V3)' aranır!";
          } else if (sentenceLower.includes("since")) {
            reason = "[KURAL 5: Since Belirleyicisi] 'Since' yan cümlesine V2 alır, ana cümleye Have/Has V3 alır; yan cümleye 'Have V3' gelemez!";
          } else if (optLower === "yet") {
            reason = "'Yet' zarfı Present Perfect ile olumsuz cümlelerde veya sorularda genellikle cümle sonunda kullanılır; olumlu cümle ortasında kullanılamaz.";
          } else if (optLower === "still") {
            reason = "'Still' eylemin devam ettiğini vurgular; Present Perfect kalıbında (has/have + V3) olumlu cümle ortasında 'already' yerini alamaz.";
          } else if (optLower.includes("will have") || optLower.includes("had been v-ing")) {
            reason = "Cümlede belirli bir gelecek/geçmiş zaman sınırlayıcısı (by 2030, by the time V2 vb.) olmadığı için elenir.";
          } else if (optLower.includes("had ") || optLower.includes("was ") || optLower.includes("were ") || optLower.includes("ed")) {
            reason = "Yan cümle Present (V1) yapısındayken Past (V2/Had V3) kullanımı zaman uyumsuzluğu (Tense Mismatch) yaşatır.";
          } else if (optLower.includes("will ") || optLower.includes("would ")) {
            reason = "Zaman veya şart bağlaçlarının (when, before, if, unless) yan cümle tarafına 'will' veya 'would' GELEMEZ!";
          } else if (optLower.includes("that")) {
            reason = "Edatlardan (preposition) hemen sonra doğrudan 'that' kullanılamaz!";
          }
          
          analysisHtml += `<div style="color: var(--text-secondary); opacity: 0.9; margin-top: 4px; line-height: 1.4;">❌ <strong>${cleanOptText}</strong>${groupTag} (ELENDİ): ${reason}</div>`;
        }
      });
      
      optionAnalysisEl.innerHTML = analysisHtml;
      optionAnalysisEl.style.display = 'block';
    }

    // Hatalı cevaplarda gramatik açıklama pop-up'ını tetikle (Hız Tüneli hariç)
    if (question.type !== 'true-false' && question.type !== 'reflex-blitz') {
      showGrammarExplanationModal(question, selectedAnswer);
    }
  }

  saveState();

  const btnCheck = document.getElementById('btn-check');
  btnCheck.textContent = 'DEVAM ET';
  btnCheck.disabled = false;
  try {
    btnCheck.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } catch (e) {}

  const btnSkip = document.getElementById('btn-skip');
  if (btnSkip) {
    btnSkip.style.display = 'none';
  }

  if (isCorrect) {
    autoAdvanceTimeout = setTimeout(() => {
      nextQuestion();
    }, 5000);
  }
}

function showMCFeedback(question) {
  const options = document.querySelectorAll('.mc-option');
  options.forEach(btn => {
    const idx = parseInt(btn.dataset.index);
    if (idx === question.correctIndex) {
      btn.classList.add('correct');
    } else if (idx === selectedAnswer && idx !== question.correctIndex) {
      btn.classList.add('wrong');
    }
  });
}

function showEFFeedback(question) {
  const tokens = document.querySelectorAll('.ef-token');
  tokens.forEach(span => {
    const idx = parseInt(span.dataset.index);
    if (idx === question.correctIndex) {
      span.classList.add('correct');
      span.style.borderColor = 'var(--color-correct)';
      span.style.background = 'var(--color-correct-bg)';
      span.style.color = 'var(--color-correct)';
    } else if (idx === selectedAnswer && idx !== question.correctIndex) {
      span.classList.add('wrong');
      span.style.borderColor = 'var(--color-wrong)';
      span.style.background = 'var(--color-wrong-bg)';
      span.style.color = 'var(--color-wrong)';
    }
  });
}

function showFBFeedback(question) {
  const options = document.querySelectorAll('.fb-option');
  options.forEach(btn => {
    const idx = parseInt(btn.dataset.index);
    if (idx === question.correctIndex) {
      btn.classList.add('correct');
      btn.style.borderColor = 'var(--color-correct)';
      btn.style.background = 'var(--color-correct-bg)';
      btn.style.color = 'var(--color-correct)';
    } else if (idx === selectedAnswer && idx !== question.correctIndex) {
      btn.classList.add('wrong');
      btn.style.borderColor = 'var(--color-wrong)';
      btn.style.background = 'var(--color-wrong-bg)';
      btn.style.color = 'var(--color-wrong)';
    }
  });
}

function skipQuestion() {
  if (autoAdvanceTimeout) {
    clearTimeout(autoAdvanceTimeout);
    autoAdvanceTimeout = null;
  }
  currentQuestionIndex++;

  const total = isFormationMode ? FORMATION_QUESTIONS.length : (isReviewMode ? reviewQuestions.length : currentQuizQuestions.length);
  if (currentQuestionIndex >= total) {
    if (isFormationMode) {
      completeFormationTour();
    } else if (isExamMode) {
      completeExamSession();
    } else if (isReviewMode) {
      completeReviewSession();
    } else {
      completeLesson();
    }
    return;
  }

  renderQuestion();
}

function nextQuestion() {
  if (autoAdvanceTimeout) {
    clearTimeout(autoAdvanceTimeout);
    autoAdvanceTimeout = null;
  }
  currentQuestionIndex++;
  saveActiveQuizState();

  // Canlar bitti mi?
  if (!isReviewMode && !isFormationMode && state.hearts <= 0) {
    showGameOver();
    return;
  }

  // Ders/Tekrar bitti mi?
  const total = isFormationMode ? FORMATION_QUESTIONS.length : (isReviewMode ? reviewQuestions.length : currentQuizQuestions.length);
  if (currentQuestionIndex >= total) {
    if (isFormationMode) {
      completeFormationTour();
    } else if (isExamMode) {
      completeExamSession();
    } else if (isReviewMode) {
      completeReviewSession();
    } else {
      completeLesson();
    }
    return;
  }

  renderQuestion();
}

