// Grubun bütün kaynaklarındaki sorular tek havuzda toplanır.
function examPoolQuestions(group) {
  const out = [];
  (group.sources || []).forEach(src => {
    const lesson = lessons.find(l => l.id === src.lessonId);
    if (!lesson) return;
    if (src.exerciseId) {
      const ex = (lesson.exercises || []).find(e => e.id === src.exerciseId);
      if (ex) out.push(...(ex.questions || []));
    } else {
      out.push(...getLessonQuestions(lesson));
    }
  });
  return out;
}

// Havuz 10'ar soruluk testlere bölünür; eksik kalan son test listelenmez.
function examTests(group) {
  const pool = examPoolQuestions(group);
  const tests = [];
  for (let i = 0; i < EXAM_TEST_COUNT; i++) {
    const chunk = pool.slice(i * EXAM_TEST_SIZE, (i + 1) * EXAM_TEST_SIZE);
    if (chunk.length < EXAM_TEST_SIZE) break;
    tests.push({
      id: `${group.id}-${i + 1}`, label: `Test ${i + 1}`,
      minutes: group.minutes, questions: chunk
    });
  }
  return tests;
}

// Testi id ile bul; grup bilgisi (başlık, beceri etiketi) oturuma taşınır.
function findExamTest(testId) {
  for (const g of EXAM_GROUPS) {
    const t = examTests(g).find(x => x.id === testId);
    if (t) return Object.assign({}, t, { title: `${g.title} — ${t.label}`, skill: g.skill, icon: g.icon });
  }
  return null;
}

function getExamQuestions(session) {
  if (Array.isArray(session.questions)) return session.questions.slice();
  return examPoolQuestions(session);
}

// Deneme sınavı yalnızca yerel geliştirme ortamında açık; yayındaki sürümde
// dersler tamamlanmadan erişilmesin diye kilitli gösterilir.
// Matrisler, robotlar, Yapısal Kurallar ve Deneme Sınavı web sürümünde de
// açık. Kilit yalnızca localhost/file: ortamında açılıyordu, yani mobil paket
// zaten açıktı; kapalı olan tek sürüm webdi. Kilit düzeneği (LOCKED_TABS,
// applyTabLock, renderExamLocked) yerinde duruyor: geri almak için bu
// fonksiyonu eski konak/protokol kontrolüne döndürmek yeterli.
function isExamUnlocked() {
  return true;
}

// Kilit geri getirilmek istenirse hangi sekmeleri kapsayacağının listesi.
// isExamUnlocked() true döndüğü sürece bu liste etkisizdir.
const LOCKED_TABS = ['time-matrix', 'transitions-matrix', 'simulator',
                     'structure-robot', 'exam', 'connector-drill'];

// Başlık sekmenin kendi etiketinden okunur; yeni bir sekme eklendiğinde burada
// ayrıca bir metin tutmak gerekmesin.
function lockedTabTitle(tabId) {
  const label = document.querySelector(`.nav-tab[data-tab="${tabId}"] .nav-tab-label`);
  const name = label ? label.textContent.trim() : '';
  return name ? `${name} Kilitli` : 'Bu Bölüm Kilitli';
}

function lockCardHtml(title) {
  return `
    <div class="tab-lock-overlay" style="display: flex; justify-content: center; padding: 24px 8px;">
      <div style="background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-xl); padding: 40px 28px; max-width: 480px; width: 100%; text-align: center; box-shadow: var(--shadow-lg); display: flex; flex-direction: column; align-items: center; gap: 18px; box-sizing: border-box;">
        <div style="font-size: 4.5rem; line-height: 1; filter: drop-shadow(0 4px 10px rgba(0,0,0,0.15)); animation: pulse 2s infinite;">🔒</div>
        <h3 style="font-family: var(--font-heading); font-size: 1.5rem; font-weight: 800; color: var(--accent-primary); margin: 0;">${title}</h3>
        <p style="font-size: 0.95rem; color: var(--text-secondary); line-height: 1.6; margin: 0;">
          Bu uygulamayı tüm dersleri bitirdikten sonra açabilirsiniz.
        </p>
      </div>
    </div>`;
}

// Kilitli sekmenin içeriği silinmez, gizlenir: kilit açıldığında (yerel
// geliştirme) sekmenin init fonksiyonları aradığı elemanları yerinde bulur.
function applyTabLock(tabId) {
  const el = document.getElementById('tab-content-' + tabId);
  if (!el) return false;

  const existing = Array.from(el.children).find(c => c.classList.contains('tab-lock-overlay'));
  const locked = LOCKED_TABS.includes(tabId) && !isExamUnlocked();

  if (!locked) {
    el.classList.remove('tab-locked');
    if (existing) existing.remove();
    return false;
  }
  if (!existing) el.insertAdjacentHTML('beforeend', lockCardHtml(lockedTabTitle(tabId)));
  el.classList.add('tab-locked');
  return true;
}

function renderExamLocked(listEl) {
  listEl.innerHTML = `
    <div style="grid-column: 1 / -1; display: flex; justify-content: center; padding: 24px 8px;">
      <div style="background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-xl); padding: 40px 28px; max-width: 480px; width: 100%; text-align: center; box-shadow: var(--shadow-lg); display: flex; flex-direction: column; align-items: center; gap: 18px; box-sizing: border-box;">
        <div style="font-size: 4.5rem; line-height: 1; filter: drop-shadow(0 4px 10px rgba(0,0,0,0.15)); animation: pulse 2s infinite;">🔒</div>
        <h3 style="font-family: var(--font-heading); font-size: 1.5rem; font-weight: 800; color: var(--accent-primary); margin: 0;">Deneme Sınavı Kilitli</h3>
        <p style="font-size: 0.95rem; color: var(--text-secondary); line-height: 1.6; margin: 0;">
          Bu uygulamayı tüm dersleri bitirdikten sonra açabilirsiniz.
        </p>
      </div>
    </div>`;
}

function renderExamTab() {
  const listEl = document.getElementById('exam-card-list');
  if (!listEl) return;

  if (!isExamUnlocked()) {
    renderExamLocked(listEl);
    return;
  }

  listEl.innerHTML = EXAM_GROUPS.map(g => {
    const rows = examTests(g).map(t => {
      const n = getExamQuestions(t).length;
      return `
        <div class="flex-between-wrap-10" style="padding: 8px 0; border-top: 1px solid var(--border-color);">
          <span class="text-sm-muted">${t.label} · ${n} soru · ${t.minutes} dk</span>
          <button class="btn btn-secondary" style="padding: 6px 14px; font-size: 0.8rem;"
                  data-exam-id="${t.id}" ${n ? '' : 'disabled'}>Başlat</button>
        </div>`;
    }).join('');
    return `
      <div class="card-panel" style="gap: 10px;">
        <div class="flex-center-12">
          <span class="icon-lg">${g.icon}</span>
          <div class="flex-col-4">
            <span class="section-title-sm">${g.title}</span>
            <span class="text-sm-muted">${g.desc}</span>
          </div>
        </div>
        ${rows}
      </div>`;
  }).join('');

  listEl.querySelectorAll('[data-exam-id]').forEach(btn => {
    btn.onclick = () => startExamSession(btn.dataset.examId);
  });
}

