// Her alıştırma 10'ar soruluk testlere bölünüp öyle listelenir: 80 soruluk tek
// bir düğme caydırıcı, 10 soruluk bir test oturulup bitirilebilir bir hedef.
const CONNECTOR_DRILL_TEST_SIZE = 10;

function connectorDrillTests(ex) {
  const qs = (ex && ex.questions) || [];
  const out = [];
  for (let i = 0; i < qs.length; i += CONNECTOR_DRILL_TEST_SIZE) {
    out.push(qs.slice(i, i + CONNECTOR_DRILL_TEST_SIZE));
  }
  return out;
}

function renderConnectorDrillTab() {
  const listEl = document.getElementById('connector-drill-list');
  if (!listEl) return;

  document.querySelectorAll('.drill-tab').forEach(btn => {
    const on = btn.dataset.drillSection === drillActiveSection;
    btn.classList.toggle('active', on);
    btn.classList.toggle('pill-toggle', !on);
    btn.onclick = () => {
      drillActiveSection = btn.dataset.drillSection;
      renderConnectorDrillTab();
    };
  });

  const sec = CONNECTOR_DRILL_SECTIONS.find(x => x.lessonId === drillActiveSection)
           || CONNECTOR_DRILL_SECTIONS[0];
  const lesson = lessons.find(l => l.id === sec.lessonId);
  const exercises = (lesson && lesson.exercises) || [];
  if (!exercises.length) {
    listEl.innerHTML = '<p class="text-sm-muted">Bu alıştırma henüz hazır değil.</p>';
    return;
  }

  const total = exercises.reduce((a, e) => a + (e.questions || []).length, 0);
  // Temel ayrım kartı ilk gelişte açık gelir, sonra kapatılabilir ve tercih hatırlanır.
  const introOpen = !drillIntroCollapsed(sec.lessonId);
  const intro = sec.intro ? `
    <div class="card-panel" style="grid-column: 1 / -1; gap: 0; padding: 18px 22px;">
      <button type="button" id="drill-intro-toggle"
              style="display: flex; align-items: center; justify-content: space-between; gap: 12px;
                     background: none; border: none; padding: 0; cursor: pointer; width: 100%; text-align: left;">
        <span class="section-title-sm">📚 ${sec.intro.title}</span>
        <span class="text-sm-muted" id="drill-intro-caret">${introOpen ? '▲ Gizle' : '▼ Göster'}</span>
      </button>
      <div id="drill-intro-body" style="display: ${introOpen ? 'block' : 'none'}; margin-top: 14px; font-size: 0.9rem; color: var(--text-primary);">
        ${sec.intro.html}
      </div>
    </div>` : '';
  const head = intro + `
    <div style="grid-column: 1 / -1; margin: 2px 0;">
      <p class="text-sm-muted" style="margin: 0;">${sec.desc} · ${exercises.length} alıştırma, ${total} soru</p>
    </div>`;

  const cards = exercises.map(ex => {
    const tests = connectorDrillTests(ex);
    const rows = tests.map((chunk, t) => `
      <div class="flex-between-wrap-10" style="padding: 8px 0; border-top: 1px solid var(--border-color);">
        <span class="text-sm-muted">Test ${t + 1} · ${chunk.length} soru</span>
        <div style="display: flex; gap: 6px;">
          <button class="btn btn-secondary" style="padding: 6px 10px; font-size: 0.78rem;"
                  data-brief-ex="${ex.id}" data-brief-test="${t}" title="Bu testin kurallarını göster">📖 Kurallar</button>
          <button class="btn btn-secondary" style="padding: 6px 14px; font-size: 0.8rem;"
                  data-drill-lesson="${sec.lessonId}" data-drill-ex="${ex.id}" data-drill-test="${t}">Başlat</button>
        </div>
      </div>`).join('');
    return `
      <div class="card-panel" style="gap: 10px;">
        <div class="flex-center-12">
          <span class="icon-lg">${sec.icons[ex.id] || '📘'}</span>
          <div class="flex-col-4">
            <span class="section-title-sm">${ex.title}</span>
            <span class="text-sm-muted">${ex.description || ''}</span>
          </div>
        </div>
        ${rows}
      </div>`;
  }).join('');

  listEl.innerHTML = head + cards;

  listEl.querySelectorAll('[data-drill-ex]').forEach(btn => {
    btn.onclick = () => startConnectorDrill(btn.dataset.drillLesson, btn.dataset.drillEx,
                                            parseInt(btn.dataset.drillTest, 10) || 0);
  });
  const introToggle = listEl.querySelector('#drill-intro-toggle');
  if (introToggle) {
    introToggle.onclick = () => {
      const bodyEl = listEl.querySelector('#drill-intro-body');
      const open = bodyEl.style.display === 'none';
      bodyEl.style.display = open ? 'block' : 'none';
      listEl.querySelector('#drill-intro-caret').textContent = open ? '▲ Gizle' : '▼ Göster';
      setDrillIntroCollapsed(sec.lessonId, !open);
    };
  }

  listEl.querySelectorAll('[data-brief-ex]').forEach(btn => {
    btn.onclick = () => {
      const e = exercises.find(x => x.id === btn.dataset.briefEx);
      const t = parseInt(btn.dataset.briefTest, 10) || 0;
      const chunk = connectorDrillTests(e)[t] || [];
      showRuleBriefing(`${e.title} — Test ${t + 1}`, drillBriefCards(chunk), null);
    };
  });
}

// ── Soru içi formül hatırlatıcısı ──────────────────────────────────────────
// Sorunun terim etiketleri tıklanabilir çip olarak çizilir; çipe basınca o
// terimin kuralı ve tuzağı cümlenin üstünde açılır. Varsayılan kapalı,
// açıldıysa oturum boyunca açık kalır -- öğrenci 10 soruda 10 kez tıklamasın.
let drillHintOpen = false;

function renderDrillFormulaHint(body, question) {
  const terms = (question && question.terms) || [];
  if (!activeDrillSession || !terms.length) return false;

  const cards = terms.map(findRuleCard).filter(Boolean);
  if (!cards.length) return false;

  // Etiketlenen terim çoğu soruda aynı zamanda DOĞRU CEVAPTIR. Terim adını
  // çipe ya da panele yazmak, öğrenci hatırlatıcıyı açmadan bile cevabı ele
  // verir. Bu yüzden şıklarda geçen terimlerin adı maskelenir; geriye kuralın
  // yapısal bilgisi kalır (";" sonrası virgüllü boşluk hangi sınıfı ister).
  //
  // Bu tehlike yalnızca fill-blank-dropdown sorularında var: orada options[]
  // doğrudan aday cevaplardır, terim adı = doğru şık. Hata avcılığı (error-
  // spotting) sorularında options[] cümlenin PARÇALARIdır (hangi öbek yanlış);
  // bağlacın kendisi bu parçalardan biri olsa bile adının görünmesi hangi
  // öbeğin hatalı olduğunu ele vermez. O yüzden leaks() yalnızca dropdown
  // sorularında çalışır; aksi halde kural metni tamamen açık kalır.
  const isChoiceType = question.type === 'fill-blank-dropdown';
  const inOptions = new Set((question.options || []).map(o => String(o).toLowerCase().trim()));
  // Son güvenlik katmanı: kural metni ne söylerse söylesin, doğru cevabın
  // kendisi hatırlatıcıda görünmemeli. Hata avcılığı sorularında cevap hatalı
  // öbektir ve tuzak metni çoğu zaman doğru biçimi adıyla anıyordu.
  const answer = String((question.options || [])[question.correctIndex] || '').trim();
  const maskAnswer = text => {
    if (answer.length < 2) return text;
    const esc = answer.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return String(text || '').replace(new RegExp('\\b' + esc + '\\b', 'gi'), '____');
  };
  const leaks = term => {
    if (!isChoiceType) return false;
    const t = String(term).toLowerCase();
    return [...inOptions].some(o => o && (o === t || t.includes(o) || o.includes(t)));
  };
  const mask = (text, term) => {
    let out = String(text || '');
    String(term).split(/[\/|]/).forEach(part => {
      const p = part.replace(/\([^)]*\)/g, '').trim();
      if (p.length < 2) return;
      const esc = p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      out = out.replace(new RegExp('\\b' + esc + '\\b', 'gi'), '____');
    });
    return out;
  };

  const panels = cards.map((c, i) => {
    const hide = leaks(c.term);
    const head = hide
      ? '<span style="font-weight: 800;">Bu boşluğun kuralı</span>'
      : `<span style="font-weight: 800;">${maskAnswer(c.term)}</span>
         <span style="font-size: 0.78rem; color: var(--text-secondary);">${maskAnswer(c.meaning || '')}</span>`;
    const rule = String(c.rule || c.formula || '');
    const trap = String(c.trap || '');
    return `
      <div class="drill-hint-panel" data-hint-panel="${i}"
           style="display: ${drillHintOpen ? 'block' : 'none'}; text-align: left; margin: 0 auto 8px auto;
                  max-width: 640px; padding: 10px 14px; border-radius: var(--radius-md);
                  border: 1px solid var(--border-color); background: var(--bg-card);">
        <div style="display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; margin-bottom: 6px;">${head}</div>
        ${(txt => looksLikeFormula(txt)
             ? formulaRowsHTML(txt)
             : `<div style="font-size: 0.82rem; font-weight: 700; color: var(--accent-primary); line-height: 1.5;">${txt.replace(/\n/g, '<br>')}</div>`
          )(maskAnswer(hide ? mask(rule, c.term) : rule))}
        ${trap ? `<div style="margin-top: 5px; font-size: 0.78rem; color: #ef4444; line-height: 1.5;">${maskAnswer(hide ? mask(trap, c.term) : trap)}</div>` : ''}
      </div>`;
  }).join('');

  // Tek ve nötr bir düğme: etiketinde terim adı geçmez.
  body.insertAdjacentHTML('afterbegin', `
    <div class="drill-hint-wrap" style="width: 100%; margin: 0 auto 14px auto;">
      <div style="display: flex; justify-content: center; margin-bottom: 8px;">
        <button type="button" class="drill-hint-chip"
                style="font-size: 0.72rem; font-weight: 700; padding: 4px 12px; border-radius: 9999px;
                       background: rgba(139, 126, 200, 0.15); color: var(--accent-primary, #8b7ec8);
                       border: 1px solid rgba(139, 126, 200, 0.3); cursor: pointer;">
          📐 ${drillHintOpen ? 'Kuralı gizle' : 'Kuralı hatırlat'}
        </button>
      </div>
      ${panels}
    </div>`);

  const wrap = body.querySelector('.drill-hint-wrap');
  const chip = wrap.querySelector('.drill-hint-chip');
  chip.onclick = () => {
    drillHintOpen = !drillHintOpen;
    wrap.querySelectorAll('.drill-hint-panel').forEach(p => {
      p.style.display = drillHintOpen ? 'block' : 'none';
    });
    chip.textContent = drillHintOpen ? '📐 Kuralı gizle' : '📐 Kuralı hatırlat';
  };
  return true;
}

// ── Kural brifingi ──────────────────────────────────────────────────────────
// Alıştırmaların kuralları matrislerde zaten yazılı; eksik olan yönlendirmeydi.
// Her soru çalıştırdığı terimlerle etiketli (questions[].terms), brifing de o
// etiketlerden derleniyor: testte en sık geçen terimlerin kartları gösterilir.
const DRILL_INTRO_KEY = 'amok_drill_intro_collapsed';

function drillIntroCollapsed(lessonId) {
  try {
    return (JSON.parse(localStorage.getItem(DRILL_INTRO_KEY) || '[]') || []).includes(lessonId);
  } catch (e) { return false; }
}

function setDrillIntroCollapsed(lessonId, collapsed) {
  try {
    let list = JSON.parse(localStorage.getItem(DRILL_INTRO_KEY) || '[]') || [];
    list = list.filter(x => x !== lessonId);
    if (collapsed) list.push(lessonId);
    localStorage.setItem(DRILL_INTRO_KEY, JSON.stringify(list));
  } catch (e) { /* depolama kapalıysa kart yine çalışır, tercih hatırlanmaz */ }
}

const DRILL_BRIEF_KEY = 'amok_drill_briefed';
const DRILL_BRIEF_MAX = 6;

function findRuleCard(term) {
  const srcs = [typeof TIME_MATRIX_DATA !== 'undefined' ? TIME_MATRIX_DATA : null,
                typeof TRANSITIONS_MATRIX_DATA !== 'undefined' ? TRANSITIONS_MATRIX_DATA : null,
                typeof CAUSE_EFFECT_DATA !== 'undefined' ? CAUSE_EFFECT_DATA : null];
  for (const src of srcs) {
    if (!src) continue;
    for (const list of Object.values(src)) {
      const hit = (list || []).find(x => x.term === term);
      if (hit) return hit;
    }
  }
  return null;
}

// Testteki sorulardan, en sık geçen terimlerin kartlarını çıkarır.
function drillBriefCards(questions) {
  const freq = {}, first = {};
  (questions || []).forEach(q => (q.terms || []).forEach((t, i) => {
    freq[t] = (freq[t] || 0) + 1;
    // Etiketler açıklamada geçenler önde olacak şekilde sıralı; ilk görülen
    // konumu sıklık eşitliğinde ayırt edici olarak saklıyoruz.
    if (first[t] === undefined || i < first[t]) first[t] = i;
  }));
  return Object.keys(freq)
    .sort((a, b) => (freq[b] - freq[a]) || (first[a] - first[b]))
    .map(findRuleCard)
    .filter(Boolean)
    .slice(0, DRILL_BRIEF_MAX);
}

function drillBriefSeen(exerciseId) {
  try {
    return (JSON.parse(localStorage.getItem(DRILL_BRIEF_KEY) || '[]') || []).includes(exerciseId);
  } catch (e) { return false; }
}

function markDrillBriefSeen(exerciseId) {
  try {
    const seen = JSON.parse(localStorage.getItem(DRILL_BRIEF_KEY) || '[]') || [];
    if (!seen.includes(exerciseId)) {
      seen.push(exerciseId);
      localStorage.setItem(DRILL_BRIEF_KEY, JSON.stringify(seen));
    }
  } catch (e) { /* depolama kapalıysa brifing yine çalışır, sadece hatırlanmaz */ }
}

function showRuleBriefing(title, cards, onStart) {
  const old = document.getElementById('drill-brief-modal');
  if (old) old.remove();

  if (!cards.length) { if (onStart) onStart(); return; }

  const body = cards.map(c => {
    const ex = (c.examples || [])[0];
    return `
      <div style="border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 14px 16px; background: var(--bg-card);">
        <div style="display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap;">
          <span style="font-weight: 800; font-size: 1rem; color: var(--text-primary);">${c.term}</span>
          <span style="font-size: 0.82rem; color: var(--text-secondary);">${c.meaning || ''}</span>
        </div>
        <div style="margin-top: 8px; font-size: 0.85rem; font-weight: 700; color: var(--accent-primary); line-height: 1.5;">
          ${(txt => looksLikeFormula(txt) ? formulaRowsHTML(txt) : txt.replace(/\n/g, '<br>'))(String(c.rule || c.formula || ''))}
        </div>
        ${c.trap ? `<div style="margin-top: 6px; font-size: 0.82rem; color: #ef4444; line-height: 1.5;">${c.trap}</div>` : ''}
        ${ex ? `<div style="margin-top: 8px; font-size: 0.82rem; color: var(--text-secondary); line-height: 1.5;">
                  🇬🇧 ${ex.en}<br><span style="font-style: italic;">🇹🇷 ${ex.tr}</span>
                </div>` : ''}
      </div>`;
  }).join('');

  const modal = document.createElement('div');
  modal.id = 'drill-brief-modal';
  modal.style.cssText = 'position:fixed; inset:0; background:rgba(10,10,18,0.75); backdrop-filter:blur(10px);' +
    'z-index:10000; display:flex; align-items:center; justify-content:center; padding:20px;';
  modal.innerHTML = `
    <div style="background: var(--bg-body); border: 1px solid var(--border-color); border-radius: var(--radius-xl);
                max-width: 640px; width: 100%; max-height: 86vh; display: flex; flex-direction: column;
                box-shadow: var(--shadow-lg); overflow: hidden;">
      <div style="padding: 20px 24px 12px;">
        <span style="font-size: 0.75rem; font-weight: 800; letter-spacing: 0.06em; color: var(--text-secondary);">BAŞLAMADAN ÖNCE</span>
        <h2 style="margin: 6px 0 0; font-family: var(--font-heading); font-size: 1.2rem; font-weight: 800; color: var(--text-primary);">${title}</h2>
        <p style="margin: 6px 0 0; font-size: 0.85rem; color: var(--text-secondary);">Bu testte çalışacağın kurallar:</p>
      </div>
      <div style="padding: 4px 24px 16px; overflow-y: auto; display: flex; flex-direction: column; gap: 10px;">
        ${body}
      </div>
      <div style="padding: 14px 24px 20px; border-top: 1px solid var(--border-color); display: flex; gap: 10px; justify-content: flex-end;">
        <button class="btn btn-secondary" id="drill-brief-close" style="padding: 10px 18px;">Kapat</button>
        ${onStart ? '<button class="btn btn-primary" id="drill-brief-start" style="padding: 10px 22px;">Anladım, başla</button>' : ''}
      </div>
    </div>`;
  document.body.appendChild(modal);

  const close = () => modal.remove();
  modal.querySelector('#drill-brief-close').onclick = close;
  const startBtn = modal.querySelector('#drill-brief-start');
  if (startBtn) startBtn.onclick = () => { close(); onStart(); };
  modal.onclick = e => { if (e.target === modal) close(); };
}

function startConnectorDrill(lessonId, exerciseId, testIndex) {
  const lesson = lessons.find(l => l.id === lessonId);
  const ex = lesson && (lesson.exercises || []).find(e => e.id === exerciseId);
  const questions = connectorDrillTests(ex)[testIndex || 0] || [];
  if (!questions.length) {
    showToast('Bu testte henüz soru bulunmuyor.', 'info');
    return;
  }

  const label = `${ex.title} — Test ${(testIndex || 0) + 1}`;

  // Bir alıştırmanın ilk testinde kurallar otomatik gösterilir; sonrasında
  // öğrenci isterse kart üzerindeki "Kuralları gör" ile açar.
  if (!drillBriefSeen(exerciseId)) {
    markDrillBriefSeen(exerciseId);
    showRuleBriefing(label, drillBriefCards(questions), () => runConnectorDrill(questions, label));
    return;
  }
  runConnectorDrill(questions, label);
}

function runConnectorDrill(questions, label) {
  activeDrillSession = true;
  quizSessionId++;
  isReviewMode = true;    // can kaybı yok, soru kaynağı reviewQuestions
  isExamMode = false;     // geri bildirim anında gelsin
  examCurrent = null;
  // Başlık tekrar modundan geliyordu ve 'Hızlı Tekrar' yazıyordu; alıştırmanın
  // kendi adı zaten elimizde.
  examSessionLabel = label || 'Yapısal Kurallar';
  reviewQuestions = questions;
  reviewSessionCorrectIds = [];
  currentQuestionIndex = 0;
  quizShuffleEpoch++;
  correctCount = 0;
  wrongCount = 0;

  showScreen('quiz-screen');
  renderQuestion();
}

function startExamSession(examId) {
  activeDrillSession = false;
  if (!isExamUnlocked()) {
    showToast('Bu uygulamayı tüm dersleri bitirdikten sonra açabilirsiniz.', 'info');
    return;
  }
  const session = findExamTest(examId);
  if (!session) return;
  const questions = getExamQuestions(session);
  if (!questions.length) {
    showToast('Bu denemede henüz soru bulunmuyor.', 'info');
    return;
  }

  // Tekrar oturumu altyapısını yeniden kullanıyoruz: can kaybı yok, ilerleme
  // kaydı ve mevcut soru arayüzü hazır geliyor.
  quizSessionId++;
  isReviewMode = true;   // soru kaynağı ve can muafiyeti bu bayraktan geliyor
  isExamMode = true;
  examSessionLabel = session.title;
  examCurrent = session;
  examAnswers = [];
  reviewQuestions = questions;
  reviewSessionCorrectIds = [];
  currentQuestionIndex = 0;
  quizShuffleEpoch++;
  correctCount = 0;
  wrongCount = 0;

  startExamTimer(session.minutes || 35);

  showScreen('quiz-screen');
  renderQuestion();
}

// ── Süre ───────────────────────────────────────────────────────────────────
function startExamTimer(minutes) {
  stopExamTimer();
  examEndsAt = Date.now() + minutes * 60 * 1000;
  examTimerId = setInterval(() => {
    if (!isExamMode) { stopExamTimer(); return; }
    if (Date.now() >= examEndsAt) {
      stopExamTimer();
      showToast('Süre doldu. Deneme sonlandırıldı.', 'info');
      completeExamSession();
      return;
    }
    paintExamTimer();
  }, 1000);
}

function stopExamTimer() {
  if (examTimerId) { clearInterval(examTimerId); examTimerId = null; }
}

function paintExamTimer() {
  const el = document.getElementById('exam-timer');
  if (!el) return;
  const left = Math.max(0, examEndsAt - Date.now());
  const m = Math.floor(left / 60000);
  const sec = Math.floor((left % 60000) / 1000);
  el.textContent = `${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
  el.style.color = left < 5 * 60 * 1000 ? 'var(--color-wrong)' : '';
}

// ── Beceri etiketi (sonuç dökümü için) ─────────────────────────────────────
function getExamSkill(question) {
  if (question.examSkill) return question.examSkill;
  if (examCurrent && examCurrent.skill) return examCurrent.skill;
  const p = String(question.prompt || '').toLowerCase();
  if (p.includes('ana fikri') || p.includes('başlık')) return 'Ana fikir';
  if (p.includes('çıkarılabilir') || p.includes('çıkarım')) return 'Çıkarım';
  if (p.includes('kelimesi') || p.includes('anlamca')) return 'Kelime';
  if (p.includes('tutum') || p.includes('ne demek istemektedir') ||
      p.includes('neden aktarmaktadır') || p.includes('yaklaşımı') || p.includes('bakışı')) return 'Tutum / Amaç';
  if (p.includes('parçaya göre') || p.includes('göre')) return 'Detay';
  return (question.grammarTags && question.grammarTags[0]) || 'Diğer';
}

// ── Sonuç ekranı ───────────────────────────────────────────────────────────
function completeExamSession() {
  stopExamTimer();
  const answers = examAnswers.slice();
  const questions = reviewQuestions.slice();
  const label = examSessionLabel || 'Deneme';

  isExamMode = false;
  isReviewMode = false;
  examSessionLabel = null;
  localStorage.removeItem('amok_active_quiz_type');

  const total = questions.length;
  const right = answers.filter(a => a.correct).length;
  const pct = total ? Math.round((right / total) * 100) : 0;

  const bySkill = {};
  answers.forEach(a => {
    const k = a.skill || 'Diğer';
    bySkill[k] = bySkill[k] || { right: 0, total: 0 };
    bySkill[k].total++;
    if (a.correct) bySkill[k].right++;
  });

  const wrongList = answers.filter(a => !a.correct).map(a => {
    const q = questions.find(x => x.id === a.id);
    if (!q) return '';
    const correctOpt = q.options ? q.options[q.correctIndex] : '';
    const chosen = (q.options && typeof a.selected === 'number') ? q.options[a.selected] : null;
    return `
      <div style="border:1px solid var(--border-color); border-radius: var(--radius-md); padding: 12px 14px; margin-bottom: 10px; background: var(--bg-card);">
        <div class="text-label" style="margin-bottom:6px;">${q.prompt}</div>
        ${chosen ? `<div class="text-sm-muted" style="color: var(--color-wrong);">Senin cevabın: ${chosen}</div>` : ''}
        <div class="text-sm-muted" style="color: var(--color-correct);">Doğru cevap: ${correctOpt}</div>
        ${q.explanation ? `<div class="text-sm-muted" style="margin-top:6px;">${q.explanation}</div>` : ''}
      </div>`;
  }).join('');

  state.xp += right * XP_PER_CORRECT;
  saveState();
  updateTopBar();

  playCompletionSound(true);
  showScreen('home-screen');
  switchTab('exam');

  const listEl = document.getElementById('exam-card-list');
  if (listEl) {
    listEl.innerHTML = `
      <div class="card-panel" style="grid-column: 1 / -1; gap: 16px;">
        <div class="flex-between-wrap-10">
          <span class="section-title-sm">${label} — Sonuç</span>
          <span class="exercise-q-badge">${right}/${total} · %${pct}</span>
        </div>
        <div>
          <div class="text-label" style="margin-bottom:8px;">Soru tipine göre döküm</div>
          ${Object.entries(bySkill).map(([k, v]) =>
            `<div class="flex-between-wrap-10" style="margin-bottom:6px;">
               <span class="text-sm-muted">${k}</span>
               <span class="text-label-muted">${v.right}/${v.total}</span>
             </div>`).join('')}
        </div>
        ${wrongList ? `<div><div class="text-label" style="margin:6px 0 8px;">Yanlış yaptığın sorular</div>${wrongList}</div>`
                    : '<div class="text-sm-muted">Tüm soruları doğru yanıtladın. 🎉</div>'}
        <button class="btn btn-primary" onclick="renderExamTab()">Denemelere Dön</button>
      </div>`;
  }
}

function completeReviewSession() {
  isReviewMode = false;
  examSessionLabel = null;

  // Oturum bittiğinde doğru cevaplanan soruları hatalı listesinden düşür
  if (reviewSessionCorrectIds && reviewSessionCorrectIds.length > 0) {
    reviewSessionCorrectIds.forEach(id => {
      const idx = state.wrongQuestions.indexOf(id);
      if (idx > -1) {
        state.wrongQuestions.splice(idx, 1);
      }
    });
  }

  const wasDrill = activeDrillSession;
  activeDrillSession = false;

  if (!wasDrill) updateDailyTaskProgress('review', 1);
  saveState();
  playCompletionSound(true);
  showToast(wasDrill ? 'Test tamamlandı! 🎉'
                     : 'Tekrar oturumu tamamlandı! Yanlışlarını pekiştirdin. 🎉', 'success');

  updateTopBar();
  renderLessonTree();
  // renderAchievements(); // BAŞARIMLAR DEVRE DIŞI
  checkReviewBanner();
  showScreen('home-screen');
  // Alıştırmadan gelindiyse Yapısal Kurallar sekmesine dönülür; hangi alt
  // bölümde kalındığı drillActiveSection'da zaten duruyor.
  switchTab(wasDrill ? 'connector-drill' : 'lessons');
}

function completeFormationTour() {
  isFormationMode = false;
  
  const isFirstTime = !state.formationTourCompleted;
  state.formationTourCompleted = true;

  if (isFirstTime) {
    state.xp += 50;
    showToast('Tebrikler! Formasyon Turunu tamamladınız ve 50 XP kazandınız! 🎓', 'success');
  } else {
    showToast('Tebrikler! Formasyon Turunu tekrar tamamladınız! 🎓', 'success');
  }

  // Confetti & Sound explosion
  playCompletionSound(true);
  if (typeof confetti === 'function') {
    confetti({
      particleCount: 150,
      spread: 80,
      origin: { y: 0.6 }
    });
  }

  saveState();
  updateTopBar();
  showScreen('home-screen');
  updateFormationTourCardUI();
}

// ============================================================
// DERS TAMAMLAMA
// ============================================================
function completeLesson() {
  const total = currentQuizQuestions.length;
  const accuracy = Math.round((correctCount / total) * 100);
  const isSuccess = isLocalEnvironment() || accuracy >= 80;
  
  isCurrentExercisePassed = isSuccess;

  let newAchievements = [];

  const earnedXP = isSuccess ? correctCount * XP_PER_CORRECT : 0;
  const exTitle = currentLesson.activeExerciseTitle ? ` - ${correctExerciseNumber(currentLesson)}` : '';

  if (isSuccess) {
    // Dersi tamamlanan listesine ekle
    if (currentLesson.activeExerciseId) {
      const exerciseKey = `${currentLesson.id}_${currentLesson.activeExerciseId}`;
      if (!state.completedLessons.includes(exerciseKey)) {
        state.completedLessons.push(exerciseKey);
      }
      // Eğer bu ders altındaki tüm alıştırmalar tamamlandıysa, dersin kendisini de tamamlandı olarak işaretle
      const allExercisesCompleted = currentLesson.exercises.every(ex =>
        state.completedLessons.includes(`${currentLesson.id}_${ex.id}`)
      );
      if (allExercisesCompleted && !state.completedLessons.includes(currentLesson.id)) {
        state.completedLessons.push(currentLesson.id);
      }
    } else {
      if (!state.completedLessons.includes(currentLesson.id)) {
        state.completedLessons.push(currentLesson.id);
      }
    }

    // Gece kuşu kontrolü
    const hour = new Date().getHours();
    if (hour >= 22 || hour < 6) {
      state.nightOwlTriggered = true;
    }

    // Mükemmeliyetçi kontrolü
    if (wrongCount === 0) {
      state.perfectLessonTriggered = true;
      updateDailyTaskProgress('perfect', 1);
      addCoins(6); // hatasız bitirme bonusu
    }

    updateDailyTaskProgress('lessons', 1);
    addCoins(8); // alıştırma tamamlama jeton ödülü
    saveState(true);
    if (typeof addRecentChange === 'function') {
      addRecentChange(`Ders Tamamlandı: ${currentLesson.title}`, `Kazanılan XP: +${earnedXP}`, 'lesson', currentLesson.id);
    }

    // Telegram notification
    try {
      const message = `🔔 *Ders Tamamlandı!*\n👤 *Kullanıcı:* ${state.username}\n📚 *Ders:* ${currentLesson.title}${exTitle}\n🎯 *Doğruluk:* %${accuracy}\n🏆 *Kazanılan XP:* +${earnedXP}\n🔥 *Seri:* ${state.streak} Gün`;
      sendTelegramNotification(message);
    } catch(e) {}

    // Başarım kontrolü
    // newAchievements = checkAchievements(); // BAŞARIMLAR DEVRE DIŞI
  }
  const trophyEl = document.querySelector('.summary-trophy');
  const titleEl = document.querySelector('.summary-title');
  const subtitleEl = document.getElementById('summary-lesson-name');
  const xpEl = document.getElementById('summary-xp');
  const accuracyEl = document.getElementById('summary-accuracy');
  const continueBtn = document.getElementById('btn-summary-continue');

  if (isSuccess) {
    if (trophyEl) trophyEl.textContent = '🏆';
    if (titleEl) titleEl.textContent = 'Tebrikler!';
    if (subtitleEl) subtitleEl.textContent = `"${currentLesson.title}${exTitle}" alıştırmasını tamamladın!`;
    if (xpEl) xpEl.textContent = `+${earnedXP}`;
    if (continueBtn) continueBtn.textContent = 'DEVAM ET';
  } else {
    if (trophyEl) trophyEl.textContent = '❌';
    if (titleEl) titleEl.textContent = 'Başarısız!';
    if (subtitleEl) subtitleEl.textContent = `Bu alıştırmayı geçmek için en az %80 doğruluk oranı elde etmelisin. Tekrar deneyerek barajı geçebilirsin.`;
    if (xpEl) xpEl.textContent = `+0`;
    if (continueBtn) continueBtn.textContent = 'TEKRAR DENE';
  }

  if (accuracyEl) accuracyEl.textContent = `${accuracy}%`;

  // BAŞARIMLAR DEVRE DIŞI — Yeni başarımları göster
  // const summaryAch = document.getElementById('summary-achievements');
  // const achList = document.getElementById('summary-achievement-list');
  // if (newAchievements.length > 0) {
  //   summaryAch.style.display = 'block';
  //   achList.innerHTML = newAchievements.map(a =>
  //     `<span class="summary-achievement-badge">${a.icon} ${a.title}</span>`
  //   ).join('');
  // } else {
  //   summaryAch.style.display = 'none';
  // }
  const summaryAch = document.getElementById('summary-achievements');
  if (summaryAch) summaryAch.style.display = 'none';

  // Konfeti ve Ses Efekti
  playCompletionSound(isSuccess);
  showScreen('summary-screen');
  if (typeof confetti === 'function') {
    setTimeout(() => {
      confetti({
        particleCount: 100,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#8b6e4e', '#5b8c5a', '#d4a843', '#c9a87c']
      });
    }, 300);
  }
}

