function showGameOver() {
  const costEl = document.getElementById('refill-cost');
  costEl.textContent = `(${HEARTS_REFILL_COST} Puan)`;

  const refillBtn = document.getElementById('btn-refill-hearts');
  refillBtn.disabled = state.xp < HEARTS_REFILL_COST;

  if (state.xp < HEARTS_REFILL_COST) {
    refillBtn.style.opacity = '0.5';
    refillBtn.title = `Yeterli puan yok. (${state.xp}/${HEARTS_REFILL_COST})`;
  } else {
    refillBtn.style.opacity = '1';
    refillBtn.title = '';
  }

  showScreen('gameover-screen');
}

// ============================================================
// TEMA DEĞİŞTİRME
// ============================================================
function initTheme() {
  const saved = localStorage.getItem('amok_theme');
  if (['gold', 'canva', 'mint', 'sakura', 'sunset', 'kutup', 'siber', 'orman'].includes(state.activeTheme)) {
    document.documentElement.setAttribute('data-theme', state.activeTheme);
  } else if (saved === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.getElementById('btn-theme').textContent = '☀️';
  }
}

function toggleTheme() {
  if (['gold', 'canva', 'mint', 'sakura', 'sunset', 'kutup', 'siber', 'orman'].includes(state.activeTheme)) {
    state.activeTheme = 'light';
    saveState();
  }
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  if (isDark) {
    document.documentElement.removeAttribute('data-theme');
    localStorage.setItem('amok_theme', 'light');
    document.getElementById('btn-theme').textContent = '🌙';
  } else {
    document.documentElement.setAttribute('data-theme', 'dark');
    localStorage.setItem('amok_theme', 'dark');
    document.getElementById('btn-theme').textContent = '☀️';
  }
  renderStore();
}

// ============================================================
// SEKME YÖNETİMİ
// ============================================================
const PROFILE_HUB_TABS = ['info', 'leaderboard', 'store'];

function switchProfileHub(hubId) {
  if (!hubId) hubId = 'info';
  state.activeProfileHub = hubId;

  // Update hub tab buttons
  document.querySelectorAll('.profile-hub-tab').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.hub === hubId);
  });

  // Move the sliding indicator
  const indicator = document.getElementById('profile-hub-indicator');
  if (indicator) {
    const idx = PROFILE_HUB_TABS.indexOf(hubId);
    indicator.setAttribute('data-pos', idx >= 0 ? idx : 0);
  }

  // Show/hide subcontent areas
  document.querySelectorAll('.profile-hub-content').forEach(area => {
    const isTarget = area.id === `profile-hub-${hubId}`;
    if (isTarget) {
      area.classList.add('active');
      // Re-trigger animation
      area.style.animation = 'none';
      area.offsetHeight; // force reflow
      area.style.animation = '';
    } else {
      area.classList.remove('active');
    }
  });

  // Render the appropriate content
  if (hubId === 'info') {
    renderProfile();
  } else if (hubId === 'leaderboard') {
    renderLeaderboard();
  } else if (hubId === 'store') {
    renderStore();
  }
}

function switchTab(tabId) {
  if (!tabId) return;
  
  // Redirect leaderboard/store to profile hub
  if (tabId === 'leaderboard') {
    switchTab('profile');
    switchProfileHub('leaderboard');
    return;
  }
  if (tabId === 'store') {
    switchTab('profile');
    switchProfileHub('store');
    return;
  }
  
  localStorage.setItem('amok_last_tab', tabId);

  document.querySelectorAll('.nav-tab').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === tabId);
  });
  
  const subtabsMenu = document.getElementById('admin-subtabs-menu');
  if (subtabsMenu) {
    if (tabId === 'admin') {
      subtabsMenu.style.display = 'flex';
    } else {
      subtabsMenu.style.display = 'none';
    }
  }
  if (typeof updateAdminBadgeCount === 'function') {
    updateAdminBadgeCount();
  }

  const userMenuBtn = document.getElementById('btn-user-menu');
  if (userMenuBtn) {
    if (tabId === 'profile') {
      userMenuBtn.style.boxShadow = '0 0 0 3px #ec4899, 0 4px 14px rgba(236, 72, 153, 0.5)';
      userMenuBtn.style.transform = 'scale(1.08)';
    } else {
      userMenuBtn.style.boxShadow = 'none';
      userMenuBtn.style.transform = 'none';
    }
  }

  document.querySelectorAll('.tab-content').forEach(content => {
    content.classList.toggle('active', content.id === `tab-content-${tabId}`);
  });

  // Kilitli sekmede init çalıştırılmaz; kilit kartı içeriğin yerini alır.
  if (applyTabLock(tabId)) return;

  if (tabId === 'profile') {
    switchProfileHub(state.activeProfileHub || 'info');
  } else if (tabId === 'simulator') {
    state.activePassiveMode = 'active';
    saveState();
    renderSimulator();
  } else if (tabId === 'feedback') {
    initFeedbackTab();
  } else if (tabId === 'cause-effect') {
    initCauseEffectTab();
  } else if (tabId === 'time-matrix') {
    initTimeMatrixTab();
  } else if (tabId === 'transitions-matrix') {
    initTransitionsMatrixTab();
  } else if (tabId === 'exam') {
    renderExamTab();
  } else if (tabId === 'connector-drill') {
    renderConnectorDrillTab();
  } else if (tabId === 'structure-robot') {
    loadScriptOnce('structure-robot.js').then(() => {
      if (typeof initStructureRobot === 'function') initStructureRobot();
    }).catch(err => {
      console.error(err);
      showToast('Yapı Robotu yüklenemedi, lütfen tekrar deneyin.', 'error');
    });
  }
}

// ============================================================
// BOŞ ALİŞTIRMALI DERS BULUCU (DEVELOPER TOOL)
// ============================================================
let lastVisitedEmptyLessonIndex = -1;

function navigateToNextEmptyLesson() {
  if (typeof lessons === 'undefined' || !lessons) return;

  const emptyLessons = lessons.filter(l => {
    return (!l.exercises || l.exercises.length === 0) && (!l.questions || l.questions.length === 0);
  });

  if (emptyLessons.length === 0) {
    showToast("Eksik alıştırması olan ders kalmamış! 🎉", "success");
    return;
  }

  lastVisitedEmptyLessonIndex = (lastVisitedEmptyLessonIndex + 1) % emptyLessons.length;
  const targetLesson = emptyLessons[lastVisitedEmptyLessonIndex];

  switchTab('lessons');

  setTimeout(() => {
    ensureLessonRendered(targetLesson.id);
    const btn = document.querySelector(`.lesson-node[data-lesson-id="${targetLesson.id}"]`);
    if (btn) {
      btn.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => {
        btn.click();
        showToast(`Boş Ders: ${targetLesson.title} - ${targetLesson.subtitle} (${lastVisitedEmptyLessonIndex + 1}/${emptyLessons.length})`, "info");
      }, 400);
    } else {
      showToast(`Ders düğmesi bulunamadı: ${targetLesson.title}`, "error");
    }
  }, 100);
}

