const STORE_CATEGORIES = [
  { id: 'boost',    label: '⚡ Güçlendiriciler' },
  { id: 'theme',    label: '🎨 Temalar' },
  { id: 'cosmetic', label: '✨ Kozmetik' }
];

const FREE_THEMES = ['light', 'canva'];
const THEME_IDS = STORE_CATALOG.filter(i => i.cat === 'theme').map(i => i.id);
let storeActiveCat = 'boost';

function catalogItem(id) { return STORE_CATALOG.find(i => i.id === id); }
function coinBalance() { return state.coins || 0; }
function addCoins(n) { state.coins = Math.max(0, Math.round((state.coins || 0) + n)); }
function themeOwned(id) { return FREE_THEMES.includes(id) || (state.purchasedThemes || []).includes(id); }
function cosmeticOwned(id) { return (state.purchasedCosmetics || []).includes(id); }
function equippedTitleLabel() {
  const it = catalogItem(state.equippedTitle);
  return it ? `${it.icon} ${it.label}` : '';
}
function applyThemeAttr(id) {
  if (id && id !== 'light') document.documentElement.setAttribute('data-theme', id);
  else document.documentElement.removeAttribute('data-theme');
}

// Geriye dönük durum göçü — eski hesaplar yeni ekonomiyle uyumlansın.
function migrateStoreEconomy() {
  if (!state.inventory || typeof state.inventory !== 'object') state.inventory = { streak_freeze: 0 };
  if (state.inventory.streak_freeze == null) state.inventory.streak_freeze = 0;
  if (!state.boosts || typeof state.boosts !== 'object') state.boosts = { xpBoosterQ: 0, heartShieldQ: 0 };
  if (state.boosts.xpBoosterQ == null) state.boosts.xpBoosterQ = 0;
  if (state.boosts.heartShieldQ == null) state.boosts.heartShieldQ = 0;
  if (!Array.isArray(state.purchasedThemes)) state.purchasedThemes = [];
  if (!Array.isArray(state.purchasedCosmetics)) state.purchasedCosmetics = [];

  // Eski tek seferlik "streakFreezeBought" bayrağı -> stoklanabilir envanter
  if (state.streakFreezeBought && state.inventory.streak_freeze < 1) {
    state.inventory.streak_freeze = 1;
  }
  // Daha önce etkinleştirilmiş ücretli tema -> kalıcı sahiplik
  if (state.activeTheme && !FREE_THEMES.includes(state.activeTheme) &&
      THEME_IDS.includes(state.activeTheme) && !state.purchasedThemes.includes(state.activeTheme)) {
    state.purchasedThemes.push(state.activeTheme);
  }
  // Tek seferlik jeton göçü: XP sıralamada kalır, jeton harcama birimidir.
  if (!state.coinsMigrated) {
    state.coins = (state.coins || 0) + 150 + Math.round((state.xp || 0) * 0.35);
    state.coinsMigrated = true;
  }
}

function buyStoreItem(id) {
  const it = catalogItem(id);
  if (!it) return;
  const cost = isLocalEnvironment() ? 0 : (it.cost || 0);
  const afford = () => {
    if (coinBalance() < cost) { showToast(`Yeterli jeton yok! (Gereken: ${cost} 🪙)`, 'error'); return false; }
    return true;
  };

  if (it.type === 'theme') {
    if (!themeOwned(id)) {
      if (!afford()) return;
      addCoins(-cost);
      state.purchasedThemes.push(id);
      state.activeTheme = id;
      applyThemeAttr(id);
      updateDailyTaskProgress('shop', 1);
      showToast(`${it.title} satın alındı ve etkinleştirildi! ${it.icon}`, 'success');
    } else if (state.activeTheme === id) {
      state.activeTheme = 'light';
      applyThemeAttr('light');
      showToast(`${it.title} kapatıldı.`, 'info');
    } else {
      state.activeTheme = id;
      applyThemeAttr(id);
      showToast(`${it.title} etkinleştirildi. ${it.icon}`, 'success');
    }
  } else if (it.type === 'instant' && id === 'hearts') {
    if (state.hearts >= MAX_HEARTS) { showToast('Canların zaten dolu!', 'warning'); return; }
    if (!afford()) return;
    addCoins(-cost);
    state.hearts = MAX_HEARTS;
    updateDailyTaskProgress('shop', 1);
    showToast('Canların yenilendi! ❤️', 'success');
  } else if (it.type === 'consumable' && id === 'streak_freeze') {
    const have = state.inventory.streak_freeze || 0;
    if (have >= (it.max || 3)) { showToast(`En fazla ${it.max} Seri Dondurucu taşıyabilirsin.`, 'warning'); return; }
    if (!afford()) return;
    addCoins(-cost);
    state.inventory.streak_freeze = have + 1;
    state.streakFreezeBought = true;
    updateDailyTaskProgress('shop', 1);
    showToast('Seri Dondurucu envanterine eklendi! ❄️', 'success');
  } else if (it.type === 'boost') {
    if (!afford()) return;
    addCoins(-cost);
    if (id === 'xp_booster') {
      state.boosts.xpBoosterQ = (state.boosts.xpBoosterQ || 0) + 20;
      showToast('⚡ XP Katlayıcı etkin! Sonraki 20 doğru cevap 2× puan.', 'success');
    } else if (id === 'heart_shield') {
      state.boosts.heartShieldQ = (state.boosts.heartShieldQ || 0) + 3;
      showToast('🛡️ Can Kalkanı etkin! Sonraki 3 yanlış can götürmez.', 'success');
    }
    updateDailyTaskProgress('shop', 1);
  } else if (it.type === 'title' || it.type === 'frame') {
    const slot = it.type === 'title' ? 'equippedTitle' : 'equippedFrame';
    if (!cosmeticOwned(id)) {
      if (!afford()) return;
      addCoins(-cost);
      state.purchasedCosmetics.push(id);
      state[slot] = id;
      updateDailyTaskProgress('shop', 1);
      showToast(`${it.title} alındı ve kuşanıldı! ${it.icon}`, 'success');
    } else if (state[slot] === id) {
      state[slot] = null;
      showToast(`${it.title} çıkarıldı.`, 'info');
    } else {
      state[slot] = id;
      showToast(`${it.title} kuşanıldı. ${it.icon}`, 'success');
    }
  }

  saveState();
  updateTopBar();
  renderStore();
}

function storeCardHTML(it) {
  const esc = s => String(s || '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  const cost = isLocalEnvironment() ? 0 : (it.cost || 0);
  const priceLabel = cost === 0 ? 'Ücretsiz' : `${cost} 🪙`;
  let btnLabel = priceLabel;
  let btnClass = 'btn-primary';
  let disabled = false;
  let status = '';

  if (it.type === 'theme') {
    if (!themeOwned(it.id)) {
      btnLabel = priceLabel; btnClass = 'btn-primary';
    } else if (state.activeTheme === it.id) {
      btnLabel = 'Aktif (Kapat)'; btnClass = 'btn-secondary';
      status = '<span class="store-card-status owned">✓ Sahipsin</span>';
    } else {
      btnLabel = 'Etkinleştir'; btnClass = 'btn-secondary-outline';
      status = '<span class="store-card-status owned">✓ Sahipsin</span>';
    }
  } else if (it.type === 'instant' && it.id === 'hearts') {
    if (state.hearts >= MAX_HEARTS) { disabled = true; btnLabel = 'Canların Dolu'; btnClass = 'btn-secondary'; }
  } else if (it.type === 'consumable' && it.id === 'streak_freeze') {
    const have = state.inventory.streak_freeze || 0;
    status = `<span class="store-card-status">Envanter: ${have}/${it.max}</span>`;
    if (have >= it.max) { disabled = true; btnLabel = 'Dolu (Maks.)'; btnClass = 'btn-secondary'; }
  } else if (it.type === 'boost') {
    const q = it.id === 'xp_booster' ? (state.boosts.xpBoosterQ || 0) : (state.boosts.heartShieldQ || 0);
    const unit = it.id === 'xp_booster' ? 'doğru' : 'yanlış';
    if (q > 0) status = `<span class="store-card-status active">⏳ Aktif: ${q} ${unit}</span>`;
  } else if (it.type === 'title' || it.type === 'frame') {
    const slot = it.type === 'title' ? 'equippedTitle' : 'equippedFrame';
    if (!cosmeticOwned(it.id)) {
      btnLabel = priceLabel; btnClass = 'btn-primary';
    } else if (state[slot] === it.id) {
      btnLabel = 'Kuşanıldı (Çıkar)'; btnClass = 'btn-secondary';
      status = '<span class="store-card-status owned">✓ Sahipsin</span>';
    } else {
      btnLabel = 'Kuşan'; btnClass = 'btn-secondary-outline';
      status = '<span class="store-card-status owned">✓ Sahipsin</span>';
    }
  }

  return `
    <div class="store-card${status.includes('owned') ? ' bought' : ''}">
      <span class="store-card-icon">${it.icon}</span>
      <h3>${esc(it.title)}</h3>
      <p>${esc(it.desc)}</p>
      ${status}
      <button class="btn ${btnClass} store-buy-btn" data-item="${it.id}"${disabled ? ' disabled' : ''}>${btnLabel}</button>
    </div>`;
}

function renderStore() {
  const container = document.querySelector('.store-container');
  if (!container) return;

  // Jeton bakiyesi
  const coinEl = document.getElementById('store-coin-count');
  if (coinEl) coinEl.textContent = coinBalance();

  // Kategori sekmeleri
  const tabsEl = document.getElementById('store-cat-tabs');
  if (tabsEl) {
    tabsEl.innerHTML = STORE_CATEGORIES.map(c =>
      `<button class="store-cat-tab${c.id === storeActiveCat ? ' active' : ''}" data-cat="${c.id}">${c.label}</button>`
    ).join('');
  }

  // Kart ızgarası
  const grid = document.getElementById('store-grid');
  if (grid) {
    grid.innerHTML = STORE_CATALOG
      .filter(it => it.cat === storeActiveCat)
      .map(storeCardHTML)
      .join('');
  }
}

function showGuestBlockModal() {
  const modal = document.getElementById('guest-block-modal');
  if (modal) {
    const titleEl = modal.querySelector('.grammar-modal-body p:first-of-type');
    const descEl = modal.querySelector('.grammar-modal-body p:last-of-type');
    const loginBtn = document.getElementById('guest-block-login-btn');
    const registerBtn = document.getElementById('guest-block-register-btn');
    const activateBtn = document.getElementById('guest-block-activate-btn');
    const licenceBtn = document.getElementById('guest-block-licence-btn');
    const loginRegisterRow = loginBtn ? loginBtn.parentElement : null;

    if (state.isGuest) {
      if (titleEl) titleEl.textContent = "Devam Etmek İçin Üye Ol ve Lisans Anahtarı Al!";
      if (descEl) descEl.textContent = "Misafir hesapları sadece ilk bölümü tamamlayabilir. İlerlemeyi kaydetmek, diğer bölümleri açmak ve liglerde yarışmak için ücretsiz üye olun!";
      if (loginBtn) loginBtn.style.display = 'block';
      if (registerBtn) registerBtn.style.display = 'block';
      if (activateBtn) activateBtn.style.display = 'none';
      if (licenceBtn) licenceBtn.style.display = 'none';
      if (loginRegisterRow) loginRegisterRow.style.display = 'flex';
    } else {
      if (titleEl) titleEl.textContent = "Premium Lisans Gerekli! 🔑";
      if (descEl) descEl.textContent = "Deneme sürümünüzün sonuna geldiniz (Maksimum 2 ders). Öğrenmeye devam etmek için lütfen geçerli bir lisans anahtarı etkinleştirin.";
      if (loginBtn) loginBtn.style.display = 'none';
      if (registerBtn) registerBtn.style.display = 'none';
      if (activateBtn) activateBtn.style.display = 'block';
      if (licenceBtn) licenceBtn.style.display = 'block';
      if (loginRegisterRow) loginRegisterRow.style.display = 'flex';
    }

    modal.classList.add('show');
  }
}

function startFormationTour(isRestore = false) {
  quizSessionId++;
  isFormationMode = true;

  if (typeof FORMATION_QUESTIONS !== 'undefined' && FORMATION_QUESTIONS) {
    sanitizeQuestions(FORMATION_QUESTIONS);
  }

  if (isRestore) {
    currentQuestionIndex = parseInt(localStorage.getItem('amok_active_question_index') || '0', 10);
    correctCount = parseInt(localStorage.getItem('amok_active_correct_count') || '0', 10);
    wrongCount = parseInt(localStorage.getItem('amok_active_wrong_count') || '0', 10);
  } else {
    currentQuestionIndex = 0;
    quizShuffleEpoch++;
    correctCount = 0;
    wrongCount = 0;
  }

  selectedAnswer = null;
  isAnswerChecked = false;
  matchState = null;

  saveActiveQuizState();

  updateQuizUI();
  showScreen('quiz-screen');
  renderQuestion();
}

// ============================================================
// EVENT LİSTENERLER
// ============================================================
function initEventListeners() {
  // Formasyon Turu Kartı Güncelleme
  function updateFormationTourCardUI() {
    const btn = document.getElementById('btn-tree-start-formation');
    if (btn) {
      if (state.formationTourCompleted) {
        btn.textContent = "Turu Tekrarla (Keşfet)";
        btn.className = "btn btn-secondary";
        btn.style.cssText = "padding: 12px 24px; font-size: 0.95rem; font-weight: 800; border-radius: var(--radius-md); cursor: pointer;";
      } else {
        btn.textContent = "Turu Başlat (Keşfet)";
        btn.className = "btn btn-primary";
        btn.style.cssText = "padding: 12px 24px; font-size: 0.95rem; font-weight: 800; background: linear-gradient(135deg, #a855f7 0%, #db2777 100%); border: none; border-radius: var(--radius-md); box-shadow: 0 4px 14px rgba(168, 85, 247, 0.4); cursor: pointer;";
      }
    }
  }
  window.updateFormationTourCardUI = updateFormationTourCardUI;
  updateFormationTourCardUI();

  // Misafir Engel Modali
  const guestBlockCloseBtn = document.getElementById('guest-block-close-btn');
  const guestBlockLoginBtn = document.getElementById('guest-block-login-btn');
  const guestBlockRegisterBtn = document.getElementById('guest-block-register-btn');

  const hideGuestBlockModal = () => {
    const modal = document.getElementById('guest-block-modal');
    if (modal) modal.classList.remove('show');
  };

  if (guestBlockCloseBtn) {
    guestBlockCloseBtn.addEventListener('click', hideGuestBlockModal);
  }

  if (guestBlockLoginBtn) {
    guestBlockLoginBtn.addEventListener('click', () => {
      hideGuestBlockModal();
      logout();
      const tabLogin = document.getElementById('tab-login');
      if (tabLogin) tabLogin.click();
    });
  }

  if (guestBlockRegisterBtn) {
    guestBlockRegisterBtn.addEventListener('click', () => {
      hideGuestBlockModal();
      logout();
      const tabRegister = document.getElementById('tab-register');
      if (tabRegister) tabRegister.click();
    });
  }

  const guestBlockActivateBtn = document.getElementById('guest-block-activate-btn');
  if (guestBlockActivateBtn) {
    guestBlockActivateBtn.addEventListener('click', () => {
      hideGuestBlockModal();
      switchTab('profile');
      setTimeout(() => {
        const statusBox = document.getElementById('profile-licence-status-box');
        if (statusBox) {
          statusBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
          const emailInput = document.getElementById('profile-licence-email');
          if (emailInput) emailInput.focus();
        }
      }, 300);
    });
  }

  const guestBlockLicenceBtn = document.getElementById('guest-block-licence-btn');
  const guestLicenceRequestModal = document.getElementById('guest-licence-request-modal');
  const guestLicenceRequestCloseBtn = document.getElementById('guest-licence-request-close-btn');
  const guestLicenceRequestForm = document.getElementById('guest-licence-request-form');

  if (guestBlockLicenceBtn && guestLicenceRequestModal) {
    guestBlockLicenceBtn.addEventListener('click', () => {
      if (state.isGuest) {
        showToast("Lisans talep edebilmek için lütfen önce üye olun veya giriş yapın!", "warning");
        hideGuestBlockModal();
        const tabRegister = document.getElementById('tab-register');
        if (tabRegister) tabRegister.click();
        return;
      }

      if (state.licenceKey === 'REQUESTED') {
        showToast("Lisans talebiniz zaten beklemede! 📩", "info");
        hideGuestBlockModal();
        return;
      }

      // Prefill fields if available in user state
      const nameInput = document.getElementById('req-name-surname');
      if (nameInput) nameInput.value = ''; // Let them write full Name & Surname
      
      const emailInput = document.getElementById('req-email');
      if (emailInput) emailInput.value = state.email || '';

      const phoneInput = document.getElementById('req-phone');
      if (phoneInput) phoneInput.value = state.phone || '';

      hideGuestBlockModal();
      guestLicenceRequestModal.classList.add('show');
    });
  }

  if (guestLicenceRequestModal) {
    if (guestLicenceRequestCloseBtn) {
      guestLicenceRequestCloseBtn.addEventListener('click', () => {
        guestLicenceRequestModal.classList.remove('show');
      });
    }
    const guestLicenceRequestCancelBtn = document.getElementById('guest-licence-request-cancel-btn');
    if (guestLicenceRequestCancelBtn) {
      guestLicenceRequestCancelBtn.addEventListener('click', () => {
        guestLicenceRequestModal.classList.remove('show');
      });
    }
  }

  if (guestLicenceRequestForm && guestLicenceRequestModal) {
    guestLicenceRequestForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      
      const adSoyad = document.getElementById('req-name-surname').value.trim();
      const emailVal = document.getElementById('req-email').value.trim();
      const phoneVal = document.getElementById('req-phone').value.trim();

      if (!adSoyad || !emailVal || !phoneVal) {
        showToast("Lütfen tüm alanları doldurun!", "warning");
        return;
      }

      try {
        state.licenceKey = 'REQUESTED';
        saveState();

        const localStates = JSON.parse(localStorage.getItem('amok_user_states') || '{}');
        if (localStates[state.username]) {
          localStates[state.username].licence_key = 'REQUESTED';
          localStorage.setItem('amok_user_states', JSON.stringify(localStates));
        }

        if (supabaseClient && state.username) {
          await supabaseClient
            .from('user_states')
            .update({ licence_key: 'REQUESTED' })
            .eq('username', state.username);
        }

        sendLicenceRequestEmail(state.username, adSoyad, emailVal, phoneVal);

        showToast("Lisans anahtarı talebiniz yöneticinize başarıyla iletildi! 📩", "success");
        guestLicenceRequestModal.classList.remove('show');
        updateProfileLicenceUI();
      } catch (err) {
        console.error('Request licence key error:', err);
        showToast("Talep iletilirken bir sorun oluştu.", "error");
      }
    });
  }

  // Profile Subnav Buttons
  document.querySelectorAll('.profile-subnav-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const section = btn.dataset.profileSection;
      switchProfileSubcontent(section);
    });
  });

  // Sağ Slide-over Paneli (Sosyal & Araçlar)
  window.openRightDrawer = function() {
    const drawer = document.getElementById('right-side-drawer');
    const backdrop = document.getElementById('drawer-backdrop');
    if (drawer) drawer.classList.add('active');
    if (backdrop) backdrop.classList.add('active');
  };

  window.closeRightDrawer = function() {
    const drawer = document.getElementById('right-side-drawer');
    const backdrop = document.getElementById('drawer-backdrop');
    if (drawer) drawer.classList.remove('active');
    if (backdrop) backdrop.classList.remove('active');
  };

  const btnToggleDrawer = document.getElementById('btn-toggle-social-drawer');
  if (btnToggleDrawer) {
    btnToggleDrawer.addEventListener('click', window.openRightDrawer);
  }

  const btnCloseDrawer = document.getElementById('btn-close-side-drawer');
  if (btnCloseDrawer) {
    btnCloseDrawer.addEventListener('click', window.closeRightDrawer);
  }

  const drawerBackdrop = document.getElementById('drawer-backdrop');
  if (drawerBackdrop) {
    drawerBackdrop.addEventListener('click', window.closeRightDrawer);
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      window.closeRightDrawer();
    }
  });

  // Tema
  document.getElementById('btn-theme').addEventListener('click', toggleTheme);

  // Kullanıcı menüsü / Profil Butonu (Sağ üst avatar)
  const userMenuBtn = document.getElementById('btn-user-menu');
  if (userMenuBtn) {
    userMenuBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      switchTab('profile');
    });
  }

  const btnGotoProfileDropdown = document.getElementById('btn-goto-profile-dropdown');
  if (btnGotoProfileDropdown) {
    btnGotoProfileDropdown.addEventListener('click', (e) => {
      e.stopPropagation();
      const userDropdown = document.getElementById('user-dropdown');
      if (userDropdown) userDropdown.classList.remove('open');
      switchTab('profile');
    });
  }

  document.addEventListener('click', (e) => {
    document.getElementById('user-dropdown').classList.remove('open');
    
    // Toggle active state for hoverable words on tap/click
    const hoverable = e.target.closest('.hoverable-word');
    if (hoverable && !hoverable.classList.contains('no-meaning')) {
      const wasActive = hoverable.classList.contains('active');
      document.querySelectorAll('.hoverable-word.active').forEach(w => w.classList.remove('active'));
      if (!wasActive) {
        hoverable.classList.add('active');
      }
      e.stopPropagation();
    } else {
      document.querySelectorAll('.hoverable-word.active').forEach(w => w.classList.remove('active'));
    }
  });

  // Çıkış
  document.getElementById('btn-logout').addEventListener('click', logout);

  // Giriş Yap butonu (Üst Bar)
  const loginTopbarBtn = document.getElementById('btn-login-topbar');
  if (loginTopbarBtn) {
    loginTopbarBtn.addEventListener('click', () => {
      showScreen('auth-screen');
    });
  }

  // Quiz kapatma
  document.getElementById('quiz-close').addEventListener('click', () => {
    if (confirm('Dersten çıkmak istediğine emin misin? İlerleme kaybedilecek.')) {
      const wasReview = isReviewMode;
      const wasDrill = activeDrillSession;
      isReviewMode = false;
      activeDrillSession = false;
      updateTopBar();
      renderLessonTree();
      // renderAchievements(); // BAŞARIMLAR DEVRE DIŞI
      showScreen('home-screen');
      if (wasDrill) {
        switchTab('connector-drill');
      } else if (wasReview) {
        switchTab('lessons');
      }
    }
  });

  // Soru Hata Bildirimi
  document.getElementById('quiz-report').addEventListener('click', () => {
    showReportModal();
  });
  // html2canvas (~200KB) artık önden yüklenmiyor; ekran görüntüsü isteğe bağlı
  // olduğu için betik yalnızca kullanıcı kutucuğu işaretlediğinde indiriliyor.

  // Kontrol Et / Devam Et butonu
  document.getElementById('btn-check').addEventListener('click', () => {
    if (isTranslationGateActive && onTranslationGateVerify) {
      onTranslationGateVerify();
    } else if (!isAnswerChecked) {
      const question = isReviewMode ? reviewQuestions[currentQuestionIndex] : currentQuizQuestions[currentQuestionIndex];
      const activeType = question ? ((question.type === 'fill-blank-dropdown' || question.type === 'fill-blank') ? question._dynamicType : question.type) : '';

      // Empty selection validation for word-bank questions
      if (activeType === 'word-bank' && (!selectedAnswer || selectedAnswer.length === 0)) {
        const sentenceContainer = document.getElementById('wb-sentence');
        const checkBtn = document.getElementById('btn-check');

        if (sentenceContainer) {
          sentenceContainer.classList.add('shake-anim');
          setTimeout(() => sentenceContainer.classList.remove('shake-anim'), 500);
        }
        if (checkBtn) {
          checkBtn.classList.add('shake-anim');
          setTimeout(() => checkBtn.classList.remove('shake-anim'), 500);
        }

        showToast('Lütfen kelimeleri sürükleyerek veya seçerek bir cevap oluşturun!', 'info');
        return;
      }

      const isTargetUnit = question && question.translation ? true : false;
      const isCorrectDropdown = activeType === 'fill-blank-dropdown' && selectedAnswer === question.correctIndex;

      if (isTargetUnit && isCorrectDropdown && question.translation) {
        startTranslationGate(document.getElementById('quiz-body'), question);
      } else {
        checkAnswer();
      }
    } else {
      nextQuestion();
    }
  });

  // Soruyu Atla butonu
  const btnSkip = document.getElementById('btn-skip');
  if (btnSkip) {
    btnSkip.addEventListener('click', () => {
      skipQuestion();
    });
  }

  // Özet ekranı devam
  document.getElementById('btn-summary-continue').addEventListener('click', () => {
    if (!isCurrentExercisePassed) {
      startLesson(currentLesson.id, currentLesson.activeExerciseId);
      return;
    }

    updateTopBar();
    renderLessonTree();
    // renderAchievements(); // BAŞARIMLAR DEVRE DIŞI
    showScreen('home-screen');

    // Check licence trial limit restriction
    if (!hasLicenseOrTrialAccess() && !checkIsLocal()) {
      showGuestBlockModal();
      return;
    }

    // Find the next target lesson to open
    let targetLessonId = null;
    if (currentLesson) {
      if (currentLesson.exercises && currentLesson.exercises.length > 0) {
        // Check if there are uncompleted exercises in the current lesson
        const hasUncompleted = currentLesson.exercises.some(ex => !state.completedLessons.includes(`${currentLesson.id}_${ex.id}`));
        if (hasUncompleted) {
          targetLessonId = currentLesson.id;
        }
      }
      if (!targetLessonId) {
        const sortedLessons = [];
        units.forEach(u => {
          u.lessons.forEach(lId => {
            sortedLessons.push(lId);
          });
        });
        const currentIdx = sortedLessons.indexOf(currentLesson.id);
        if (currentIdx !== -1 && currentIdx + 1 < sortedLessons.length) {
          const nextLessonId = sortedLessons[currentIdx + 1];
          if (isLessonUnlocked(nextLessonId)) {
            targetLessonId = nextLessonId;
          }
        }
      }
    }

    if (targetLessonId) {
      setTimeout(() => {
        ensureLessonRendered(targetLessonId);
        const targetLesson = lessons.find(l => l.id === targetLessonId);
        if (targetLesson) {
          const unitSection = document.querySelector(`.unit-section[data-unit-id="${targetLesson.unitId}"]`);
          if (unitSection) {
            unitSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
            setTimeout(() => {
              homeScreenScrollY = window.scrollY;
              localStorage.setItem('amok_last_scroll_y', window.scrollY);
            }, 600);
          }
        }
        const button = document.querySelector(`.lesson-node[data-lesson-id="${targetLessonId}"]`);
        if (button) {
          setTimeout(() => {
            button.click();
          }, 600);
        }
      }, 100);
    } else {
      setTimeout(() => {
        scrollToActiveUnit('smooth');
      }, 100);
    }
  });

  // Can Bitti ekranı butonları
  document.getElementById('btn-refill-hearts').addEventListener('click', () => {
    if (state.xp >= HEARTS_REFILL_COST) {
      state.xp -= HEARTS_REFILL_COST;
      state.hearts = MAX_HEARTS;
      state.warriorTriggered = true;
      saveState();
      // checkAchievements(); // BAŞARIMLAR DEVRE DIŞI
      updateTopBar();
      showToast('Canlar dolduruldu! ❤️', 'success');

      // Derse geri dön
      if (currentLesson) {
        updateQuizUI();
        showScreen('quiz-screen');
        renderQuestion();
      } else {
        renderLessonTree();
        // renderAchievements(); // BAŞARIMLAR DEVRE DIŞI
        showScreen('home-screen');
      }
    } else {
      showToast('Yeterli puan yok!', 'error');
    }
  });

  document.getElementById('btn-restart-lesson').addEventListener('click', () => {
    state.hearts = MAX_HEARTS;
    saveState();
    updateTopBar();
    if (currentLesson) {
      startLesson(currentLesson.id, currentLesson.activeExerciseId);
    }
  });

  document.getElementById('btn-go-home').addEventListener('click', () => {
    state.hearts = MAX_HEARTS;
    saveState();
    updateTopBar();
    renderLessonTree();
    // renderAchievements(); // BAŞARIMLAR DEVRE DIŞI
    showScreen('home-screen');
  });

  // Sekmeler (Nav Tabs)
  document.querySelectorAll('.nav-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.tab) {
        switchTab(btn.dataset.tab);
      }
    });
  });

  // Marka logosu: tıklanınca ana sayfaya (Dersler sekmesi) dön.
  const brandHome = document.getElementById('sidebar-brand-home');
  if (brandHome) {
    const goHomeFromBrand = () => {
      const inQuiz = document.getElementById('quiz-screen')?.classList.contains('active');
      if (inQuiz && !confirm('Dersten çıkmak istediğine emin misin? İlerleme kaybedilecek.')) return;
      isReviewMode = false;
      activeDrillSession = false;
      switchTab('lessons');
      updateTopBar();
      renderLessonTree();
      showScreen('home-screen');
    };
    brandHome.addEventListener('click', goHomeFromBrand);
    brandHome.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); goHomeFromBrand(); }
    });
  }

  // Profil Hub Alt Sekmeleri (Profilim / Puan Tablosu / Mağaza)
  document.querySelectorAll('.profile-hub-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.hub) {
        switchProfileHub(btn.dataset.hub);
      }
    });
  });

  // Dev Tool: Boş Ders Bul
  const devTabBtn = document.getElementById('btn-next-empty-lesson');
  if (devTabBtn) {
    devTabBtn.addEventListener('click', () => {
      navigateToNextEmptyLesson();
    });
  }

  // Mağaza: kategori sekmeleri ve satın alma (olay delegasyonu — katalog dinamik)
  const storeContainer = document.querySelector('.store-container');
  if (storeContainer) {
    storeContainer.addEventListener('click', (e) => {
      const catTab = e.target.closest('.store-cat-tab');
      if (catTab && catTab.dataset.cat) {
        storeActiveCat = catTab.dataset.cat;
        renderStore();
        return;
      }
      const buyBtn = e.target.closest('.store-buy-btn');
      if (buyBtn && buyBtn.dataset.item && !buyBtn.disabled) {
        buyStoreItem(buyBtn.dataset.item);
      }
    });
  }

  // Collapsible Üyelik & Lisans Kartı
  const licenceHeader = document.getElementById('store-licence-header');
  const licenceBody = document.getElementById('store-licence-body');
  const licenceArrow = document.getElementById('store-licence-arrow');
  
  if (licenceHeader && licenceBody) {
    licenceHeader.addEventListener('click', () => {
      const isExpanded = licenceBody.style.maxHeight && licenceBody.style.maxHeight !== '0px';
      if (isExpanded) {
        licenceBody.style.maxHeight = '0px';
        licenceBody.style.opacity = '0';
        licenceBody.style.borderTopColor = 'transparent';
        if (licenceArrow) licenceArrow.style.transform = 'rotate(0deg)';
      } else {
        licenceBody.style.maxHeight = '800px';
        licenceBody.style.opacity = '1';
        licenceBody.style.borderTopColor = 'var(--border-color)';
        if (licenceArrow) licenceArrow.style.transform = 'rotate(180deg)';
      }
    });
  }

  // Mağaza Lisans Butonları ve Girişleri
  const storeLicenceInput = document.getElementById('store-licence-input');
  const storeActivateBtn = document.getElementById('btn-store-activate-licence');
  const storeRequestBtn = document.getElementById('btn-store-request-licence');
  const storeEmail = document.getElementById('store-licence-email');
  const storePhone = document.getElementById('store-licence-phone');

  if (storeEmail) {
    storeEmail.addEventListener('input', (e) => {
      state.email = e.target.value.trim();
      const profileEmail = document.getElementById('profile-licence-email');
      if (profileEmail) profileEmail.value = state.email;
    });
  }
  if (storePhone) {
    storePhone.addEventListener('input', (e) => {
      state.phone = e.target.value.trim();
      const profilePhone = document.getElementById('profile-licence-phone');
      if (profilePhone) profilePhone.value = state.phone;
    });
  }
  if (storeActivateBtn && storeLicenceInput) {
    storeActivateBtn.addEventListener('click', async () => {
      await activateLicence(storeLicenceInput.value.trim());
    });
  }
  if (storeRequestBtn) {
    storeRequestBtn.addEventListener('click', async () => {
      await requestLicence();
    });
  }

  // Home Screen Scroll tracking
  window.addEventListener('scroll', () => {
    const activeScreen = document.querySelector('.app-screen.active');
    if (activeScreen && activeScreen.id === 'home-screen') {
      localStorage.setItem('amok_last_scroll_y', window.scrollY);
    }
  });

  // Seviye Belirleme Sınavı
  const startPlacementBtn = document.getElementById('btn-start-placement');
  if (startPlacementBtn) {
    startPlacementBtn.addEventListener('click', () => {
      if (!hasLicenseOrTrialAccess() && !checkIsLocal()) {
        showGuestBlockModal();
        return;
      }
      startPlacementTest();
    });
  }

  const placementCloseBtn = document.getElementById('placement-close');
  if (placementCloseBtn) {
    placementCloseBtn.addEventListener('click', () => {
      if (confirm('Sınavdan çıkmak istediğinize emin misiniz? Seviyeniz kaydedilmeyecek.')) {
        isPlacementMode = false;
        showScreen('home-screen');
      }
    });
  }

  const btnPlacementCheck = document.getElementById('btn-placement-check');
  if (btnPlacementCheck) {
    btnPlacementCheck.addEventListener('click', () => {
      if (!isPlacementAnswerChecked) {
        checkPlacementAnswer();
      } else {
        nextPlacementQuestion();
      }
    });
  }

  const btnPlacementSkip = document.getElementById('btn-placement-skip');
  if (btnPlacementSkip) {
    btnPlacementSkip.addEventListener('click', () => {
      skipPlacementQuestion();
    });
  }

  // Hızlı Tekrar
  const startReviewBtn = document.getElementById('btn-start-review');
  if (startReviewBtn) {
    startReviewBtn.addEventListener('click', () => {
      if (!hasLicenseOrTrialAccess() && !checkIsLocal()) {
        showGuestBlockModal();
        return;
      }
      startReviewMode();
    });
  }

  // Akıllı Tekrar Davet Modali Event Listeners
  const reviewPromptCloseBtn = document.getElementById('review-prompt-close-btn');
  const reviewPromptCancelBtn = document.getElementById('review-prompt-cancel-btn');
  const reviewPromptConfirmBtn = document.getElementById('review-prompt-confirm-btn');

  const hideReviewPromptModal = () => {
    const modal = document.getElementById('review-prompt-modal');
    if (modal) modal.classList.remove('show');
  };

  if (reviewPromptCloseBtn) {
    reviewPromptCloseBtn.addEventListener('click', () => {
      state.lastPromptedWrongCount = state.wrongQuestions ? state.wrongQuestions.length : 0;
      saveState();
      hideReviewPromptModal();
    });
  }

  if (reviewPromptCancelBtn) {
    reviewPromptCancelBtn.addEventListener('click', () => {
      state.lastPromptedWrongCount = state.wrongQuestions ? state.wrongQuestions.length : 0;
      saveState();
      hideReviewPromptModal();
    });
  }

  if (reviewPromptConfirmBtn) {
    reviewPromptConfirmBtn.addEventListener('click', () => {
      hideReviewPromptModal();
      if (!hasLicenseOrTrialAccess() && !checkIsLocal()) {
        showGuestBlockModal();
        return;
      }
      startReviewMode();
    });
  }

  // Klavye Kısayolları (Quiz ve Placement ekranları için)
  document.addEventListener('keydown', (e) => {
    // Eğer dilbilgisi modalı açıksa, Enter kapatma tuşunu (Anladım) tetiklesin
    const grammarModal = document.getElementById('grammar-modal');
    if (grammarModal && grammarModal.classList.contains('show')) {
      if (e.key === 'Enter') {
        const okBtn = document.getElementById('grammar-modal-ok-btn');
        if (okBtn) {
          e.preventDefault();
          okBtn.click();
        }
        return;
      }
    }

    // Eğer kullanıcı bir metin kutusuna veya alana yazıyorsa kısayolları engelle
    if (document.activeElement && (document.activeElement.tagName === 'INPUT' || document.activeElement.tagName === 'TEXTAREA')) {
      if (['1', '2', '3', '4'].includes(e.key)) {
        return; // Sayı yazmasına izin ver
      }
      if (e.key === 'Enter') {
        // Textarea içinde Enter satır atlamalı, input veya translation-text-area içindeyse kontrol butonu tıklanabilir
        if (document.activeElement.tagName === 'INPUT' || document.activeElement.id === 'translation-text-area') {
          e.preventDefault();
          const quizScreen = document.getElementById('quiz-screen');
          const placementScreen = document.getElementById('placement-screen');
          let checkBtn = null;
          if (quizScreen && quizScreen.classList.contains('active')) {
            checkBtn = document.getElementById('btn-check');
          } else if (placementScreen && placementScreen.classList.contains('active')) {
            checkBtn = document.getElementById('btn-placement-check');
          }
          if (checkBtn && !checkBtn.disabled) {
            checkBtn.click();
          }
        }
        return;
      }
    }

    const quizScreen = document.getElementById('quiz-screen');
    const placementScreen = document.getElementById('placement-screen');
    const summaryScreen = document.getElementById('summary-screen');

    if (quizScreen && quizScreen.classList.contains('active')) {
      // 1, 2, 3, 4 seçimi
      if (['1', '2', '3', '4'].includes(e.key)) {
        const idx = parseInt(e.key) - 1;
        // MC options
        const mcOpts = quizScreen.querySelectorAll('.mc-option');
        if (mcOpts.length > idx) {
          mcOpts[idx].click();
          return;
        }
        // Fill blank options
        const fbOpts = quizScreen.querySelectorAll('.fb-option');
        if (fbOpts.length > idx) {
          fbOpts[idx].click();
          return;
        }
      }
      // Enter: Kontrol Et / Devam Et
      if (e.key === 'Enter') {
        const checkBtn = document.getElementById('btn-check');
        if (checkBtn && !checkBtn.disabled) {
          checkBtn.click();
          e.preventDefault();
        }
      }
    } else if (placementScreen && placementScreen.classList.contains('active')) {
      if (['1', '2', '3', '4'].includes(e.key)) {
        const idx = parseInt(e.key) - 1;
        const mcOpts = placementScreen.querySelectorAll('.mc-option');
        if (mcOpts.length > idx) {
          mcOpts[idx].click();
          return;
        }
        const fbOpts = placementScreen.querySelectorAll('.fb-option');
        if (fbOpts.length > idx) {
          fbOpts[idx].click();
          return;
        }
      }
      if (e.key === 'Enter') {
        const checkBtn = document.getElementById('btn-placement-check');
        if (checkBtn && !checkBtn.disabled) {
          checkBtn.click();
          e.preventDefault();
        }
      }
    } else if (summaryScreen && summaryScreen.classList.contains('active')) {
      if (e.key === 'Enter') {
        const summaryContinue = document.getElementById('btn-summary-continue');
        if (summaryContinue) {
          summaryContinue.click();
          e.preventDefault();
        }
      }
    }
  });

  // Son Düzenlemeler Kutusu (Recent Changes Box) Tıklama Dinleyicisi
  const recentChangesBox = document.getElementById('recent-changes-box');
  if (recentChangesBox) {
    recentChangesBox.addEventListener('click', (e) => {
      const item = e.target.closest('.recent-change-item');
      if (!item) return;

      const action = item.dataset.action;
      const target = item.dataset.target;

      if (action === 'lesson') {
        const lessonId = isNaN(target) ? target : parseInt(target, 10);
        switchTab('lessons');
        
        setTimeout(() => {
          ensureLessonRendered(lessonId);
          const btn = document.querySelector(`.lesson-node[data-lesson-id="${lessonId}"]`);
          if (btn) {
            btn.scrollIntoView({ behavior: 'smooth', block: 'center' });
            btn.classList.add('navigation-highlight');
            setTimeout(() => {
              btn.click();
            }, 600);
            setTimeout(() => {
              btn.classList.remove('navigation-highlight');
            }, 2500);
            showToast(`Derse gidildi: ${lessonId}. Ders`, "success");
          } else {
            showToast(`Ders bulunamadı: ${lessonId}. Ders`, "error");
          }
        }, 150);
      } else if (action === 'element') {
        if (target === '#btn-admin') {
          switchTab('admin');
          const adminBtn = document.getElementById('btn-admin');
          if (adminBtn) {
            adminBtn.classList.add('navigation-highlight');
            setTimeout(() => {
              adminBtn.classList.remove('navigation-highlight');
            }, 2000);
          }
          showToast(`Admin Sekmesi Açıldı`, "success");
        } else if (target === '#placement-banner') {
          switchTab('lessons');
          setTimeout(() => {
            const banner = document.querySelector('#placement-banner');
            if (banner) {
              banner.scrollIntoView({ behavior: 'smooth', block: 'center' });
              banner.classList.add('navigation-highlight');
              setTimeout(() => {
                banner.classList.remove('navigation-highlight');
              }, 2500);
              showToast(`Seviye Sınavı Kutusuna Gidildi`, "success");
            } else {
              showToast(`Sınav Kutusu Bulunamadı! (Seviyeniz zaten belirlenmiş olabilir)`, "info");
            }
          }, 150);
        }
      }
    });
  }

  // Scroll tab theme listener with requestAnimationFrame throttling and theme change optimization
  let updateThemeTimeout = null;
  let lastActiveUnitThemeId = null;

  const updateThemeOnScroll = () => {
    if (updateThemeTimeout) return;

    updateThemeTimeout = requestAnimationFrame(() => {
      updateThemeTimeout = null;

      const homeScreen = document.getElementById('home-screen');
      const tabLessons = document.getElementById('tab-content-lessons');
      if (!homeScreen || !homeScreen.classList.contains('active') || !tabLessons || !tabLessons.classList.contains('active')) {
        return;
      }

      const sections = document.querySelectorAll('.unit-section');
      let activeUnitId = null;
      const threshold = 82;

      for (let i = 0; i < sections.length; i++) {
        const section = sections[i];
        const rect = section.getBoundingClientRect();
        if (rect.top <= threshold && rect.bottom > threshold) {
          activeUnitId = parseInt(section.dataset.unitId, 10);
          break;
        }
      }

      let targetUnitId = null;
      if (activeUnitId !== null && !isNaN(activeUnitId)) {
        targetUnitId = activeUnitId;
      } else if (sections.length > 0) {
        const firstRect = sections[0].getBoundingClientRect();
        if (firstRect.top > threshold) {
          targetUnitId = parseInt(sections[0].dataset.unitId, 10);
        }
      }

      if (targetUnitId !== null && targetUnitId !== lastActiveUnitThemeId) {
        lastActiveUnitThemeId = targetUnitId;
        setUnitTheme(targetUnitId);
      }
    });
  };

  window.addEventListener('scroll', updateThemeOnScroll);
  
  // Trigger on initial loads and tab transitions
  document.querySelectorAll('.sidebar-menu .nav-tab, .nav-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      setTimeout(updateThemeOnScroll, 50);
    });
  });
}

// ============================================================
// SEVİYE BELİRLEME SINAVI (PLACEMENT TEST)
// ============================================================
let placementCorrectCount = 0;
let placementCurrentIndex = 0;
let placementSelectedAnswer = null;
let isPlacementAnswerChecked = false;

function checkPlacementBanner() {
  const banner = document.getElementById('placement-banner');
  if (banner) {
    if (!state.placementTaken) {
      banner.style.display = 'flex';
    } else {
      banner.style.display = 'none';
    }
  }
}

function startPlacementTest() {
  quizSessionId++;
  isPlacementMode = true;
  placementCorrectCount = 0;
  placementCurrentIndex = 0;
  placementSelectedAnswer = null;
  isPlacementAnswerChecked = false;

  if (typeof placementQuestions !== 'undefined' && placementQuestions) {
    sanitizeQuestions(placementQuestions);
  }
  placementQuestionsList = placementQuestions;

  showScreen('placement-screen');
  renderPlacementQuestion();
}

function renderPlacementQuestion() {
  const question = placementQuestionsList[placementCurrentIndex];
  if (!question) return;

  // Dynamically assign render type for blank questions
  if (question.type === 'fill-blank-dropdown' || question.type === 'fill-blank') {
    if (question._dynamicSessionId !== quizSessionId) {
      question._dynamicSessionId = quizSessionId;
      question._dynamicType = Math.random() < 0.5 ? 'fill-blank-dropdown' : 'fill-blank';
    }
  }

  placementSelectedAnswer = null;
  isPlacementAnswerChecked = false;

  const body = document.getElementById('placement-body');
  const btnCheck = document.getElementById('btn-placement-check');
  const feedbackPanel = document.getElementById('placement-feedback-panel');

  const btnPlacementSkip = document.getElementById('btn-placement-skip');
  if (btnPlacementSkip) {
    btnPlacementSkip.style.display = 'inline-flex';
  }

  feedbackPanel.classList.remove('show', 'correct', 'wrong');
  btnCheck.disabled = true;
  btnCheck.textContent = 'KONTROL ET';

  // İlerleme çubuğu
  const total = placementQuestionsList.length;
  const progress = (placementCurrentIndex / total) * 100;
  document.getElementById('placement-progress').style.width = `${progress}%`;

  const activeType = (question.type === 'fill-blank-dropdown' || question.type === 'fill-blank')
    ? question._dynamicType
    : question.type;

  // Adjust prompt text to fit the visual type
  const originalPrompt = question.prompt;
  question.prompt = translatePromptToTurkish(question.prompt, question);
  if (activeType === 'fill-blank-dropdown' && question.prompt === 'Boşluğu doldur') {
    question.prompt = 'Boşluğa gelecek en uygun kelimeyi seçin:';
  } else if (activeType === 'fill-blank' && question.prompt.startsWith('Boşluğa gelecek en uygun kelimeyi seçin')) {
    question.prompt = 'Boşluğu doldur';
  }

  switch (activeType) {
    case 'multiple-choice':
    case 'error-spotting':
    case 'context-clue':
    case 'chain-expansion-differential':
    case 'structural-deconstruction':
    case 'vector-velocity-shift':
    case 'titan-boundary-defense':
    case 'vagon-to-suffix-match':
    case 'reverse-engineering-translation':
    case 'suffix-decapitation':
      renderPlacementMultipleChoice(body, question);
      break;
    case 'fill-blank-dropdown':
      renderPlacementFillBlankDropdown(body, question);
      break;
    case 'fill-blank':
      renderPlacementFillBlank(body, question);
      break;
    case 'fill-blank-text':
      renderPlacementFillBlankText(body, question);
      break;
  }

  // Restore prompt text so data remains unmodified
  question.prompt = originalPrompt;
}

function renderPlacementMultipleChoice(container, question) {
  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <div class="mc-options">
      ${question.options.map((opt, i) => `
        <button class="mc-option" data-index="${i}">${opt}</button>
      `).join('')}
    </div>
  `;
  container.querySelectorAll('.mc-option').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isPlacementAnswerChecked) return;
      container.querySelectorAll('.mc-option').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      placementSelectedAnswer = parseInt(btn.dataset.index);
      document.getElementById('btn-placement-check').disabled = false;
    });
  });
}

function renderPlacementFillBlankDropdown(container, question) {
  const sentence = question.sentence || question.prompt || '';
  const parts = sentence.split(/_{3,}/);
  const selectOptions = `<option value="" disabled selected>Seçin...</option>` +
    question.options.map((opt, i) => {
      const meaning = getOptionMeaning(question, opt);
      const label = meaning ? `${opt} / ${meaning}` : opt;
      return `<option value="${i}">${label}</option>`;
    }).join('');

  let displayPrompt = question.sentence ? question.prompt : 'Boşluğa gelecek en uygun kelimeyi seçin:';
  if (displayPrompt === 'Boşluğu doldur') {
    displayPrompt = 'Boşluğu doldur!';
  }

  container.innerHTML = `
    <p class="quiz-prompt">${displayPrompt}</p>
    <div style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary);">
      ${parts[0]}<select class="inline-dropdown" id="fb-placement-dropdown-select">${selectOptions}</select>${parts[1] || ''}
    </div>
  `;

  const selectEl = document.getElementById('fb-placement-dropdown-select');
  selectEl.addEventListener('change', () => {
    if (isPlacementAnswerChecked) return;
    placementSelectedAnswer = parseInt(selectEl.value);
    document.getElementById('btn-placement-check').disabled = isNaN(placementSelectedAnswer);
  });
}

function renderPlacementFillBlankText(container, question) {
  const parts = question.sentence.split(/_{3,}/);

  container.innerHTML = `
    <p class="quiz-prompt">${question.prompt}</p>
    <div style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary);">
      ${parts[0]}<input type="text" class="inline-text-input" id="fb-placement-text-input" autocomplete="off" placeholder="yazın">${parts[1] || ''}
    </div>
  `;

  const inputEl = document.getElementById('fb-placement-text-input');
  setTimeout(() => inputEl.focus(), 100);

  inputEl.addEventListener('input', () => {
    if (isPlacementAnswerChecked) return;
    placementSelectedAnswer = inputEl.value.trim();
    document.getElementById('btn-placement-check').disabled = placementSelectedAnswer.length === 0;
  });
}

function renderPlacementFillBlank(container, question) {
  const sentence = question.sentence || question.prompt || '';
  const parts = sentence.split(/_{3,}/);
  const part0Html = parts[0];
  const part1Html = parts[1] || '';

  const optionsHtml = question.options.map((opt, i) => {
    return `<button class="fb-option" data-index="${i}">
      <span class="fb-number">${i + 1}</span>
      <span class="fb-text">${opt}</span>
    </button>`;
  }).join('');

  let displayPrompt = question.sentence ? question.prompt : 'Boşluğu doldur';
  if (displayPrompt === 'Boşluğu doldur') {
    displayPrompt = 'Boşluğu doldur!';
  }

  container.innerHTML = `
    <p class="quiz-prompt">${displayPrompt}</p>
    <div class="fb-sentence" style="font-size: 1.25rem; font-weight: 500; text-align: center; margin: 24px 0; color: var(--text-primary); line-height: 1.6;">
      ${part0Html}<span class="fb-blank" id="fb-placement-blank-word">______</span>${part1Html}
    </div>
    <div class="fb-options">
      ${optionsHtml}
    </div>
  `;

  const blankEl = document.getElementById('fb-placement-blank-word');
  
  container.querySelectorAll('.fb-option').forEach(btn => {
    btn.addEventListener('click', () => {
      if (isPlacementAnswerChecked) return;
      container.querySelectorAll('.fb-option').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      
      const idx = parseInt(btn.dataset.index);
      placementSelectedAnswer = idx;
      
      blankEl.innerHTML = question.options[idx];
      
      document.getElementById('btn-placement-check').disabled = false;
    });
  });
}

function checkPlacementAnswer() {
  const question = placementQuestionsList[placementCurrentIndex];
  isPlacementAnswerChecked = true;

  const body = document.getElementById('placement-body');
  const activeType = (question.type === 'fill-blank-dropdown' || question.type === 'fill-blank')
    ? question._dynamicType
    : question.type;

  let isCorrect = false;
  if (activeType === 'multiple-choice' || activeType === 'error-spotting' || activeType === 'context-clue' || activeType === 'fill-blank-dropdown' || activeType === 'fill-blank') {
    isCorrect = placementSelectedAnswer === question.correctIndex;
    if (activeType === 'fill-blank') {
      const options = body.querySelectorAll('.fb-option');
      options.forEach(btn => {
        const idx = parseInt(btn.dataset.index);
        if (idx === question.correctIndex) {
          btn.classList.add('correct');
          btn.style.borderColor = 'var(--color-correct)';
          btn.style.background = 'var(--color-correct-bg)';
          btn.style.color = 'var(--color-correct)';
        } else if (idx === placementSelectedAnswer && idx !== question.correctIndex) {
          btn.classList.add('wrong');
          btn.style.borderColor = 'var(--color-wrong)';
          btn.style.background = 'var(--color-wrong-bg)';
          btn.style.color = 'var(--color-wrong)';
        }
      });
    }
  } else if (activeType === 'fill-blank-text') {
    const userVal = (placementSelectedAnswer || "").toLowerCase().trim();
    const correctVal = (question.correct || question.correctAnswer || "").toLowerCase().trim();
    isCorrect = userVal === correctVal;
  }

  const panel = document.getElementById('placement-feedback-panel');
  const icon = document.getElementById('placement-feedback-icon');
  const text = document.getElementById('placement-feedback-text');

  panel.classList.add('show');
  playFeedbackSound(isCorrect);
  if (isCorrect) {
    panel.classList.add('correct');
    panel.classList.remove('wrong');
    icon.textContent = '✓';
    text.textContent = 'Doğru! Tebrikler.';
    placementCorrectCount++;

    // Sorular doğru cevaplandığında sayfanın sağında ve solunda küçük havai fişek patlamaları oluşsun
    if (typeof confetti === 'function') {
      confetti({
        particleCount: 65,
        spread: 360,
        startVelocity: 35,
        origin: { x: 0.2, y: 0.4 },
        scalar: 1.2
      });
      confetti({
        particleCount: 65,
        spread: 360,
        startVelocity: 35,
        origin: { x: 0.8, y: 0.4 },
        scalar: 1.2
      });
    }
  } else {
    panel.classList.add('wrong');
    panel.classList.remove('correct');
    icon.textContent = '✗';
    let correctText = '';
    if (question.type === 'multiple-choice' || question.type === 'error-spotting' || question.type === 'context-clue' || question.type === 'fill-blank-dropdown' || question.type === 'fill-blank') {
      correctText = question.options[question.correctIndex];
    } else if (question.type === 'fill-blank-text') {
      correctText = question.correct || question.correctAnswer;
    }
    text.textContent = `Yanlış. Doğru cevap: "${correctText}"`;
  }

  const btnCheck = document.getElementById('btn-placement-check');
  btnCheck.textContent = 'DEVAM ET';

  const btnPlacementSkip = document.getElementById('btn-placement-skip');
  if (btnPlacementSkip) {
    btnPlacementSkip.style.display = 'none';
  }

  if (isCorrect) {
    autoAdvanceTimeout = setTimeout(() => {
      nextPlacementQuestion();
    }, 1200);
  }
}

function skipPlacementQuestion() {
  if (autoAdvanceTimeout) {
    clearTimeout(autoAdvanceTimeout);
    autoAdvanceTimeout = null;
  }
  placementCurrentIndex++;
  if (placementCurrentIndex >= placementQuestionsList.length) {
    completePlacementTest();
  } else {
    renderPlacementQuestion();
  }
}

function nextPlacementQuestion() {
  if (autoAdvanceTimeout) {
    clearTimeout(autoAdvanceTimeout);
    autoAdvanceTimeout = null;
  }
  placementCurrentIndex++;
  if (placementCurrentIndex >= placementQuestionsList.length) {
    completePlacementTest();
  } else {
    renderPlacementQuestion();
  }
}

function completePlacementTest() {
  state.placementTaken = true;

  let feedbackMsg = '';
  if (placementCorrectCount <= 2) {
    feedbackMsg = `Seviye Sınavı Tamamlandı! ${placementCorrectCount}/5 doğru yaptın. 1. Bölümden (Temel Seviye) başlaman uygun görüldü.`;
  } else if (placementCorrectCount <= 4) {
    // Unlock Unit 1 lessons (1 to 8)
    state.completedLessons = [1, 2, 3, 4, 5, 6, 7, 8];
    feedbackMsg = `Tebrikler! ${placementCorrectCount}/5 doğru yaptın. 1. Bölümü başarıyla atladın! Doğrudan 2. Bölümden başlayabilirsin.`;
  } else {
    // Unlock all lessons
    state.completedLessons = lessons.map(l => l.id);
    feedbackMsg = `Mükemmel! 5/5 doğru yaptın. Tüm seviyelerin kilidi açıldı, dilediğin konudan başlayabilirsin!`;
  }

  saveState();
  playCompletionSound(true);
  isPlacementMode = false;

  showToast('Seviyeniz başarıyla belirlendi!', 'success');
  alert(feedbackMsg);
  enterApp();
}

function showReportModal() {
  const question = isReviewMode ? reviewQuestions[currentQuestionIndex] : currentQuizQuestions[currentQuestionIndex];
  if (!question) {
    showToast('Aktif bir soru bulunamadı.', 'error');
    return;
  }
  
  const modal = document.createElement('div');
  modal.className = 'custom-modal-overlay';
  modal.id = 'report-modal';
  
  const questionText = question.prompt || question.sentence || 'Görsel / Eşleştirme';
  
  modal.innerHTML = `
    <div class="custom-modal">
      <div class="custom-modal-header">
        <h3>⚠️ Soru Hatası Bildir</h3>
        <button class="modal-close-btn" id="btn-close-report-modal">&times;</button>
      </div>
      <div class="custom-modal-body">
        <div class="report-question-info">
          <div class="info-row">
            <strong>Soru Metni:</strong>
            <span>${escapeHtml(questionText)}</span>
          </div>
          <div class="info-row">
            <strong>Soru ID:</strong>
            <span>${escapeHtml(question.id)}</span>
          </div>
        </div>
        
        <div class="form-group">
          <label for="report-error-type">Hata Türü</label>
          <select id="report-error-type" class="report-select">
            <option value="translation">Çeviri Hatası</option>
            <option value="typo">Yazım / İmla Hatası</option>
            <option value="answer">Cevap Anahtarı Hatası</option>
            <option value="technical">Teknik Sorun</option>
            <option value="other">Diğer</option>
          </select>
        </div>
        
        <div class="form-group" style="margin-top: 15px;">
          <label for="report-comment">Açıklamanız (Muhtemel düzeltme vb.)</label>
          <textarea id="report-comment" placeholder="Lütfen hatayı detaylandırın..." class="report-textarea"></textarea>
        </div>

        <div class="form-group" style="margin-top: 15px;">
          <label style="display: flex; align-items: center; gap: 8px; cursor: pointer; font-weight: 600;">
            <input type="checkbox" id="report-include-screenshot" style="margin: 0; cursor: pointer;" />
            📷 Sayfanın ekran görüntüsünü ekle (isteğe bağlı)
          </label>
          <div id="report-screenshot-preview" style="margin-top: 8px; border: 1px solid var(--border-color); border-radius: var(--radius-md); overflow: hidden; max-height: 160px; background: var(--bg-card); display: none; align-items: center; justify-content: center; font-size: 0.78rem; color: var(--text-muted); min-height: 60px;">
            Kutucuğu işaretleyin; ekran görüntüsü o an alınır.
          </div>
        </div>
      </div>
      <div class="custom-modal-footer">
        <button class="btn btn-secondary" id="btn-cancel-report">İptal</button>
        <button class="btn btn-primary" id="btn-submit-report">Bildirimi Gönder</button>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  // Ekran görüntüsünü modal açılır açılmaz arka planda al. Modal, #quiz-screen'in
  // kardeşi olduğu için yakalamaya dahil olmaz.
  //
  // html2canvas hem ilk sefer ~200KB betik indirir hem de DOM'u tararken ana
  // iş parçacığını saniyelerce bloklar. Bunu doğrudan çağırırsak tarayıcı modalı
  // boyamadan donuyor ("bildirim sayfası 5-6 sn geç açılıyor"). İki kare
  // bekleyip modalın boyanmasını garanti ettikten sonra yakalamayı başlat.
  // Ekran görüntüsü artık yalnızca kullanıcı kutucuğu işaretlerse alınır.
  // Mobilde html2canvas ana iş parçacığını saniyelerce bloklayıp bildirimi
  // yavaşlattığı için otomatik yakalama kaldırıldı.
  let capturedScreenshot = null;
  let captureInFlight = null;
  const previewEl = document.getElementById('report-screenshot-preview');
  const chkEl = document.getElementById('report-include-screenshot');
  const runCapture = () => {
    if (capturedScreenshot || captureInFlight) return captureInFlight || Promise.resolve();
    if (previewEl) { previewEl.style.display = 'flex'; previewEl.textContent = 'Ekran görüntüsü hazırlanıyor…'; }
    captureInFlight = capturePageScreenshot(document.getElementById('quiz-screen'))
      .then(dataUrl => {
        capturedScreenshot = dataUrl;
        if (previewEl) {
          previewEl.innerHTML = `<img src="${dataUrl}" style="max-width: 100%; max-height: 160px; object-fit: contain; display: block;" />`;
        }
      })
      .catch(err => {
        console.error('Rapor ekran görüntüsü alınamadı:', err);
        if (previewEl) previewEl.textContent = 'Ekran görüntüsü alınamadı (bildirim yine de gönderilebilir).';
        if (chkEl) { chkEl.checked = false; }
      })
      .finally(() => { captureInFlight = null; });
    return captureInFlight;
  };
  if (chkEl) {
    chkEl.addEventListener('change', () => {
      if (chkEl.checked) {
        runCapture();
      } else if (previewEl) {
        previewEl.style.display = 'none';
      }
    });
  }

  document.getElementById('btn-close-report-modal').addEventListener('click', () => modal.remove());
  document.getElementById('btn-cancel-report').addEventListener('click', () => modal.remove());
  document.getElementById('btn-submit-report').addEventListener('click', async () => {
    const errorType = document.getElementById('report-error-type').value;
    const comment = document.getElementById('report-comment').value.trim();

    if (!comment) {
      showToast('Lütfen bir açıklama yazın.', 'error');
      return;
    }

    // Kullanıcı ekran görüntüsü istediyse ama yakalama henüz bitmediyse bekle.
    if (chkEl && chkEl.checked && !capturedScreenshot && captureInFlight) {
      await captureInFlight;
    }
    const screenshot = (chkEl && chkEl.checked) ? capturedScreenshot : null;
    submitReport(question, errorType, comment, screenshot);
    modal.remove();
  });
}

function getLessonQuestions(l) {
  let list = [];
  if (l.questions && Array.isArray(l.questions)) {
    list = list.concat(l.questions);
  }
  if (l.exercises && Array.isArray(l.exercises)) {
    l.exercises.forEach(ex => {
      if (ex.questions && Array.isArray(ex.questions)) {
        list = list.concat(ex.questions);
      }
    });
  }
  return list;
}

function submitReport(question, errorType, comment, screenshot) {
  let reports;
  try {
    reports = JSON.parse(localStorage.getItem('amok_question_reports') || '[]');
  } catch (e) {
    console.error('Rapor veritabanı bozuk, sıfırlanıyor:', e);
    reports = [];
  }
  const questionLesson = (typeof lessons !== 'undefined') ? lessons.find(l => getLessonQuestions(l).some(q => q.id === question.id)) : null;
  const activeLesson = questionLesson || currentLesson;
  const lessonTitleStr = activeLesson ? (activeLesson.subtitle ? `${activeLesson.id}. Ders (${activeLesson.subtitle})` : (activeLesson.title || `${activeLesson.id}. Ders`)) : (isReviewMode ? 'Hızlı Tekrar' : 'N/A');
  const lessonIdStr = activeLesson ? activeLesson.id : 'N/A';

  const newReport = {
    id: "rep_" + Date.now(),
    timestamp: new Date().toLocaleString('tr-TR'),
    createdAt: new Date().toISOString(),
    lessonId: lessonIdStr,
    lessonTitle: lessonTitleStr,
    questionId: question.id,
    questionPrompt: question.prompt || question.sentence || 'Görsel / Eşleştirme',
    questionType: question.type,
    errorType: errorType,
    userComment: comment,
    username: state.username || 'Misafir',
    screenshot: screenshot || null
  };

  reports.push(newReport);
  // Ekran görüntüleri base64 olarak yer kapladığından localStorage kotası
  // dolabilir; dolarsa eski raporların görüntülerini düşürüp yeniden dene.
  try {
    localStorage.setItem('amok_question_reports', JSON.stringify(reports));
  } catch (quotaErr) {
    console.warn('Rapor kaydı kota aşımı, eski ekran görüntüleri temizleniyor:', quotaErr);
    for (let i = 0; i < reports.length - 1; i++) reports[i].screenshot = null;
    try {
      localStorage.setItem('amok_question_reports', JSON.stringify(reports));
    } catch (quotaErr2) {
      newReport.screenshot = null;
      localStorage.setItem('amok_question_reports', JSON.stringify(reports));
    }
  }

  if (supabaseClient) {
    const baseRow = {
      username: newReport.username,
      lesson_id: newReport.lessonId,
      lesson_title: newReport.lessonTitle,
      question_id: newReport.questionId,
      question_prompt: newReport.questionPrompt,
      question_type: newReport.questionType,
      error_type: newReport.errorType,
      user_comment: newReport.userComment
    };
    try {
      supabaseClient
        .from('question_reports')
        .insert([newReport.screenshot ? { ...baseRow, screenshot: newReport.screenshot } : baseRow])
        .then(({ error }) => {
          if (error && newReport.screenshot) {
            // `screenshot` kolonu yoksa satırı görüntüsüz tekrar dene.
            console.warn('Supabase rapor kaydı (ekran görüntülü) başarısız, görüntüsüz deneniyor:', error);
            return supabaseClient.from('question_reports').insert([baseRow]);
          }
          if (error) console.error('Supabase error saving report:', error);
        })
        .then(res => {
          if (res && res.error) console.error('Supabase error saving report (fallback):', res.error);
        })
        .catch(err => {
          console.error('Supabase insert promise rejection in submitReport:', err);
        });
    } catch (dbErr) {
      console.error('Supabase insert exception in submitReport:', dbErr);
    }
  }
  
  // E-posta bildirimi gönder
  sendReportEmail(newReport, question);
  
  showToast('Hata bildiriminiz gönderildi. Teşekkür ederiz! 🙏', 'success');
}

function sendReportEmail(report, question) {
  if (typeof OBFUSCATED_EMAIL === 'undefined' || !OBFUSCATED_EMAIL) return;

  try {
    // Decode the Base64 email address to keep it hidden in source code
    const emailAddress = atob(OBFUSCATED_EMAIL);
    
    // FormSubmit AJAX API endpoint
    const url = `https://formsubmit.co/ajax/${emailAddress}`;
    
    // Generate AI Prompt
    const qClean = question ? { ...question } : {};
    delete qClean._dynamicType;
    
    const aiPrompt = `[HATA BİLDİRİMİ - YAPAY ZEKA GELİŞTİRİCİ PROMPTU]
Lütfen aşağıdaki sorudaki hatayı düzelt:

- Ders Bilgisi: ${report.lessonTitle}
- Soru ID: ${report.questionId}
- Soru Türü: ${report.questionType}
- Bildirilen Hata Türü: ${translateErrorType(report.errorType)}
- Kullanıcı Açıklaması: "${report.userComment}"

Mevcut Soru Verisi (JSON):
${JSON.stringify(qClean, null, 2)}

Yapılması Gerekenler:
1. data.js dosyasında "${report.questionId}" ID'li soruyu bulun.
2. Kullanıcının belirttiği "${report.userComment}" açıklamasını inceleyip hatayı (çeviri, imla, yanlış cevap anahtarı veya seçenekler) düzeltin.
3. Sorudaki gerekli alanları (en, tr, options, word, trWord, correctIndex vb.) güncelleyip dosyayı kaydedin.`;

    const body = {
      _subject: `AMOK Soru Hata Bildirimi - ${report.lessonTitle}`,
      "Ders Bilgisi": report.lessonTitle,
      "Soru ID": report.questionId,
      "Soru Türü": report.questionType,
      "Soru Metni": report.questionPrompt,
      "Hata Türü": translateErrorType(report.errorType),
      "Kullanıcı Açıklaması": report.userComment,
      "Ekran Görüntüsü": report.screenshot ? 'Var (admin panelinde görüntülenebilir)' : 'Yok',
      "Yapay Zeka Hazır Promptu (AI Ready Prompt)": aiPrompt,
      "Bildiren Kullanıcı": report.username,
      "Bildirim Zamanı": report.timestamp
    };

    fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(body)
    })
    .then(response => {
      if (!response.ok) {
        console.error('Email API returned non-ok status');
      }
    })
    .catch(error => {
      console.error('Error sending email request:', error);
    });
  } catch (err) {
    console.error('Error decoding obfuscated email:', err);
  }
}

function sendLicenceRequestEmail(username, adSoyad, email, tel) {
  try {
    const url = 'https://formsubmit.co/ajax/f94120015@gmail.com';
    const body = {
      _subject: `AMOK Lisans Talebi - ${username}`,
      "Ad Soyad": adSoyad || 'Belirtilmemiş',
      "Kullanıcı Adı": username || 'Belirtilmemiş',
      "E-posta": email || 'Belirtilmemiş',
      "Telefon": tel || 'Belirtilmemiş',
      "Talep Zamanı": new Date().toLocaleString('tr-TR')
    };

    fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(body)
    })
    .then(response => {
      if (!response.ok) {
        console.error('Licence request email API returned non-ok status');
      }
    })
    .catch(error => {
      console.error('Error sending licence request email:', error);
    });
  } catch (err) {
    console.error('Error sending licence request email:', err);
  }
}

